Object.assign(window.TEM8_DICTIONARY, {"church":{"media":{"uk":"media/uk/church__gb_1.mp3","us":"media/us/church__us_1.mp3"},"oxford":{"phon":"tʃɜːtʃ","pos":"noun","senses":[{"en":"a building where Christians go to attend services, pray, etc.","cn":"（基督教的）教堂，礼拜堂","g":"[countable]","ex":{"en":"The procession moved into the church.","cn":"人们排着队走进教堂。"}},{"en":"a service or services in a church","cn":"礼拜；礼拜仪式","g":"[uncountable]","lab":"British English","ex":{"en":"How often do you go to church?","cn":"你多久去教堂做一次礼拜？"}},{"en":"a particular group of Christians","cn":"基督教教派","g":"[countable]","ex":{"en":"the Anglican Church","cn":"圣公会"}},{"en":"the ministers of the Christian religion; the institution of the Christian religion","cn":"基督教牧师；基督教机构","g":"[singular]","ex":{"en":"The Church has a duty to condemn violence.","cn":"基督教会有义务谴责暴力。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(基督)教堂;礼拜堂","en":"A church is a building in which Christians worship. You usually refer to this place as church when you are talking about the time that people spend there.","ex":{"en":"...one of Britain's most historic churches.","cn":"英国最古老的教堂之一"}},{"pos":"N-COUNT 可数名词","cn":"(基督教的)教派","en":"A Church is one of the groups of people within the Christian religion, for example Catholics or Methodists, that have their own beliefs, clergy, and forms of worship.","ex":{"en":"...co-operation with the Catholic Church","cn":"和天主教派的合作"}},{"pos":"PHRASE 短语","cn":"广纳众议的机构（或团体）；兼收并蓄的活动","en":"You can refer to an organization, group, or area of activity as a broad church when it includes a wide range of opinions, beliefs, or styles.","ex":{"en":"The party has responded by trying to become a broad church that appeals to devout pensioners, Munich punks and aerospace engineers","cn":"该党的反应是要努力成为一个吸引笃信宗教的退休者、慕尼黑朋客族和航天工程师的兼收并蓄的政党。"}}]},"examples":[{"en":"How often do you go to church?","cn":"你多久去教堂做一次礼拜？"},{"en":"Church is at 9 o'clock.","cn":"礼拜仪式 9 点钟开始。"}]},"chooses":{"oxford":{"phon":"tʃuːz","pos":"verb","senses":[{"en":"to decide which thing or person you want out of the ones that are available","cn":"选择；挑选；选取"},{"en":"to prefer or decide to do sth","cn":"宁愿；情愿；决定"}]},"media":{"uk":"media/uk/choose__gb_1.mp3","us":"media/us/choose__us_1.mp3"}},"chose":{"collins":{"senses":[{"pos":"","cn":"","en":"Chose is the past tense of choose."}]},"media":{"uk":"media/uk/chose__gb_1.mp3","us":"media/us/chose__us_1.mp3"}},"chatter":{"media":{"uk":"media/uk/chatter__gb_1.mp3","us":"media/us/chatter__us_1.mp3"},"oxford":{"phon":"ˈtʃætə(r)","pos":"verb","senses":[{"en":"to talk quickly and continuously, especially about things that are not important","cn":"喋喋不休；唠叨；饶舌","g":"[intransitive]","ex":{"en":"They chattered away happily for a while.","cn":"他们高兴地闲扯了一会儿。"}},{"en":"to knock together continuously because you are cold or frightened","cn":"（因冷或害怕）打颤","g":"[intransitive]","ex":{"en":"Her teeth chattered as she dressed.","cn":"她穿衣服时牙齿打战。"}},{"en":"to make a series of short high sounds","cn":"鸣叫；啁啾；唧唧叫；吱吱叫","g":"[intransitive]","ex":{"en":"The only sounds we could hear were the birds chattering in the trees.","cn":"我们唯一能听到的声音是鸟儿在树上叽叽喳喳的声音。"}},{"en":"continuous rapid talk about things that are not important","cn":"唠叨的话；喋喋不休","ex":{"en":"Jane's constant chatter was beginning to annoy him.","cn":"简无休止的唠叨开始使他心烦。"},"pos":"noun"},{"en":"a series of quick short high sounds that some animals make","cn":"鸣叫声；啼啭声；吱吱叫声","ex":{"en":"the chatter of monkeys","cn":"猴子的吱吱叫声"},"pos":"noun"},{"en":"a series of short sounds made by things knocking together","cn":"碰击声；咯咯声；打颤声","ex":{"en":"the chatter of teeth","cn":"牙齿打颤的咯咯声"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"唠叨;喋喋不休","en":"If you chatter, you talk quickly and continuously, usually about things which are not important.","ex":{"en":"Everyone's chattering away in different languages","cn":"大家操着不同的语言喋喋不休地说着。"}},{"pos":"VERB 动词","cn":"(牙齿)打战，咯咯响","en":"If your teeth chatter, they keep knocking together because you are very cold or very nervous.","ex":{"en":"She was so cold her teeth chattered.","cn":"她冻得牙齿咯咯响。"}},{"pos":"VERB 动词","cn":"发出咯咯声(或嗒嗒声)","en":"If objects chatter, they make short repeated sounds.","ex":{"en":"The telex chattered all day and night with news bulletins.","cn":"电传机没日没夜“嗒嗒嗒”地接收新闻稿。"}},{"pos":"VERB 动词","cn":"(鸟)鸣叫，啁啾;(动物)唧唧叫，吱吱叫","en":"When birds or animals chatter, they make high-pitched noises.","ex":{"en":"Birds were chattering somewhere.","cn":"鸟儿在某处唧唧喳喳地叫着。"}}]},"examples":[{"en":"The children chattered to each other excitedly about the next day's events.","cn":"孩子们很兴奋，没完没了地谈论着第二天的活动。"},{"en":"Jane's constant chatter was beginning to annoy him.","cn":"简无休止的唠叨开始使他心烦。"}]},"check":{"media":{"uk":"media/uk/check__gb_1.mp3","us":"media/us/check__us_1.mp3"},"oxford":{"phon":"tʃek","pos":"verb","senses":[{"en":"to examine something to see if it is correct, safe or acceptable","cn":"检查；审查；核查；检验","g":"[transitive]","sc":"examine","ex":{"en":"She gave me the minutes of the meeting to read and check.","cn":"她把会议记录交给我审阅。"}},{"en":"to look at something or ask somebody to find out if something/somebody is present, correct or true or if something is how you think it is","cn":"查明；查看；核实；弄确实","g":"[intransitive, transitive]","sc":"make sure","ex":{"en":"We'll check back in a couple of hours.","cn":"我们过几个小时会复查。"}},{"en":"to put a mark (✓) next to an item on a list, an answer, etc.","cn":"标记号；打上钩；打对号","g":"[transitive]","lab":"especially North American English","sc":"make mark","ex":{"en":"Check the box next to the right answer.","cn":"在正确答案旁边的方框中打钩。"}},{"en":"to control something; to stop something from increasing or getting worse","cn":"控制；抑制；阻止","g":"[transitive]","sc":"control","ex":{"en":"The government is determined to check the growth of public spending.","cn":"政府决心要控制公共开支的增长。"}},{"en":"to stop yourself from saying or doing something or from showing a particular emotion","cn":"克制，抑制（做某事或表露感情）","g":"[transitive]","sc":"control","ex":{"en":"to check your anger/laughter/tears","cn":"忍住怒火／笑／眼泪"}},{"en":"to leave coats, bags, etc. in an official place (called a checkroom) while you are visiting a club, restaurant, etc.","cn":"存放；寄放","g":"[transitive]","lab":"North American English","sc":"coats/bags/cases","ex":{"en":"Do you want to check your coats?","cn":"你们要寄放外套吗？"}},{"en":"to leave bags or cases with an official so that they can be put on a plane or train","cn":"托运（行李）","g":"[transitive]","lab":"North American English","sc":"coats/bags/cases","ex":{"en":"How many bags are you checking?","cn":"您要托运多少件行李？"}},{"en":"an act of making sure that something is safe, correct or in good condition by examining it","cn":"检查；查看；检验","g":"[countable]","sc":"examination","ex":{"en":"Could you give the tyres a check?","cn":"你能检查一下轮胎吗？"},"pos":"noun"},{"en":"an investigation to find out more information about somebody/something","cn":"调查；审查","g":"[countable]","sc":"investigation","ex":{"en":"The agency insisted all the necessary background checks had been carried out.","cn":"该机构坚称已完成所有必要的背景调查。"},"pos":"noun"},{"en":"a mark (✓) put next to a sum or an item on a list, usually to show that it has been checked or done or is correct","cn":"核对号；对号；钩号","g":"[countable]","lab":"both especially North American English","sc":"mark","ex":{"en":"The teacher put a check next to his name.","cn":"老师在他的名字旁边打了钩。"},"pos":"noun"},{"en":"a piece of paper that shows how much you have to pay for the food and drinks that you have had in a restaurant","cn":"（餐馆的）账单","g":"[countable]","lab":"North American English","sc":"money","ex":{"en":"Can I have the check, please?","cn":"请给我结账。"},"pos":"noun"},{"en":"a printed form that you can write on and sign as a way of paying for something instead of using money","cn":"支票","g":"[countable]","lab":"US English","sc":"money","pos":"noun"},{"en":"something that delays the progress of something else or stops it from getting worse","cn":"阻碍进程的事物；阻止恶化的事物","g":"[countable]","lab":"formal","sc":"control","ex":{"en":"A cold spring will provide a natural check on the number of insects.","cn":"寒冷的春季会自然控制昆虫的数量。"},"pos":"noun"},{"en":"rules that are designed to control the amount of power, especially political power, that one person or group has","cn":"（对政治等权力的）规定，条令，约束","g":"[plural]","lab":"formal","sc":"control","pos":"noun"},{"en":"a pattern of squares, usually of two colours","cn":"（通常指双色的）方格图案，方格，格子","g":"[countable, uncountable]","sc":"pattern","ex":{"en":"Do you prefer checks or stripes?","cn":"你喜欢方格还是条纹？"},"pos":"noun"},{"en":"a place in a club, restaurant, etc. where you can leave your coat or bag","cn":"（俱乐部、餐馆等外套、包的）寄存处，存放处","g":"[countable]","lab":"North American English","sc":"for coats/bags","pos":"noun"},{"en":"a ticket that you get when you leave your coat, bag, etc. in, for example, a restaurant or theatre","cn":"（餐馆或剧院等的）存物牌，存放证","g":"[countable]","lab":"North American English","sc":"for coats/bags","pos":"noun"},{"en":"a position in which a player’s king (= the most important piece) can be directly attacked by the other player’s pieces","cn":"被将军的局面","g":"[uncountable]","sc":"in game","ex":{"en":"There, you're in check.","cn":"瞧，将你一军。"},"pos":"noun"},{"en":"used to show that you agree with somebody or that something on a list has been dealt with","cn":"行；已经办好","ex":{"en":"‘Do you have your tickets?’ ‘Check.’ ‘Passport?’ ‘Check.’","cn":"“你有票吗？”“有。”“护照呢？”“有。”"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"检查;审查;核实","en":"If you check something such as a piece of information or a document, you make sure that it is correct or satisfactory.","ex":{"en":"Check the accuracy of everything in your CV","cn":"请核对简历中的每个细节，务必准确无误。"}},{"pos":"VERB 动词","cn":"检查，查看(以确保一切正常)","en":"If you check on someone or something, you make sure they are in a safe or satisfactory condition.","ex":{"en":"Stephen checked on her several times during the night","cn":"斯蒂芬夜里起来看了她好几遍。"}},{"pos":"VERB 动词","cn":"在…上打钩（以确定其正确、已选定或已处理）","en":"If you check something that is written on a piece of paper, you put a mark, like a V with the right side extended, next to it to show that something is correct or has been selected or dealt with.","ex":{"en":"Frequently, men who check answer (b) have not actually had the experience of being repeatedly rejected by women.","cn":"多数情况下，选(b)的男人没有真的尝过三番五次被女人拒绝的滋味。"}},{"pos":"VERB 动词","cn":"控制;防止;抑制","en":"To check something, usually something bad, means to stop it from spreading or continuing.","ex":{"en":"Sex education is also expected to help check the spread of AIDS.","cn":"人们还希望性教育有助于控制艾滋病的蔓延。"}},{"pos":"VERB 动词","cn":"(使)突然停下;(使)停住","en":"If you check yourself or if something checks you, you suddenly stop what you are doing or saying.","ex":{"en":"He was about to lose his temper but checked himself in time","cn":"他刚要发火，不过又及时克制住了。"}},{"pos":"VERB 动词","cn":"托运(行李)","en":"When you check your luggage at an airport, you give it to an official so that it can be taken on to your plane.","ex":{"en":"We arrived at the airport, checked our baggage and wandered around the gift shops","cn":"我们到了机场，托运了行李，到礼品店里逛了逛。"}},{"pos":"N-COUNT 可数名词","cn":"(餐馆的)结账单","en":"The check in a restaurant is a piece of paper on which the price of your meal is written and which you are given before you pay."},{"pos":"CONVENTION 惯用语","cn":"(国际象棋中)“将军”","en":"In a game of chess, you say check when you are attacking your opponent's king."},{"pos":"N-COUNT 可数名词","cn":"(通常为两种颜色的)方格图案，格子图案","en":"A pattern of squares, usually of two colours, can be referred to as checks or a check .","ex":{"en":"Styles include stripes and checks.","cn":"款式包括条纹的和格子的。"}},{"pos":"PHRASE 短语","cn":"受到控制的；被控制住的","en":"If something or someone is held in check or is kept in check, they are controlled and prevented from becoming too great or powerful.","ex":{"en":"Life on Earth will become unsustainable unless population growth is held in check","cn":"人口增长要是不加控制的话，地球上的生命将无法持续发展。"}},{"pos":"","cn":"同 cheque","en":"A check is the same as a cheque ."},{"pos":"","cn":"","en":"相关词组：check in check off check out check up"}]},"examples":[{"en":"She wanted to tell him the whole truth but she checked herself — it wasn't the right moment.","cn":"她本想告诉他全部真相，但是又忍住了，当时还不是时候。"},{"en":"He checked into a top London clinic yesterday for an operation on his knee.","cn":"他昨天住进了伦敦一家最高级的诊所，准备做膝部手术。"}]},"chances":{"oxford":{"phon":"tʃɑːns","pos":"noun","senses":[{"en":"a possibility of sth happening, especially sth that you want （","cn":"尤指希望发生的事的）可能性"},{"en":"a suitable time or situation when you have the opportunity to do sth","cn":"机会；机遇；时机"}]},"media":{"uk":"media/uk/chance__gb_1.mp3","us":"media/us/chance__us_1.mp3"}},"chew":{"oxford":{"phon":"tʃuː","pos":"verb","senses":[{"en":"to bite food into small pieces in your mouth with your teeth to make it easier to swallow","cn":"咀嚼；嚼碎","g":"[intransitive, transitive]","ex":{"en":"After the operation you may find it difficult to chew and swallow.","cn":"手术后你咀嚼和吞咽可能会感到困难。"}},{"en":"to bite something continuously, for example because you are nervous or to taste it","cn":"（因为紧张等）咬住，不停地啃；（为尝味道）不停地咀嚼","g":"[intransitive, transitive]","ex":{"en":"Rosa chewed on her lip and stared at the floor.","cn":"罗莎咬着嘴唇，眼睛盯着地板。"}},{"en":"an act of chewing something","cn":"咀嚼","pos":"noun"},{"en":"a type of sweet that you chew","cn":"口香糖","pos":"noun"},{"en":"a piece of tobacco that you chew","cn":"供嚼用的烟草","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"咀嚼;嚼(碎)","en":"When you chew food, you use your teeth to break it up in your mouth so that it becomes easier to swallow.","ex":{"en":"Be certain to eat slowly and chew your food extremely well","cn":"一定要慢慢吃，要细细咀嚼。"}},{"pos":"VERB 动词","cn":"嚼(口香糖、烟草)","en":"If you chew gum or tobacco, you keep biting it and moving it around your mouth to taste the flavour of it. You do not swallow it.","ex":{"en":"One girl was chewing gum","cn":"一个女孩在嚼口香糖。"}},{"pos":"VERB 动词","cn":"(因为紧张)咬(嘴唇、指甲)","en":"If you chew your lips or your fingernails, you keep biting them because you are nervous.","ex":{"en":"He chewed his lower lip nervously.","cn":"他紧张地咬着下嘴唇。"}},{"pos":"VERB 动词","cn":"(人或动物)咬，啃","en":"If a person or animal chews an object, they bite it with their teeth.","ex":{"en":"They pause and chew their pencils","cn":"他们停了下来，咬着铅笔。"}},{"pos":"N-COUNT 可数名词","cn":"口嚼糖","en":"A chew is a sweet that you have to chew very hard before it becomes soft.","ex":{"en":"...a selection of penny chews.","cn":"各式各样可供选择的便宜口嚼糖"}},{"pos":"PHRASE 短语","cn":"试图承担力不能及的事","en":"If you say that someone has bitten off more than they can chew, you mean that they are trying to do something which is too difficult for them.","ex":{"en":"Micky is used to handling dodgy deals but this time fears he may have bitten off more than he can chew.","cn":"米基本来是善于处理棘手交易的，可是这回他可能会力有不逮。"}},{"pos":"PHR-RECIP 相互短语","cn":"闲聊;闲扯","en":"If people chew the fat, they talk in a relaxed, informal way.","ex":{"en":"We'd been lounging around, chewing the fat for a couple of hours.","cn":"我们东游西逛，瞎扯了两三个钟头。"}},{"pos":"","cn":"","en":"to chew the cud→see: ;"},{"pos":"","cn":"","en":"相关词组：chew out chew over chew up"}]},"media":{"uk":"media/uk/chew__gb_2.mp3","us":"media/us/chew__us_2.mp3"},"examples":[{"en":"After the operation you may find it difficult to chew and swallow.","cn":"手术后你咀嚼和吞咽可能会感到困难。"},{"en":"Rosa chewed on her lip and stared at the floor.","cn":"罗莎咬着嘴唇，眼睛盯着地板。"}]},"chariot":{"media":{"uk":"media/uk/chariot__gb_1.mp3","us":"media/us/chariot__us_1.mp3"},"oxford":{"phon":"ˈtʃæriət","pos":"noun","senses":[{"en":"an open vehicle with two wheels, pulled by horses, used in ancient times in battle and for racing","cn":"（古代用于战斗或比赛的）双轮敞篷马车"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(古代的)双轮马车","en":"In ancient times, chariots were fast-moving vehicles with two wheels that were pulled by horses."}]}},"chemicals":{"oxford":{"phon":"ˈkemɪkl","pos":"adjective","senses":[{"en":"connected with chemistry","cn":"与化学有关的；化学的"},{"en":"produced by or using processes which involve changes to atoms or molecules","cn":"用化学方法制造的；化学作用的"}]}},"chin":{"oxford":{"phon":"tʃɪn","pos":"noun","senses":[{"en":"the part of the face below the mouth and above the neck","cn":"颏；下巴","lab":"informal","ex":{"en":"A strap fastens under the chin to keep the helmet in place.","cn":"一条带子固定在下巴下方，以将头盔固定到位。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"颏;下巴","en":"Your chin is the part of your face that is below your mouth and above your neck.","ex":{"en":"...a double chin","cn":"双下巴"}},{"pos":"PHRASE 短语","cn":"坦然面对，欣然接受(令人不快或困难的局面)","en":"If you say that someone took something on the chin, you mean that they accepted an unpleasant or difficult situation bravely and without making a lot of fuss about it.","ex":{"en":"When the police arrived he took it on the chin and apologised for the trouble he'd caused them.","cn":"警察赶来时，他坦然为自己给他们造成的麻烦表示歉意。"}}]},"media":{"uk":"media/uk/chin__gb_1.mp3","us":"media/us/chin__us_1.mp3"},"examples":[{"en":"Chin up! Only two exams left.","cn":"别泄气！只剩下两门考试了。"},{"en":"He rubbed his chin thoughtfully.","cn":"他若有所思地抚摸着下巴。"}]},"chance":{"media":{"uk":"media/uk/chance__gb_1.mp3","us":"media/us/chance__us_1.mp3"},"oxford":{"phon":"tʃɑːns","pos":"noun","senses":[{"en":"a possibility of something happening, especially something that you want","cn":"（尤指希望发生的事的）可能性","g":"[countable, uncountable]","ex":{"en":"She only has a slim chance of passing the exam.","cn":"她通过考试的希望很渺茫。"}},{"en":"a suitable time or situation when you have the opportunity to do something","cn":"机会；机遇；时机","g":"[countable]","ex":{"en":"It was the chance she had been waiting for.","cn":"那正是她一直等待的机会。"}},{"en":"an unpleasant or dangerous possibility","cn":"风险；冒险","g":"[countable]","ex":{"en":"When installing electrical equipment don't take any chances. A mistake could kill.","cn":"安装电器设备时千万不要冒险，一个失误就可能要人命。"}},{"en":"the way that some things happen without any cause that you can see or understand","cn":"偶然；碰巧；意外","g":"[uncountable]","ex":{"en":"I met her by chance (= without planning to) at the airport.","cn":"我碰巧在机场遇见她。"}},{"en":"to risk something, although you know the result may not be successful","cn":"冒险；拿…去冒风险","g":"[transitive]","lab":"informal","ex":{"en":"She was chancing her luck driving without a licence.","cn":"她无照驾车，完全是在冒险。"},"pos":"verb"},{"en":"to happen or to do something by chance","cn":"偶然发生；碰巧","lab":"formal","ex":{"en":"If I do chance to find out where she is, I'll inform you immediately.","cn":"要是我真的碰巧发现她的行踪，会立即通知你的。"},"pos":"verb"},{"en":"not planned","cn":"意外的；偶然的；碰巧的","ex":{"en":"a chance meeting/encounter","cn":"邂逅"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"可能(性);机会","en":"If there is a chance of something happening, it is possible that it will happen.","ex":{"en":"Do you think they have a chance of beating Australia?","cn":"你认为他们有可能击败澳大利亚吗？"}},{"pos":"N-COUNT 可数名词","cn":"机会;机遇","en":"If you have a chance to do something, you have the opportunity to do it.","ex":{"en":"The electoral council announced that all eligible people would get a chance to vote","cn":"选举委员会宣布，所有有资格者都将获得投票的机会。"}},{"pos":"ADJ 形容词","cn":"偶然的;意外的;凑巧的","en":"A chance meeting or event is one that is not planned or expected.","ex":{"en":"...a chance meeting.","cn":"偶遇"}},{"pos":"VERB 动词","cn":"碰巧(做);偶然发现","en":"If you chance to do something or chance on something, you do it or find it although you had not planned or tried to.","ex":{"en":"A man I chanced to meet proved to be a most unusual character","cn":"我邂逅了一个人，后来发现他是个极为与众不同的家伙。"}},{"pos":"VERB 动词","cn":"冒…的险","en":"If you chance something, you do it even though there is a risk that you may not succeed or that something bad may happen.","ex":{"en":"Andy knew the risks. I cannot believe he would have chanced it","cn":"安迪知道有风险，我不敢相信他竟然甘冒其险。"}},{"pos":"PHRASE 短语","cn":"偶然;碰巧","en":"Something that happens by chance was not planned by anyone.","ex":{"en":"He had met Mr Maude by chance.","cn":"他曾邂逅过莫德先生。"}},{"pos":"PHRASE 短语","cn":"(用以询问某事是否属实)会不会，可能","en":"You can use by any chance when you are asking questions in order to find out whether something that you think might be true is actually true.","ex":{"en":"Are they by any chance related?","cn":"他们有可能是亲戚吗？"}},{"pos":"PHRASE 短语","cn":"有可能;有机会","en":"If you say that someone stands a chance of achieving something, you mean that they are likely to achieve it. If you say that someone doesn't stand a chance of achieving something, you mean that they cannot possibly achieve it.","ex":{"en":"Being very good at science subjects, I stood a good chance of gaining high grades","cn":"我理科很棒，所以很有机会拿高分。"}},{"pos":"PHRASE 短语","cn":"冒险;碰运气","en":"When you take a chance, you try to do something although there is a large risk of danger or failure.","ex":{"en":"You take a chance on the weather if you holiday in the UK","cn":"在英国度假，只有赌天气了。"}}]},"examples":[{"en":"When installing electrical equipment don't take any chances. A mistake could kill.","cn":"安装电器设备时千万不要冒险，弄错了有可能出人命的。"},{"en":"We took a chance on the weather and planned to have the party outside.","cn":"我们怀着天气可能会好的侥幸心理筹划到户外聚会。"}]},"chest":{"media":{"uk":"media/uk/chest__gb_1.mp3","us":"media/us/chest__us_1.mp3"},"oxford":{"phon":"tʃest","pos":"noun","senses":[{"en":"the top part of the front of the body, between the neck and the stomach","cn":"胸部；胸膛","lab":"informal","ex":{"en":"chest pains","cn":"胸部疼痛"}},{"en":"having the type of chest mentioned","cn":"有…胸的；胸部…的","ex":{"en":"flat-chested","cn":"胸部扁平的"}},{"en":"a large strong box, usually made of wood, used for storing things in and/or moving them from one place to another","cn":"（常为木制的）大箱子","ex":{"en":"a medicine chest","cn":"药箱"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胸;胸部;胸口;胸膛","en":"Your chest is the top part of the front of your body where your ribs, lungs, and heart are.","ex":{"en":"He crossed his arms over his chest","cn":"他双手交叉，放在胸前。"}},{"pos":"N-COUNT 可数名词","cn":"大箱子；大柜子","en":"A chest is a large, heavy box used for storing things.","ex":{"en":"At the very bottom of the chest were his carving tools.","cn":"箱子最底下是他的雕刻工具。"}},{"pos":"PHRASE 短语","cn":"倾诉胸中的不快;吐苦水","en":"If you get something off your chest, you talk about something that has been worrying you.","ex":{"en":"I feel it's done me good to get it off my chest.","cn":"我感觉吐吐苦水对我有好处。"}}]},"examples":[{"en":"She gasped for breath, her chest heaving.","cn":"她喘着气，胸部不停地起伏。"},{"en":"The bullet hit him in the chest.","cn":"子弹击中了他的胸部。"}]},"charming":{"media":{"uk":"media/uk/charming__gb_1.mp3","us":"media/us/charming__us_1.mp3"},"oxford":{"phon":"ˈtʃɑːmɪŋ","pos":"adjective","senses":[{"en":"very pleasant or attractive","cn":"令人着迷的；迷人的；吸引人的","ex":{"en":"The cottage is tiny, but it's charming.","cn":"这间村舍虽小，却十分迷人。"}},{"en":"used to show that you have a low opinion of somebody’s behaviour","cn":"（表示对某人的行为评价不高）真是太好了","lab":"ironic, informal，，","ex":{"en":"They left me to tidy it all up myself. Charming, wasn't it?","cn":"他们留下我一个人来收拾这一切。真是照顾我呢，不是吗？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可爱的;迷人的;美丽的","en":"If you say that something is charming, you mean that it is very pleasant or attractive.","ex":{"en":"...a charming little fishing village.","cn":"迷人的小渔村"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"和蔼可亲的;富有魅力的;讨人喜爱的","en":"If you describe someone as charming, you mean they behave in a friendly, pleasant way that makes people like them.","ex":{"en":"...a charming young man","cn":"讨人喜欢的小伙子"}},{"pos":"CONVENTION 惯用语","cn":"(对于别人的粗鲁行为或听到他人劣迹时表示不赞同)岂有此理！","en":"You can say 'Charming!' to indicate your disapproval when someone has just been rude to you or told you about someone's bad behaviour.","ex":{"en":"'I'm glad I'm not going with you, that's for sure.' — 'Oh, charming!'","cn":"“我非常高兴不和你同去，真的。”——“好哇，有种！”"}}]},"examples":[{"en":"They left me to tidy it all up myself. Charming, wasn't it?","cn":"他们留下我一个人来收拾这一切。真是照顾我哟，不是吗？"},{"en":"The cottage is tiny, but it's charming.","cn":"这间村舍虽小，却十分迷人。"}]},"chief":{"media":{"uk":"media/uk/chief__gb_1.mp3","us":"media/us/chief__us_1.mp3"},"oxford":{"phon":"tʃiːf","pos":"adjective","senses":[{"en":"most important","cn":"最重要的；首要的；主要的","g":"[only before noun]","ex":{"en":"the chief cause/problem/reason","cn":"主要原因／问题／理由"}},{"en":"highest in rank","cn":"最高级别的；为首的；首席的","g":"[only before noun]","ex":{"en":"the chief economist at the World Bank","cn":"世界银行首席经济学家"}},{"en":"of the highest rank","cn":"最高级别的；为首的","ex":{"en":"commander-in-chief","cn":"总司令；最高统帅"}},{"en":"a person with a high rank or the highest rank in a company or an organization","cn":"（公司或机构的）首领，头目，最高领导人","ex":{"en":"army/police chiefs","cn":"部队首长；警察首脑"},"pos":"noun"},{"en":"a leader of a people or community","cn":"首领；酋长；族长","ex":{"en":"Chief Buthelezi","cn":"布特莱齐酋长"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(组织机构的)负责人，头儿，首领","en":"The chief of an organization is the person who is in charge of it.","ex":{"en":"...a commission appointed by the police chief.","cn":"警察局局长任命的委员会"}},{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"酋长;部落首领","en":"The chief of a tribe is its leader.","ex":{"en":"...Sitting Bull, chief of the Sioux tribes of the Great Plains.","cn":"坐牛，大平原地区苏人部族的酋长"}},{"pos":"ADJ 形容词","cn":"(用于职位头衔)主管的，首席的","en":"Chief is used in the job titles of the most senior worker or workers of a particular kind in an organization.","ex":{"en":"...the chief test pilot.","cn":"首席试飞员"}},{"pos":"ADJ 形容词","cn":"主要的;最重要的","en":"The chief cause, part, or member of something is the most important one.","ex":{"en":"Financial stress is well established as a chief reason for divorce","cn":"经济压力被确认是导致离婚的首要原因。"}}]},"examples":[{"en":"one of the President's chief rivals","cn":"总统的主要政敌之一"},{"en":"the chief financial officer of the company","cn":"公司的首席财务官"}]},"channel":{"oxford":{"phon":"ˈtʃænl","pos":"noun","senses":[{"en":"a television station","cn":"电视台","g":"[countable]","lab":"British English","sc":"on television/radio","ex":{"en":"a television/TV channel","cn":"电视频道"}},{"en":"a band of radio waves used for making television or radio broadcasts","cn":"频道；波段","g":"[countable]","sc":"on television/radio","ex":{"en":"radio channels","cn":"无线电信道"}},{"en":"a method or system that people use to get information, to communicate, or to send something somewhere","cn":"途径；渠道；系统","g":"[countable]","sc":"for communicating","ex":{"en":"Complaints must be made through the proper channels.","cn":"投诉必须通过正当途径进行。"}},{"en":"a means by which data is communicated and exchanged between elements of a computer system or other system","cn":"（计算机数据的）通道","g":"[countable]","sc":"for communicating","ex":{"en":"an audio channel","cn":"音频通道"}},{"en":"a way of expressing ideas and feelings","cn":"（表达的）方式，方法，手段","g":"[countable]","sc":"for ideas/feelings","ex":{"en":"The campaign provided a channel for protest against the war.","cn":"这场运动是反对战争的一种方式。"}},{"en":"a passage that water can flow along, especially in the ground, on the bottom of a river, etc.","cn":"水渠；沟渠；河槽","g":"[countable]","sc":"water","ex":{"en":"drainage channels in the rice fields","cn":"稻田的排水沟"}},{"en":"a deep passage of water in a river or near the coast that can be used as route for ships","cn":"水道；航道","g":"[countable]","sc":"water"},{"en":"a passage of water that connects two areas of water, especially two seas","cn":"海峡","g":"[countable]","sc":"water","ex":{"en":"the Bristol Channel","cn":"布里斯托尔海峡"}},{"en":"the area of sea between England and France, also known as the English Channel","cn":"英吉利海峡","g":"[singular]","sc":"water","ex":{"en":"the Channel Tunnel","cn":"英吉利海峡隧道"}},{"en":"to direct money, feelings, ideas, etc. towards a particular thing or purpose","cn":"为…引资；引导；贯注","sc":"ideas/feelings","ex":{"en":"He channels his aggression into sport.","cn":"他把他的好斗劲头倾注于体育比赛之中。"},"pos":"verb"},{"en":"to send money, help, etc. using a particular route","cn":"（利用某途径）输送资金，提供帮助","sc":"money/help","ex":{"en":"Money for the project will be channelled through local government.","cn":"这个项目的资金将由地方政府提供。"},"pos":"verb"},{"en":"to carry or send water, light, etc. through a passage","cn":"（经过通道）输送，传送","sc":"water/light","ex":{"en":"A sensor channels the light signal along an optical fibre.","cn":"传感器沿光导纤维输送光信号。"},"pos":"verb"},{"en":"to act as a medium (= a person who claims to be able to communicate with the spirits of dead people) for somebody","cn":"充当…的灵媒","sc":"spirit/character","ex":{"en":"He believed that he could channel an ancestor from two hundred years ago.","cn":"他相信自己能充当两百年前一位祖先的灵媒。"},"pos":"verb"},{"en":"to behave in the manner of somebody else, as though that person has given you the idea or desire to act in that way","cn":"像…附体一样","sc":"spirit/character","ex":{"en":"When he sang, he would channel Nat King Cole.","cn":"他演唱时犹如纳京高附体。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"电视台;电视频道","en":"A channel is a television station.","ex":{"en":"...the only serious current affairs programme on either channel.","cn":"两个频道唯一的严肃时事节目"}},{"pos":"N-COUNT 可数名词","cn":"频道;波段","en":"A channel is a band of radio waves on which radio messages can be sent and received."},{"pos":"N-COUNT 可数名词","cn":"渠道;途径;门路","en":"If you do something through a particular channel, or particular channels, that is the system or organization that you use to achieve your aims or to communicate.","ex":{"en":"The government will surely use the diplomatic channels available","cn":"政府肯定会利用各种现有的外交渠道。"}},{"pos":"VERB 动词","cn":"将(资金或资源)专门用于","en":"If you channel money or resources into something, you arrange for them to be used for that thing, rather than for a wider range of things.","ex":{"en":"Jacques Delors wants a system set up to channel funds to the poor countries","cn":"雅克·德洛尔希望建立一套体系，将资金专门用于援助贫穷的国家。"}},{"pos":"VERB 动词","cn":"将(精力或情感)专注于;集中","en":"If you channel your energies or emotions into something, you concentrate on or do that one thing, rather than a range of things.","ex":{"en":"Stephen is channelling his energies into a novel called Blue.","cn":"斯蒂芬正集中精力写一部名为《蓝色》的小说。"}},{"pos":"N-COUNT 可数名词","cn":"水道;沟渠","en":"A channel is a passage along which water flows.","ex":{"en":"Keep the drainage channel clear.","cn":"保持下水道畅通。"}},{"pos":"N-COUNT 可数名词","cn":"航道","en":"A channel is a route used by boats."},{"pos":"N-PROPER 专有名词","cn":"英吉利海峡","en":"The Channel or the English Channel is the narrow area of water between England and France."}]},"media":{"uk":"media/uk/channel__gb_1.mp3","us":"media/us/channel__us_1.mp3"},"examples":[{"en":"The company has worldwide distribution channels.","cn":"这家公司拥有遍布全世界的销售网络。"},{"en":"news from across the Channel (= from France)","cn":"来自英吉利海峡对岸（指法国）的消息"}]},"characteristic":{"media":{"uk":"media/uk/characteristic__gb_1.mp3","us":"media/us/characteristic__us_1.mp3"},"oxford":{"phon":"ˌkærəktəˈrɪstɪk","pos":"noun","senses":[{"en":"a typical feature or quality that something/somebody has","cn":"特征；特点；品质","ex":{"en":"There were few similarities in the brothers' physical characteristics.","cn":"哥哥和弟弟的体貌特征几乎没有相似之处。"}},{"en":"very typical of something or of somebody’s character","cn":"典型的；独特的；特有的","ex":{"en":"Community support of families is characteristic of many societies.","cn":"社区帮扶住户是许多社会的特点。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"特色;特点;特征","en":"The characteristics of a person or thing are the qualities or features that belong to them and make them recognizable.","ex":{"en":"Genes determine the characteristics of every living thing.","cn":"基因决定每个生物的特征。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(品质、特点)明显的，显著的，典型的","en":"A quality or feature that is characteristic of someone or something is one which is often seen in them and seems typical of them.","ex":{"en":"...the absence of strife between the generations that was so characteristic of such societies","cn":"这些社会中典型的代际冲突的缺失"}}]},"examples":[{"en":"Personal characteristics, such as age and sex are taken into account.","cn":"个人的特征，如年龄和性别等，都要考虑进去。"},{"en":"The need to communicate is a key characteristic of human society.","cn":"需要交流是人类社会最重要的一个特征。"}]},"cheer":{"media":{"uk":"media/uk/cheer__gb_1.mp3","us":"media/us/cheer__us_1.mp3"},"oxford":{"phon":"tʃɪə(r)","pos":"verb","senses":[{"en":"to shout loudly, in order to show support or praise for somebody, or to encourage them","cn":"欢呼；喝彩；加油","g":"[intransitive, transitive]","ex":{"en":"We all cheered as the team came on to the field.","cn":"球队入场时我们都为之欢呼。"}},{"en":"to encourage somebody or to give them hope or comfort","cn":"鼓励；鼓舞","g":"[transitive]","ex":{"en":"She was cheered by the news from home.","cn":"来自家里的消息使她受到鼓舞。"}},{"en":"a shout of joy, support or praise","cn":"欢呼声；喝彩声","g":"[countable]","ex":{"en":"A great cheer went up from the crowd.","cn":"观众爆发出一阵热烈的欢呼声。"},"pos":"noun"},{"en":"a special song or poem used by cheerleaders","cn":"（啦啦队的）加油歌，加油诗","g":"[countable]","lab":"North American English","pos":"noun"},{"en":"an atmosphere of happiness","cn":"欢乐（或幸福）的气氛","g":"[uncountable]","lab":"formal or literary","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"喝彩;欢呼","en":"When people cheer, they shout loudly to show their approval or to encourage someone who is doing something such as taking part in a game.","ex":{"en":"The crowd cheered as Premier Wayne Goss unveiled a lifesize statue of poet Banjo Paterson","cn":"韦恩·戈斯州长揭开诗人巴尼奥·佩特森的等身塑像时，人群欢呼起来。"}},{"pos":"VERB 动词","cn":"鼓舞;使鼓起精神","en":"If you are cheered by something, it makes you happier or less worried.","ex":{"en":"Stephen noticed that the people around him looked cheered by his presence","cn":"斯蒂芬注意到，周围的人们似乎因为他的到来而受到鼓舞。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"欢快;愉快的情绪","en":"Cheer is a feeling of cheerfulness.","ex":{"en":"They were impressed by his steadfast good cheer","cn":"他整天笑呵呵的样子给他们留下很深的印象。"}},{"pos":"CONVENTION 惯用语","cn":"(祝酒语)干杯，干","en":"People sometimes say 'Cheers' to each other just before they drink an alcoholic drink."},{"pos":"CONVENTION 惯用语","cn":"谢谢;再见","en":"Some people say 'Cheers' as a way of saying 'thank you' or 'goodbye'."},{"pos":"","cn":"","en":"相关词组：cheer on cheer up"}]},"examples":[{"en":"Bright curtains can cheer up a dull room.","cn":"色彩鲜艳的窗帘可以让单调的房间变得亮丽起来。"},{"en":"The crowd cheered the President as he drove slowly by.","cn":"当总统的车缓缓经过时，群众向他欢呼致意。"}]},"cheque":{"oxford":{"phon":"tʃek","pos":"noun","senses":[{"en":"a printed form that you can write on and sign as a way of paying for something instead of using money","cn":"支票","lab":"informal","ex":{"en":"Can I write you a cheque?","cn":"我可以给你开支票吗？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"支票","en":"A cheque is a printed form on which you write an amount of money and who it is to be paid to. Your bank then pays the money to that person from your account.","ex":{"en":"He wrote them a cheque for £10,000","cn":"他给他们开了张1万英镑的支票。"}}]},"media":{"uk":"media/uk/cheque__gb_1.mp3","us":"media/us/cheque__us_1.mp3"},"examples":[{"en":"to make a cheque out to sb","cn":"给某人开出一张支票"},{"en":"to cash a cheque (= to get or give money for a cheque)","cn":"兑现支票"}]},"childhood":{"media":{"uk":"media/uk/childhood__gb_1.mp3","us":"media/us/childhood__us_1.mp3"},"oxford":{"phon":"ˈtʃaɪldhʊd","pos":"noun","senses":[{"en":"the period of somebody’s life when they are a child","cn":"童年；幼年；孩童时期","lab":"often ironic) 102／23 （） 102／23 （）","ex":{"en":"childhood, adolescence, and adulthood","cn":"童年、青少年及成年"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"童年;幼年时代","en":"A person's childhood is the period of their life when they are a child.","ex":{"en":"She had a happy childhood","cn":"她曾有过一个幸福的童年。"}}]},"examples":[{"en":"She had a happy childhood.","cn":"她有一个幸福的童年。"},{"en":"childhood, adolescence and adulthood","cn":"童年、青少年及成年"}]},"chained":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"被困住的;被缠住的；受到约束的","en":"If you say that someone is chained to a person or a situation, you are emphasizing that there are reasons why they cannot leave that person or situation, even though you think they might like to.","ex":{"en":"Surely modern women want to be informed of world current affairs; we are no longer chained to the kitchen sink!","cn":"当代女性当然想了解时事，我们不再只是受缚于家务小事。"}}]}},"checked":{"media":{"uk":"media/uk/checked__gb_1.mp3","us":"media/us/checked__us_1.mp3"},"oxford":{"phon":"tʃekt","pos":"adjective","senses":[{"en":"having a pattern of squares, usually of two colours","cn":"有方格图案的（常为双色）","ex":{"en":"checked material","cn":"印有方格图案的布料"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（通常指双色）格子的;有格子图案的","en":"Something that is checked has a pattern of small squares, usually of two colours.","ex":{"en":"He was wearing blue jeans and checked shirt.","cn":"他穿着蓝色牛仔裤和格子衬衫。"}}]},"examples":[{"en":"checked material","cn":"印有方格图案的布料"},{"en":"a checked blouse","cn":"格子女衬衫"}]},"chewing":{"oxford":{"phon":"tʃuː","pos":"verb","senses":[{"en":"to bite food into small pieces in your mouth with your teeth to make it easier to swallow","cn":"咀嚼；嚼碎"},{"en":"to bite sth continuously, for example because you are nervous or to taste it （","cn":"因为紧张等）咬住，不停地啃；（为尝味道）不停地咀嚼"}]}},"cheese":{"media":{"uk":"media/uk/cheese__gb_1.mp3","us":"media/us/cheese__us_1.mp3","img":["media/ldoce/img/cheese.jpg"]},"oxford":{"phon":"tʃiːz","pos":"noun","senses":[{"en":"a type of food made from milk that can be either soft or hard and is usually white or yellow in colour; a particular type of this food","cn":"干酪；奶酪","g":"[uncountable, countable]","lab":"British English","ex":{"en":"Cheddar cheese","cn":"切达干酪"}},{"en":"what you ask somebody to say before you take their photograph","cn":"“茄子”（要求照相的人说的口形词）"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"奶酪;干酪","en":"Cheese is a solid food made from milk. It is usually white or yellow.","ex":{"en":"...bread and cheese.","cn":"涂了奶酪的面包"}},{"pos":"PHRASE 短语","cn":"大人物;要人;大亨","en":"Someone who has a very important job or position can be referred to as a big cheese .","ex":{"en":"He is a big cheese in the Art Fraud Squad.","cn":"他是反艺术诈骗专案组的重要人物。"}},{"pos":"PHRASE 短语","cn":"(照相时)说“茄子”;笑一笑","en":"If someone tells you to say 'cheese' when they are taking your photograph, they are indicating that they want you to smile."},{"pos":"","cn":"","en":"as different as chalk and cheese→see: ;"}]},"examples":[{"en":"goat's cheese (= made from the milk of a goat )","cn":"山羊奶酪（由山羊奶制成）"},{"en":"a cheese knife (= a knife with a special curved blade with two points on the end, used for cutting and picking up pieces of cheese)","cn":"干酪切刀"}]},"chosen":{"collins":{"senses":[{"pos":"","cn":"","en":"Chosen is the past participle of choose."}]},"media":{"uk":"media/uk/chosen__gb_1.mp3","us":"media/us/chosen__us_1.mp3"},"oxford":{"phon":"ˈtʃəʊzn","pos":"adjective","senses":[{"en":"selected as the best or most suitable","cn":"精选的；选中的","ex":{"en":"Music is his chosen vocation.","cn":"音乐是他选中的职业。"}}]}},"checkbox":{"oxford":{"phon":"ˈtʃekbɒks","pos":"noun","senses":[{"en":"a small square on a computer screen that you click on with the mouse to choose whether a particular function is switched on or off","cn":"（计算机屏幕上的）复选框"},{"en":"a small square on a printed form in which you put a tick or a cross in response to a question","cn":"（表格、问卷调查或测试的）勾选框"}]},"media":{"uk":"media/uk/checkbox__gb_1.mp3","us":"media/us/checkbox__us_1.mp3"}},"chorus":{"media":{"uk":"media/uk/chorus__gb_1.mp3","us":"media/us/chorus__us_1.mp3"},"oxford":{"phon":"ˈkɔːrəs","pos":"noun","senses":[{"en":"part of a song that is sung after each verse","cn":"副歌","g":"[countable]","ex":{"en":"Everyone joined in the chorus.","cn":"唱到副歌时，大家都加入进来。"}},{"en":"a piece of music, usually part of a larger work, that is written for a choir (= a group of singers)","cn":"合唱曲","g":"[countable]","ex":{"en":"the Hallelujah Chorus","cn":"《哈利路亚合唱曲》"}},{"en":"a large group of singers","cn":"合唱团；歌咏队","g":"[countable + singular or plural verb]","ex":{"en":"the Bath Festival Chorus","cn":"巴斯音乐节大合唱团"}},{"en":"a group of performers who sing and dance in a musical show","cn":"歌舞队","g":"[countable + singular or plural verb]"},{"en":"the sound of a lot of people expressing approval or disapproval at the same time","cn":"齐声，异口同声（表示同意或不同意）","g":"[singular]","ex":{"en":"a chorus of praise/complaint","cn":"一片赞扬声／抱怨声"}},{"en":"a group of performers who comment together on the events of the play","cn":"歌队，合唱队（对剧情加以评论）","g":"[singular + singular or plural verb]"},{"en":"an actor who speaks the opening and closing words of the play","cn":"（开场白和收场白的）朗诵演员","g":"[singular]"},{"en":"to sing or say something all together","cn":"合唱；齐声说；异口同声地说","ex":{"en":"‘Hello, Paul,’ they chorused.","cn":"“你好，保罗。”他们齐声问候道。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"叠句;副歌","en":"A chorus is a part of a song which is repeated after each verse.","ex":{"en":"Caroline sang two verses and the chorus of her song","cn":"卡罗琳唱了她歌曲中的两段和副歌部分。"}},{"pos":"N-COUNT 可数名词","cn":"合唱团;歌咏队","en":"A chorus is a large group of people who sing together.","ex":{"en":"The chorus was singing 'The Ode to Joy'.","cn":"合唱团在唱《欢乐颂》。"}},{"pos":"N-COUNT 可数名词","cn":"合唱(歌)曲","en":"A chorus is a piece of music written to be sung by a large group of people.","ex":{"en":"...the Hallelujah Chorus.","cn":"《哈利路亚合唱曲》"}},{"pos":"N-COUNT 可数名词","cn":"合唱团;歌舞队","en":"A chorus is a group of singers or dancers who perform together in a show, in contrast to the soloists.","ex":{"en":"Students played the lesser parts and sang in the chorus.","cn":"学生扮演一些次要角色，并且参与合唱。"}},{"pos":"N-COUNT 可数名词","cn":"齐声，异口同声(表示批评、反对或赞扬)","en":"When there is a chorus of criticism, disapproval, or praise, that attitude is expressed by a lot of people at the same time.","ex":{"en":"The government is defending its economic policies against a growing chorus of criticism.","cn":"面对日渐高涨的齐声指责，政府不断为其经济政策辩护。"}},{"pos":"VERB 动词","cn":"齐声说;齐唱","en":"When people chorus something, they say it or sing it together.","ex":{"en":"'Hi,' they chorused.","cn":"“嗨，”他们齐声招呼道。"}}]},"examples":[{"en":"Everyone joined in the chorus.","cn":"唱到副歌时，大家都跟着齐唱起来。"},{"en":"the chorus line (= a line of singers and dancers performing together)","cn":"排成一排同台表演的歌舞演员"}]},"chemical":{"oxford":{"phon":"ˈkemɪkl","pos":"adjective","senses":[{"en":"connected with chemistry","cn":"与化学有关的；化学的","ex":{"en":"changes in the chemical composition of the atmosphere","cn":"大气中化学成分的变化"}},{"en":"produced by or using processes that involve changes to atoms or molecules","cn":"用化学方法制造的；化学作用的","ex":{"en":"chemical reactions/compounds","cn":"化学反应；化合物"}},{"en":"using or connected with chemicals","cn":"使用化学制品的；化学品的","ex":{"en":"a chemical plant (= a factory producing chemicals)","cn":"化工厂"}},{"en":"a substance obtained by or used in a chemical process","cn":"化学制品；化学品","ex":{"en":"toxic chemicals","cn":"有毒化学品"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"化学的;化学反应的;用化学方法生成的","en":"Chemical means involving or resulting from a reaction between two or more substances, or relating to the substances that something consists of.","ex":{"en":"...chemical reactions that cause ozone destruction.","cn":"导致臭氧受到破坏的化学反应"}},{"pos":"N-COUNT 可数名词","cn":"化学品;化合物;化学制品","en":"Chemicals are substances that are used in a chemical process or made by a chemical process.","ex":{"en":"The whole food chain is affected by the overuse of chemicals in agriculture.","cn":"整个食物链因农业生产过程过多使用化学品而受到影响。"}}]},"media":{"uk":"media/uk/chemical__gb_1.mp3","us":"media/us/chemical__us_1.mp3"},"examples":[{"en":"The raw sewage is chemically treated.","cn":"未经处理的污水要进行化学处理。"},{"en":"chemical reactions/processes","cn":"化学反应/过程"}]},"cholera":{"media":{"uk":"media/uk/cholera__gb_1.mp3","us":"media/us/cholera__us_1.mp3"},"oxford":{"phon":"ˈkɒlərə","pos":"noun","senses":[{"en":"a serious disease caught from bacteria in water that causes severe diarrhoea and vomiting and often causes death","cn":"霍乱","ex":{"en":"A cholera epidemic swept the country.","cn":"霍乱席卷全国。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"霍乱","en":"Cholera is a serious disease that often kills people. It is caused by drinking infected water or by eating infected food.","ex":{"en":"...a cholera epidemic.","cn":"霍乱流行"}}]}},"chalk":{"oxford":{"phon":"tʃɔːk","pos":"noun","senses":[{"en":"a type of soft white stone","cn":"白垩","g":"[uncountable]","ex":{"en":"the chalk cliffs of southern England","cn":"英格兰南部的白垩质峭壁"}},{"en":"a substance similar to chalk made into white or coloured sticks for writing or drawing","cn":"（白色或彩色的）粉笔","g":"[uncountable, countable]","ex":{"en":"a piece/stick of chalk","cn":"一支粉笔"}},{"en":"to write or draw something with chalk","cn":"用粉笔写（或画）","ex":{"en":"She chalked (up) the day’s menu on the board.","cn":"她把当天的菜单用粉笔写在黑板上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"白垩","en":"Chalk is a type of soft white rock. You can use small pieces of it for writing or drawing with.","ex":{"en":"...the highest chalk cliffs in Britain","cn":"英国最高的白垩悬崖"}},{"pos":"N-UNCOUNT 不可数名词","cn":"粉笔","en":"Chalk is small sticks of chalk, or a substance similar to chalk, used for writing or drawing with.","ex":{"en":"...somebody writing with a piece of chalk.","cn":"在用粉笔写字的某人"}},{"pos":"VERB 动词","cn":"用粉笔画(或写)","en":"If you chalk something, you draw or write it using a piece of chalk.","ex":{"en":"He chalked the message on the blackboard","cn":"他用粉笔将消息写在黑板上。"}},{"pos":"PHRASE 短语","cn":"截然不同;完全不同","en":"If you say that two people or things are like chalk and cheese, you are emphasizing that they are completely different from each other.","ex":{"en":"The two places, he insists, are as different as chalk and cheese","cn":"他坚持说那两个地方有天壤之别。"}},{"pos":"PHRASE 短语","cn":"(用于加强语气)绝对","en":"You can use by a long chalk to add emphasis to something you are saying.","ex":{"en":"The rest of us hadn't finished our drinks, not by a long chalk.","cn":"我们其余几个人还没有喝完，还差得远呢。"}},{"pos":"","cn":"","en":"相关词组：chalk up"}]},"media":{"uk":"media/uk/chalk__gb_1.mp3","us":"media/us/chalk__us_1.mp3"},"examples":[{"en":"We can chalk that win up to a lot of luck.","cn":"我们可以把那次胜利归因于好运十足。"},{"en":"She chalked (up) the day's menu on the board.","cn":"她把当天的菜单用粉笔写在黑板上。"}]},"christian":{"oxford":{"phon":"ˈkrɪstʃən","pos":"adjective","senses":[{"en":"based on or believing the teachings of Jesus Christ","cn":"基督教的；信奉基督教的","ex":{"en":"the Christian Church/faith/religion","cn":"基督教会；基督教的信仰；基督教"}},{"en":"connected with Christians","cn":"基督教徒的","ex":{"en":"the Christian sector of the city","cn":"城市的基督教徒聚居区"}},{"en":"showing the qualities that are thought of as typical of a Christian; good and kind","cn":"有基督教徒品行的；慈善的；仁慈的；友爱的"},{"en":"a person who believes in the teachings of Jesus Christ or has been baptized in a Christian church","cn":"基督徒；基督教徒","ex":{"en":"Only 10% of the population are now practising Christians.","cn":"现在仅有 10% 的人口是积极参与宗教活动的基督徒。"},"pos":"noun"},{"en":"the main character in The Pilgrim's Progress by John Bunyan","cn":"基督徒：约翰·本扬（John Bunyan）的《朝圣者的进步》中的主要角色","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"基督徒","en":"A Christian is someone who follows the teachings of Jesus Christ.","ex":{"en":"He was a devout Christian","cn":"他是个虔诚的基督徒。"}},{"pos":"ADJ 形容词","cn":"基督教的;基督徒的","en":"Christian means relating to Christianity or Christians.","ex":{"en":"...the Christian Church.","cn":"基督教会"}}]},"media":{"uk":"media/uk/christian__gb_1.mp3","us":"media/us/christian__us_1.mp3"},"examples":[{"en":"Only 10% of the population are now practising Christians.","cn":"现在仅有 10% 的人口是热心基督教教徒。"},{"en":"She had a Christian upbringing.","cn":"她从小接受基督教教育。"}]},"chocolate":{"media":{"uk":"media/uk/chocolate__gb_1.mp3","us":"media/us/chocolate__us_1.mp3","img":["media/ldoce/img/chocolate.jpg"]},"oxford":{"phon":"ˈtʃɒklət","pos":"noun","senses":[{"en":"a hard brown sweet food made from cocoa beans, used in cooking to add taste to cakes, etc. or eaten as a sweet","cn":"巧克力；朱古力","g":"[uncountable]","ex":{"en":"a chocolate bar","cn":"巧克力棒"}},{"en":"a sweet that is made of or covered with chocolate","cn":"巧克力糖；夹心巧克力糖","g":"[countable]","ex":{"en":"I gave her a box of hand-made Belgian chocolates.","cn":"我给了她一盒手工做的比利时巧克力。"}},{"en":"a drink made by mixing chocolate powder with hot water or milk; a cup of this drink","cn":"巧克力热饮；一杯巧克力热饮","g":"[uncountable, countable]","lab":"British English","ex":{"en":"a mug of drinking chocolate","cn":"一杯巧克力饮料"}},{"en":"a dark brown colour","cn":"深褐色；巧克力色","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"巧克力","en":"Chocolate is a sweet hard food made from cocoa beans. It is usually brown in colour and is eaten as a sweet.","ex":{"en":"...a bar of chocolate","cn":"一块巧克力"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(通常用热牛奶调制的)巧克力热饮","en":"Chocolate or hot chocolate is a drink made from a powder containing chocolate. It is usually made with hot milk.","ex":{"en":"...a small cafeteria where the visitors can buy tea, coffee and chocolate","cn":"为游客提供茶、咖啡和巧克力热饮的小餐馆"}},{"pos":"N-COUNT 可数名词","cn":"（通常为盒装的）巧克力糖","en":"Chocolates are small sweets or nuts covered with a layer of chocolate. They are usually sold in a box.","ex":{"en":"...a box of chocolates","cn":"一盒巧克力糖"}},{"pos":"COLOUR 颜色词","cn":"深棕色;深褐色","en":"Chocolate is used to describe things that are dark brown in colour.","ex":{"en":"The curtains and the coverlet of the bed were chocolate velvet","cn":"窗帘和床罩是深棕色天鹅绒的。"}}]},"examples":[{"en":"a bar/piece of chocolate","cn":"一条/一块巧克力"},{"en":"a mug of drinking chocolate","cn":"一杯巧克力饮料"}]},"charged":{"oxford":{"phon":"tʃɑːdʒd","pos":"adjective","senses":[{"en":"full of or causing strong feelings or opinions","cn":"充满（某种情绪或想法）的；紧张的","ex":{"en":"a highly charged atmosphere","cn":"一触即发的紧张气氛"}},{"en":"with an electric charge","cn":"带电的","ex":{"en":"The positively and negatively charged ions cause an electric field to form.","cn":"带正电和带负电的离子导致形成电场。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(形势)紧张的，引起强烈感情的","en":"If a situation is charged, it is filled with emotion and therefore very tense or exciting.","ex":{"en":"There was a highly charged atmosphere","cn":"气氛高度紧张。"}},{"pos":"ADJ 形容词","cn":"(粒子)带电的","en":"Charged particles carry an electrical charge.","ex":{"en":"...negatively charged ions.","cn":"负离子"}}]},"media":{"uk":"media/uk/charged__gb_3.mp3","us":"media/us/charged__us_3.mp3"},"examples":[{"en":"The dialogue is charged with menace.","cn":"对话充满威胁。"},{"en":"a highly charged atmosphere","cn":"一触即发的紧张气氛"}]},"chill":{"media":{"uk":"media/uk/chill__gb_1.mp3","us":"media/us/chill__us_1.mp3"},"oxford":{"phon":"tʃɪl","pos":"noun","senses":[{"en":"a feeling of being cold","cn":"寒冷；寒意；凉意","g":"[singular]","ex":{"en":"There's a chill in the air this morning.","cn":"今天早晨寒气袭人。"}},{"en":"an illness caused by being cold and wet, causing a high temperature and shivering (= shaking of the body)","cn":"着凉；受寒","g":"[countable]","ex":{"en":"I caught a nasty chill after my swim last week.","cn":"我上周游泳后得了严重的风寒。"}},{"en":"a feeling of fear","cn":"害怕的感觉","g":"[singular]","ex":{"en":"a chill of fear/apprehension","cn":"一阵害怕／恐惧"}},{"en":"to make somebody very cold","cn":"使很冷；使冰冷","g":"[transitive, usually passive]","ex":{"en":"They were chilled by the icy wind.","cn":"凛冽的寒风吹得他们遍体冰凉。"},"pos":"verb"},{"en":"when food or a drink chills or when somebody chills it, it is made very cold but it does not freeze","cn":"（使）冷却；（被）冷藏","g":"[intransitive, transitive, often passive]","ex":{"en":"Let the pudding chill for an hour until set.","cn":"把布丁冷却一小时直至凝固成形。"},"pos":"verb"},{"en":"to frighten somebody","cn":"使恐惧；恐吓；吓唬","g":"[transitive]","lab":"literary","ex":{"en":"His words chilled her.","cn":"他的话使她不寒而栗。"},"pos":"verb"},{"en":"to spend time relaxing; to relax and stop feeling angry or nervous about something","cn":"放松；冷静；镇静","g":"[intransitive]","lab":"informal","ex":{"en":"We went home and chilled in front of the TV.","cn":"我们回家坐在电视机前放松了一下。"},"pos":"verb"},{"en":"cold, in an unpleasant way","cn":"寒冷的；冷飕飕的；阴冷的","ex":{"en":"the chill grey dawn","cn":"寒冷阴沉的拂晓"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)冷却;(使)凉下来;冷藏","en":"When you chill something or when it chills, you lower its temperature so that it becomes colder but does not freeze.","ex":{"en":"Chill the fruit salad until serving time","cn":"把水果色拉冰镇一下，吃的时候再拿出来。"}},{"pos":"VERB 动词","cn":"使变冷;使冰凉","en":"When cold weather or something cold chills a person or a place, it makes that person or that place feel very cold.","ex":{"en":"The marble floor was beginning to chill me","cn":"大理石地面开始让我觉得发冷。"}},{"pos":"VERB 动词","cn":"惊吓;使恐惧","en":"If you say that something you see, hear, or feel chills you, you mean that it frightens you.","ex":{"en":"There was a coldness in her that chilled him","cn":"她身上透着一股冷漠，让他不寒而栗。"}},{"pos":"N-COUNT 可数名词","cn":"害怕;焦虑;紧张","en":"If something sends a chill through you, it gives you a sudden feeling of fear or anxiety.","ex":{"en":"The violence used against the students sent a chill through Indonesia","cn":"针对学生的暴力使得整个印度尼西亚不寒而栗。"}},{"pos":"N-COUNT 可数名词","cn":"着凉;伤寒","en":"A chill is a mild illness which can give you a slight fever and headache.","ex":{"en":"He caught a chill while performing at a rain-soaked open-air venue.","cn":"他在大雨瓢泼的露天场地演出时受了寒。"}},{"pos":"ADJ 形容词","cn":"(天气)阴冷的，寒冷的","en":"Chill weather is cold and unpleasant.","ex":{"en":"...chill winds, rain and choppy seas.","cn":"凄风、冷雨和波浪起伏的大海"}},{"pos":"","cn":"","en":"相关词组：chill out"}]},"examples":[{"en":"They sometimes meet up to chill out and watch a movie.","cn":"他们有时聚在一起，看场电影放松一下。"},{"en":"We went home and chilled in front of the TV.","cn":"我们回家坐在电视机前放松了一下。"}]},"christ":{"oxford":{"phon":"kraɪst","pos":"noun","senses":[{"en":"the man that Christians believe is the son of God and on whose teachings the Christian religion is based","cn":"基督；耶稣基督"},{"en":"a swear word that many people find offensive, used to show that you are angry, annoyed or surprised","cn":"（很多人认为含冒犯意，表示生气、恼火或吃惊）天哪","ex":{"en":"Christ! Look at the time—I'm late!","cn":"天哪！看看时间，我迟到了！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"基督;耶稣基督","en":"Christ is one of the names of Jesus, whom Christians believe to be the son of God and whose teachings are the basis of Christianity.","ex":{"en":"...the teachings of Christ.","cn":"基督教义"}},{"pos":"EXCLAM 感叹语","cn":"(表示震惊、生气等，或加强语气，可能具冒犯意味)天哪！","en":"Some people say 'Christ!' when they are surprised, shocked, or annoyed, or in order to emphasize what they are saying. This use could cause offence.","ex":{"en":"He looked at her watch. 'Christ! We only have three minutes!'","cn":"他看了看她的表：“天哪！我们仅剩3分钟了！”"}}]},"media":{"uk":"media/uk/christ__gb_1.mp3","us":"media/us/christ__us_1.mp3"},"examples":[{"en":"Christ! Look at the time — I'm late!","cn":"天哪！看看时间，我迟到了！"},{"en":"Christ! That’s hot!","cn":"天哪﹐真烫！"}]},"choice":{"media":{"uk":"media/uk/choice__gb_1.mp3","us":"media/us/choice__us_1.mp3"},"oxford":{"phon":"tʃɔɪs","pos":"noun","senses":[{"en":"an act of choosing between two or more possibilities; something that you can choose","cn":"选择；挑选；抉择","g":"[countable]","ex":{"en":"We are faced with a difficult choice.","cn":"我们面临着困难的抉择。"}},{"en":"the right to choose; the possibility of choosing","cn":"选择权；选择的可能性","g":"[uncountable, singular]","ex":{"en":"If I had the choice, I would stop working tomorrow.","cn":"如果让我选择，我明天就停止工作。"}},{"en":"a person or thing that is chosen","cn":"选中的人（或物）","g":"[countable]","ex":{"en":"This colour wasn't my first choice.","cn":"这种颜色并非我的首选。"}},{"en":"the number or range of different things from which to choose","cn":"供选择的品种；可选的范围","g":"[singular, uncountable]","ex":{"en":"The menu has a good choice of desserts.","cn":"菜单上有多种甜食可供选择。"}},{"en":"of very good quality","cn":"优质的；上等的；优选的","pos":"adjective"},{"en":"of very good, but not the highest, quality","cn":"（质量）中上等的","lab":"North American English","pos":"adjective"},{"en":"rude language that is used deliberately to have an effect","cn":"（语言）故作粗鲁的","lab":"humorous","ex":{"en":"She summed up the situation in a few choice phrases.","cn":"她用粗鲁的两三句话总结了情况。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"选择范围;选择余地","en":"If there is a choice of things, there are several of them and you can choose the one you want.","ex":{"en":"It's available in a choice of colours","cn":"有多种颜色可供选择。"}},{"pos":"N-COUNT 可数名词","cn":"选定的人(或物)","en":"Your choice is someone or something that you choose from a range of things.","ex":{"en":"Although he was only grumbling, his choice of words made Rodney angry.","cn":"尽管他只是在咕哝，可是他的措词却让罗德妮恼火。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优选的;高品质的","en":"Choice means of very high quality.","ex":{"en":"...Fortnum and Mason's choicest chocolates.","cn":"福楠—梅森百货商店的上等巧克力"}},{"pos":"PHRASE 短语","cn":"不得不;只好","en":"If you have no choice but to do something or have little choice but to do it, you cannot avoid doing it.","ex":{"en":"They had little choice but to agree to what he suggested.","cn":"他们别无选择，只好接受他的提议。"}},{"pos":"PHRASE 短语","cn":"…选中的;…看中的","en":"The thing or person of your choice is the one that you choose.","ex":{"en":"...tickets to see the football team of your choice","cn":"观看自己喜欢的足球队比赛的门票"}},{"pos":"PHRASE 短语","cn":"首选的;广受欢迎的","en":"The item of choice is the one that most people prefer.","ex":{"en":"The drug is set to become the treatment of choice for asthma worldwide","cn":"这种药将会成为全世界治疗哮喘的首选。"}}]},"examples":[{"en":"She's going to do it. She doesn't have much choice , really, does she?","cn":"她就要做那件事了。她真的没有多少选择的余地了，不是吗？"},{"en":"Hawaii remains a popular choice for winter vacation travel.","cn":"夏威夷一直是深受人们青睐的冬季假日旅游胜地。"}]},"chamber":{"media":{"uk":"media/uk/chamber__gb_1.mp3","us":"media/us/chamber__us_1.mp3"},"oxford":{"phon":"ˈtʃeɪmbə(r)","pos":"noun","senses":[{"en":"a hall in a public building that is used for formal meetings","cn":"会议厅","g":"[countable]","ex":{"en":"The members left the council chamber.","cn":"议员离开了会议厅。"}},{"en":"one of the parts of a parliament","cn":"（议会的）议院","g":"[countable + singular or plural verb]","ex":{"en":"the Lower/Upper Chamber (= in Britain, the House of Commons/House of Lords)","cn":"下议院；上议院"}},{"en":"a room used for the particular purpose that is mentioned","cn":"（作特定用途的）房间，室","g":"[countable]","ex":{"en":"a Bronze Age burial chamber","cn":"青铜器时代的墓室"}},{"en":"a space in the body, in a plant or in a machine that is separated from the rest","cn":"（人体、植物或机器内的）腔，室","g":"[countable]","ex":{"en":"the chambers of the heart","cn":"心腔"}},{"en":"a space under the ground that is almost completely closed on all sides","cn":"洞穴","g":"[countable]","ex":{"en":"They found themselves in a vast underground chamber.","cn":"他们发现身处一个地下大洞穴。"}},{"en":"a bedroom or private room","cn":"卧室；寝室；私人房间","g":"[countable]","lab":"old use","ex":{"en":"Lady Eleanor was found dead in her chamber.","cn":"埃莉诺夫人被发现死在她的房间里。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大房间;(尤指)大会议室","en":"A chamber is a large room, especially one that is used for formal meetings.","ex":{"en":"We are going to make sure we are in the council chamber every time he speaks.","cn":"每次他发表讲话我们都会确保赶到市议会会议厅去。"}},{"pos":"N-COUNT 可数名词","cn":"议会;议院","en":"You can refer to a country's parliament or to one section of it as a chamber .","ex":{"en":"More than 80 parties are contesting seats in the two-chamber parliament","cn":"有80多个党派在竞争两院的议席。"}},{"pos":"N-COUNT 可数名词","cn":"(作特殊用途的)房间","en":"A chamber is a room designed and equipped for a particular purpose.","ex":{"en":"For many, the dentist's surgery remains a torture chamber.","cn":"对许多人来说，牙医的治疗室一直是间受刑室。"}},{"pos":"N-COUNT 可数名词","cn":"(人体、动植物体内的)腔，室","en":"A chamber is a hollow place inside the body of a person or animal, or inside a plant."},{"pos":"N-PLURAL 复数名词","cn":"（法官）办公室;(律师)事务所","en":"The offices used by judges and barristers are referred to as chambers."}]},"examples":[{"en":"Under Senate rules, the chamber must vote on the bill by this Friday.","cn":"根据规定，参议院必须在本星期五以前投票表决此项议案。"},{"en":"They found themselves in a vast underground chamber.","cn":"他们发现身处一个地下大洞穴。"}]},"charger":{"media":{"uk":"media/uk/charger__gb_1.mp3","us":"media/us/charger__us_1.mp3"},"oxford":{"phon":"ˈtʃɑːdʒə(r)","pos":"noun","senses":[{"en":"a piece of equipment for loading a battery with electricity","cn":"充电器","ex":{"en":"a phone charger","cn":"手机充电器"}},{"en":"a horse that a soldier rode in battle in the past","cn":"（旧时的）军马，战马","lab":"old use","ex":{"en":"knights on white chargers","cn":"白色战马上的骑士"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"充电器","en":"A charger is a device used for charging or recharging batteries.","ex":{"en":"He forgot the charger for his mobile phone.","cn":"他忘了带手机充电器。"}},{"pos":"N-COUNT 可数名词","cn":"(中世纪骑士骑的)战马","en":"A charger was a strong horse that a knight in the Middle Ages used to ride in battle."}]}},"charm":{"media":{"uk":"media/uk/charm__gb_1.mp3","us":"media/us/charm__us_1.mp3"},"oxford":{"phon":"tʃɑːm","pos":"noun","senses":[{"en":"the power of pleasing or attracting people","cn":"魅力；魔力；吸引力","g":"[uncountable]","ex":{"en":"He was a man of great charm.","cn":"他是个极富魅力的男人。"}},{"en":"a feature or quality that is pleasant or attractive","cn":"迷人的特征；吸引人的特性；妩媚","g":"[countable]","ex":{"en":"her physical charms (= her beauty)","cn":"她那妩媚的外貌"}},{"en":"a small object worn on a chain or bracelet that is believed to bring good luck","cn":"（链子或手镯上的）吉祥小饰物","g":"[countable]","ex":{"en":"a lucky charm","cn":"吉祥配饰"}},{"en":"an act or words believed to have magic power","cn":"魔法；咒语；符咒","g":"[countable]"},{"en":"to please or attract somebody in order to make them like you or do what you want","cn":"吸引；迷住","g":"[transitive, intransitive]","ex":{"en":"He was charmed by her beauty and wit.","cn":"他被她的才貌迷住了。"},"pos":"verb"},{"en":"to control or protect somebody/something using magic, or as if using magic","cn":"（以魔法或似用魔法）控制，保护","g":"[transitive]","ex":{"en":"He has led a charmed life (= he has been lucky even in dangerous or difficult situations).","cn":"他的日子过得如有神佑（即使遇到艰险都能逢凶化吉）。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"魅力;吸引力","en":"Charm is the quality of being pleasant or attractive.","ex":{"en":"'Snow White and the Seven Dwarfs', the 1937 Disney classic, has lost none of its original charm","cn":"1937年迪斯尼推出的经典之作《白雪公主和七个小矮人》魅力不减当年。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(人的)魅力，亲和力","en":"Someone who has charm behaves in a friendly, pleasant way that makes people like them.","ex":{"en":"He was a man of great charm and distinction.","cn":"他这个人魅力十足，卓尔不群。"}},{"pos":"VERB 动词","cn":"迷住;吸引；使倾倒","en":"If you charm someone, you please them, especially by using your charm.","ex":{"en":"He even charmed Mrs Prichard, carrying her shopping and flirting with her, though she's 83","cn":"他又是帮普里查德夫人拎买的东西，又是和她调情，居然把83岁高龄的她也给迷倒了。"}},{"pos":"VERB 动词","cn":"运用个人魅力(出入…)","en":"If you charm your way into or out of a place or situation, you use your charm to get into or out of that place or situation.","ex":{"en":"...charming his way into the British Embassy in Teheran","cn":"靠他的个人魅力打入英国驻德黑兰大使馆"}},{"pos":"VERB 动词","cn":"利用个人魅力获取","en":"If you say that someone charmed something out of you or from you, you mean that they used their charm to persuade you to give it to them.","ex":{"en":"He is good at charming money out of companies.","cn":"他擅长利用自己的魅力从各家公司套钱。"}},{"pos":"N-COUNT 可数名词","cn":"(手镯、项链上的)小挂件，小饰物，小玩意","en":"A charm is a small ornament that is fixed to a bracelet or necklace."},{"pos":"N-COUNT 可数名词","cn":"有魔力的物品;咒语;魔法","en":"A charm is an act, saying, or object that is believed to have magic powers.","ex":{"en":"They cross their fingers and spit over their shoulders as charms against the evil eye.","cn":"他们手指交叉，向身后吐口水，作为抵抗邪眼的魔法。"}},{"pos":"PHRASE 短语","cn":"(常指为了获取某物或欺骗某人而)施展魅力","en":"If someone turns on the charm, they behave in a way that seems very friendly but which you think is insincere, often in order to obtain something or deceive someone.","ex":{"en":"He figured out that you're lonely, like most widows, and he turned on the charm.","cn":"他看出你和大多数寡妇一样很寂寞，所以就拿出他的魅力来了。"}},{"pos":"PHRASE 短语","cn":"立见功效;很成功","en":"If you say that something worked like a charm, you mean that it was very effective or successful.","ex":{"en":"Economically, the policy worked like a charm.","cn":"从经济上说，这个政策非常奏效。"}}]},"examples":[{"en":"He has led a charmed life (= he has been lucky even in dangerous or difficult situations).","cn":"他的日子过得如有神佑（即使遇到艰险都能逢凶化吉）。"},{"en":"The hotel is full of charm and character.","cn":"这家旅馆风格独特，极具吸引力。"}]},"chalkboard":{"media":{"uk":"media/uk/chalkboard__gb_1.mp3","us":"media/us/chalkboard__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"黑板","en":"A chalkboard is a dark-coloured board that you can write on with chalk. Chalkboards are often used by teachers in the classroom."}]},"examples":[{"en":"She wrote the day’s menu up on a chalkboard.","cn":"她把一天的菜谱写在黑板上。"}],"oxford":{"phon":"ˈtʃɔːkbɔːd","pos":"noun","senses":[{"en":"a large board with a smooth black or dark green surface that teachers write on with a piece of chalk","cn":"黑板"}]}},"charity":{"oxford":{"phon":"ˈtʃærəti","pos":"noun","senses":[{"en":"an organization for helping people in need","cn":"慈善机构（或组织）","g":"[countable]","ex":{"en":"a registered charity","cn":"注册慈善机构"}},{"en":"organizations for helping people in need, considered as a group; the money, food, help, etc. that they give","cn":"慈善事业；慈善捐赠","g":"[uncountable]","ex":{"en":"Most of the runners in the London Marathon are raising money for charity.","cn":"大多数人参加伦敦马拉松赛跑是为慈善事业募集资金。"}},{"en":"kind behaviour and sympathy towards other people, especially when you are judging them","cn":"仁爱；宽容；宽厚","g":"[uncountable]","lab":"formal","ex":{"en":"Her article showed no charity towards her former friends.","cn":"她的文章对她以前的朋友毫不宽容。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"慈善机构;慈善组织","en":"A charity is an organization which raises money in order to help people who are ill, disabled, or very poor.","ex":{"en":"The National Trust is a registered charity.","cn":"全国托管协会是个已注册的慈善机构。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"慈善(事业)","en":"If you give money to charity, you give it to one or more charitable organizations. If you do something for charity, you do it in order to raise money for one or more charitable organizations.","ex":{"en":"He made substantial donations to charity","cn":"他为慈善事业捐了很多钱。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赈济(金);施舍(物)","en":"People who live on charity live on money or goods which other people give them because they are poor.","ex":{"en":"My mum was very proud. She wouldn't accept charity","cn":"母亲自尊心很强，不会接受施舍。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"仁慈;宽厚","en":"Charity is kindness and understanding towards other people."},{"pos":"PHRASE 短语","cn":"行善始于亲友","en":"If you say charity begins at home, you mean that people should deal with the needs of people close to them before they think about helping others."}]},"media":{"uk":"media/uk/charity__gb_1.mp3","us":"media/us/charity__us_1.mp3"},"examples":[{"en":"Most of the runners in the London Marathon are raising money for charity.","cn":"大多数人参加伦敦马拉松赛跑是为慈善事业募集资金。"},{"en":"The concert will raise money for local charities.","cn":"这场音乐会将为当地慈善机构募捐。"}]},"chess":{"media":{"img":["media/pic/games_boardgames_comp.jpg","media/thumb/chess.jpg"],"uk":"media/uk/chess__gb_1.mp3","us":"media/us/chess__us_1.mp3"},"oxford":{"phon":"tʃes","pos":"noun","senses":[{"en":"a game for two people played on a board marked with black and white squares on which each playing piece (representing a king, queen, castle, etc.) is moved according to special rules. The aim is to put the other player’s king in a position from which it cannot escape (= to checkmate it).","cn":"国际象棋","ex":{"en":"the position of the chess pieces on the board","cn":"国际象棋棋子在棋盘上的布局"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"国际象棋","en":"Chess is a game for two people, played on a chessboard. Each player has 16 pieces, including a king. Your aim is to move your pieces so that your opponent's king cannot escape being taken.","ex":{"en":"...the world chess championships.","cn":"国际象棋世界冠军"}}]},"examples":[{"en":"They meet fairly often to play chess .","cn":"他们经常在一起下国际象棋。"}]},"chicken":{"media":{"img":["media/ldoce/img/chicken.jpg","media/pic/poultry_game_comp.jpg"],"uk":"media/uk/chicken__gb_1.mp3","us":"media/us/chicken__us_1.mp3"},"oxford":{"phon":"ˈtʃɪkɪn","pos":"noun","senses":[{"en":"a large bird that is often kept for its eggs or meat","cn":"鸡","g":"[countable]","ex":{"en":"They keep chickens in the back yard.","cn":"他们在后院养鸡。"}},{"en":"meat from a chicken","cn":"鸡肉","g":"[uncountable]","ex":{"en":"fried chicken","cn":"炸鸡"}},{"en":"a person who is not brave or is afraid to do something","cn":"胆小鬼；懦夫","g":"[countable]","ex":{"en":"He called me a chicken because I wouldn't swim in the river.","cn":"他叫我胆小鬼，因为我不愿意到河里游泳。"}},{"en":"not brave; afraid to do something","cn":"胆怯；懦弱；怯懦","pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鸡","en":"Chickens are birds which are kept on a farm for their eggs and for their meat.","ex":{"en":"Lionel built a coop so that they could raise chickens and have a supply of fresh eggs.","cn":"莱昂内尔做了个鸡笼，打算养些鸡，吃上新鲜鸡蛋。"}},{"pos":"N-COUNT 可数名词","cn":"胆小鬼","en":"If someone calls you a chicken, they mean that you are afraid to do something.","ex":{"en":"I'm scared of the dark. I'm a big chicken.","cn":"我怕黑，是个十足的胆小鬼。"}},{"pos":"PHRASE 短语","cn":"高兴得太早;过早地打如意算盘","en":"If you say that someone is counting their chickens, you mean that they are assuming that they will be successful or get something, when this is not certain.","ex":{"en":"I don't want to count my chickens before they are hatched.","cn":"我不想高兴得太早。"}},{"pos":"PHRASE 短语","cn":"鸡和蛋的问题(指很难决定孰先孰后、孰因孰果的情境)","en":"If you describe a situation as a chicken and egg situation, you mean that it is impossible to decide which of two things caused the other one.","ex":{"en":"It's a chicken and egg situation. Does the deficiency lead to the eczema or has the eczema led to certain deficiencies?","cn":"这是个鸡和蛋的问题。是因为营养缺乏导致湿疹呢，还是湿疹导致了某些营养缺乏？"}},{"pos":"PHRASE 短语","cn":"像只没头的苍蝇到处乱窜","en":"If someone is running round like a headless chicken or rushing around like a headless chicken, they are panicking when they should be thinking carefully about what needs to be done.","ex":{"en":"Instead of running round like a headless chicken use your efforts in a more productive way.","cn":"别像只没头苍蝇东一头西一头的，力气要用对地方。"}},{"pos":"","cn":"","en":"chickens come home to roost→see: ;"},{"pos":"","cn":"","en":"相关词组：chicken out"}]},"examples":[{"en":"They keep chickens in the back yard.","cn":"他们在后院养鸡。"},{"en":"chicken breasts/livers/thighs","cn":"鸡胸脯肉/肝/大腿"}]},"changeable":{"media":{"uk":"media/uk/changeable__gb_1.mp3","us":"media/us/changeable__us_1.mp3"},"oxford":{"phon":"ˈtʃeɪndʒəbl","pos":"adjective","senses":[{"en":"likely to change; often changing","cn":"可能变化的；易变的；常变的","ex":{"en":"The weather is very changeable at this time of year.","cn":"年年在这个时候天气都变化无常。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易变的;变化多的","en":"Someone or something that is changeable is likely to change many times.","ex":{"en":"The forecast is for changeable weather.","cn":"预报针对的是变化无常的天气。"}}]},"examples":[{"en":"The weather is very changeable at this time of year.","cn":"年年在这个时候天气都变化无常。"},{"en":"changeable weather","cn":"变化无常的天气"}]},"channels":{"oxford":{"phon":"ˈtʃænl","pos":"noun","senses":[{"en":"a television station","cn":"电视台"},{"en":"a band of radio waves used for broadcasting television or radio programmes","cn":"频道；波段"}]}},"christmas":{"media":{"uk":"media/uk/christmas__gb_1.mp3","us":"media/us/christmas__us_1.mp3"},"oxford":{"phon":"ˈkrɪsməs","pos":"noun","senses":[{"en":"25 December, the day when Christians celebrate the birth of Christ","cn":"圣诞节（12 月 25 日）","ex":{"en":"Christmas dinner/presents","cn":"圣诞大餐／礼物"}},{"en":"the period that includes Christmas Day and the days close to it","cn":"圣诞节期间","ex":{"en":"the Christmas holidays/vacation","cn":"圣诞节假期"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"圣诞节(12月25日)","en":"Christmas is a Christian festival when the birth of Jesus Christ is celebrated. Christmas is celebrated on the 25th of December.","ex":{"en":"The day after Christmas is generally a busy one for retailers","cn":"圣诞节后的那一天零售商一般都比较忙。"}},{"pos":"N-VAR 可变名词","cn":"圣诞节期间","en":"Christmas is the period of several days around and including Christmas Day.","ex":{"en":"During the Christmas holidays there's a tremendous amount of traffic between the Northeast and Florida","cn":"在圣诞假日期间，东北地区和佛罗里达州之间的交通十分繁忙。"}}]},"examples":[{"en":"Are you spending Christmas with your family?","cn":"你和家人共度圣诞节假日吗？"},{"en":"Merry Christmas and a Happy New Year!","cn":"圣诞快乐并恭贺新禧！"}]},"charcoal":{"media":{"uk":"media/uk/charcoal__gb_1.mp3","us":"media/us/charcoal__us_1.mp3"},"oxford":{"phon":"ˈtʃɑːkəʊl","pos":"noun","senses":[{"en":"a black substance made by burning wood slowly in an oven with little air. Charcoal is used as a fuel or for drawing.","cn":"炭，木炭（可作燃料或供作画）","ex":{"en":"charcoal-grilled steaks","cn":"用木炭烤制的牛排"}},{"en":"a very dark grey colour","cn":"深灰色"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"木炭;(用于绘画的)炭笔，木炭条","en":"Charcoal is a black substance obtained by burning wood without much air. It can be burned as a fuel, and small sticks of it are used for drawing with."}]},"examples":[{"en":"charcoal grilled steaks","cn":"用木炭烤制的牛排"},{"en":"a charcoal drawing","cn":"炭笔画"}]},"channeled":{"oxford":{"phon":"ˈtʃænl","pos":"noun","senses":[{"en":"a television station","cn":"电视台"},{"en":"a band of radio waves used for broadcasting television or radio programmes","cn":"频道；波段"}]}},"chinese":{"media":{"uk":"media/uk/chinese__gb_1.mp3","us":"media/us/chinese__us_1.mp3"},"oxford":{"phon":"ˌtʃaɪˈniːz","pos":"adjective","senses":[{"en":"from or connected with China","cn":"中国的"},{"en":"a person from China, or whose family was originally from China","cn":"中国人；华裔；华人","g":"[countable]","pos":"noun"},{"en":"the language of China","cn":"中国话；汉语；中文","g":"[uncountable]","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"中国的;汉语的;中国人的","en":"Something that is Chinese relates or belongs to China or its languages or people."},{"pos":"N-UNCOUNT 不可数名词","cn":"中国话;汉语;(尤指)普通话","en":"The languages that are spoken in China, especially Mandarin, are often referred to as Chinese ."}]},"examples":[{"en":"Do you fancy going out for a Chinese?","cn":"你想不想出去吃顿中餐？"}]},"christians":{"oxford":{"phon":"ˈkrɪstʃən","pos":"adjective","senses":[{"en":"based on or believing the teachings of Jesus Christ","cn":"基督教的；信奉基督教的"},{"en":"connected with Christians","cn":"基督教徒的"}]}},"chase":{"media":{"uk":"media/uk/chase__gb_1.mp3","us":"media/us/chase__us_1.mp3"},"oxford":{"phon":"tʃeɪs","pos":"verb","senses":[{"en":"to run, drive, etc. after somebody/something in order to catch them or it","cn":"追赶；追逐；追捕","g":"[transitive, intransitive]","sc":"run/drive after","ex":{"en":"My dog likes chasing rabbits.","cn":"我的狗喜欢追捕兔子。"}},{"en":"to force somebody/something to run away","cn":"驱逐；赶走","g":"[transitive]","sc":"run/drive after","ex":{"en":"Chase the cat out—we don't want her in the kitchen.","cn":"把猫赶出去，我们不想让它进厨房。"}},{"en":"to try to obtain or achieve something, for example money, work or success","cn":"努力获得；争取得到","g":"[transitive]","sc":"money/work/success","ex":{"en":"Too many people are chasing too few jobs nowadays.","cn":"如今有太多的人在角逐寥寥无几的工作职位。"}},{"en":"to try to persuade somebody to have a sexual relationship with you","cn":"追求；求爱","g":"[intransitive, transitive]","lab":"informal","sc":"man/woman","ex":{"en":"Kevin's been chasing after Joan for months.","cn":"凯文几个月来一直在追求琼。"}},{"en":"to persuade somebody to do something that they should have done already","cn":"催促","g":"[transitive]","lab":"informal","sc":"remind somebody","ex":{"en":"I need to chase him about organizing the meeting.","cn":"我得催他有关筹办会议的事。"}},{"en":"to rush or hurry somewhere","cn":"急奔；急赶；匆忙地走","g":"[intransitive]","lab":"informal","sc":"rush","ex":{"en":"I've been chasing around town all morning looking for a present for Sharon.","cn":"为了送给莎伦一件礼物，我一上午都在满城奔走寻觅。"}},{"en":"to cut patterns or designs on metal","cn":"镂刻；雕刻","g":"[transitive]","lab":"specialist","sc":"metal","ex":{"en":"chased silver","cn":"雕花银器"}},{"en":"an act of running or driving after somebody/something in order to catch them or it","cn":"追赶；追捕；追逐","g":"[countable]","sc":"running/driving after","ex":{"en":"The thieves were caught by police after a short chase.","cn":"经过短暂追捕，小偷被警察擒获。"},"pos":"noun"},{"en":"a process of trying hard to get something","cn":"努力获得；争取","g":"[singular]","sc":"for success/money/work","ex":{"en":"Three teams are involved in the chase for the championship.","cn":"有三支队伍角逐冠军的宝座。"},"pos":"noun"},{"en":"hunting animals as a sport","cn":"打猎","g":"[singular]","sc":"in sport","ex":{"en":"She enjoyed the thrill of the chase.","cn":"她很享受打猎的快感。"},"pos":"noun"},{"en":"a long race in which horses have to jump over fences, water, etc.","cn":"越野障碍赛马","g":"[countable]","sc":"in sport","pos":"noun"},{"en":"a long race in which people run and jump over gates and water, etc. around a track","cn":"障碍赛跑","sc":"in sport","pos":"noun"},{"en":"one of largest banks in the US, operating in many states. It has its main office in Manhattan, New York, where its history goes back over 200 years. It is now part of JPMorgan Chase & Co.","cn":"大通银行：美国最大的银行之一，在许多州都有营业。它的总部设在纽约曼哈顿，其历史可以追溯到200多年。它现在是摩根大通公司的一部分。","pos":""}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"追;赶;撵","en":"If you chase someone, or chase after them, you run after them or follow them quickly in order to catch or reach them.","ex":{"en":"She chased the thief for 100 yards","cn":"她追了窃贼100码远。"}},{"pos":"VERB 动词","cn":"争取，追逐，追求(工作或金钱等)","en":"If you are chasing something you want, such as work or money, you are trying hard to get it.","ex":{"en":"In Wales, 14 people are chasing every job","cn":"在威尔士，每份工作都有14个人在竞争。"}},{"pos":"VERB 动词","cn":"追求;(向…)求欢","en":"If someone chases someone that they are attracted to, or chases after them, they try hard to persuade them to have a sexual relationship with them.","ex":{"en":"I'm not very good at flirting or chasing women","cn":"我不太会和女人调情，也不擅长追求女性。"}},{"pos":"VERB 动词","cn":"撵走;赶走","en":"If someone chases you from a place, they force you to leave by using threats or violence.","ex":{"en":"Many farmers will then chase you off their land quite aggressively","cn":"许多农民然后就会凶巴巴地把你从他们的土地上撵走。"}},{"pos":"PHRASE 短语","cn":"抓住核心;抓住要害","en":"If someone cuts to the chase, they start talking about or dealing with what is important, instead of less important things.","ex":{"en":"Hi everyone, we all know why we are here today, so let's cut to the chase.","cn":"嗨，各位，大伙儿都知道今天我们为什么在这里，那就直入正题吧。"}},{"pos":"VERB 动词","cn":"撤销…的职位;将…赶下台","en":"To chase someone from a job or a position or from power means to force them to leave it.","ex":{"en":"His single-minded pursuit of European union helped chase Mrs Thatcher from power.","cn":"他对欧洲统一的执著追求在一定程度上促成了撒切尔夫人的下台。"}},{"pos":"VERB 动词","cn":"匆忙赶往","en":"If you chase somewhere, you run or rush there.","ex":{"en":"They chased down the stairs into the narrow, dirty street.","cn":"他们冲下楼梯，来到狭窄、肮脏的街上。"}},{"pos":"N-SING 单数名词","cn":"狩猎;猎捕","en":"The chase is the activity of hunting animals.","ex":{"en":"...bear robes, mountain lion hides, and other trophies of the chase.","cn":"熊皮袍子、美洲狮的皮，以及这次狩猎的其他战利品"}},{"pos":"N-IN-NAMES 名称名词","cn":"越野赛马；障碍赛马","en":"Chase is often used in the name of horse races in which the horses have to jump over obstacles such as fences or bushes.","ex":{"en":"...the Champion Hunter Chase.","cn":"猎人王越野赛马"}},{"pos":"PHRASE 短语","cn":"追逐;追赶;追捕","en":"If you give chase, you run after someone or follow them quickly in order to catch them.","ex":{"en":"Other officers gave chase but the killers escaped.","cn":"其他警官追了上去，可是杀手还是逃了。"}},{"pos":"PHRASE 短语","cn":"追求过程中的刺激","en":"If you talk about the thrill of the chase, you are referring to the excitement that people feel when they are trying hard to get something.","ex":{"en":"People who adore the thrill of the chase know that prizes, like diamonds, are worth striving for.","cn":"享受追求过程中的刺激的人们清楚，奖赏和钻石一样，是值得为之一搏的。"}},{"pos":"","cn":"","en":"相关词组：chase away chase down chase up"}]},"examples":[{"en":"We lost him in the narrow streets and had to give up the chase (= stop chasing him).","cn":"我们在狭窄的街道上被他甩掉，不得不放弃对他的追捕。"},{"en":"I've been chasing around town all morning looking for a present for Sharon.","cn":"为了送给沙伦一件礼物，我一上午都在满城奔走寻觅。"}]},"chaotic":{"media":{"uk":"media/uk/chaotic__gb_1.mp3","us":"media/us/chaotic__us_1.mp3"},"oxford":{"phon":"keɪˈɒtɪk","pos":"adjective","senses":[{"en":"without any order; in a completely confused state","cn":"无秩序的；混乱的","ex":{"en":"The traffic in the city is chaotic in the rush hour.","cn":"在上下班高峰时间，城市的交通混乱不堪。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"混乱的;乱糟糟的","en":"Something that is chaotic is in a state of complete disorder and confusion.","ex":{"en":"My own house feels as filthy and chaotic as a bus terminal","cn":"我自家的房子感觉又脏又乱，活像公共汽车终点站。"}}]},"examples":[{"en":"The traffic in the city is chaotic in the rush hour.","cn":"在上下班高峰时间，城市的交通混乱不堪。"},{"en":"a chaotic mixture of images","cn":"杂乱无章的各种图像"}]},"cheerless":{"media":{"uk":"media/uk/cheerless__gb_1.mp3","us":"media/us/cheerless__us_1.mp3"},"oxford":{"phon":"ˈtʃɪələs","pos":"adjective","senses":[{"en":"not being warm or brightly coloured so it makes you feel depressed","cn":"阴冷的；阴暗的；阴郁的","ex":{"en":"a dark and cheerless room","cn":"黑暗阴森的房间"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方或天气)沉闷的，令人不快的","en":"Cheerless places or weather are dull and depressing.","ex":{"en":"The kitchen was dank and cheerless.","cn":"厨房既潮湿又阴暗。"}}]},"examples":[{"en":"a dark and cheerless room","cn":"黑暗阴森的房间"},{"en":"This is a cold cheerless place.","cn":"这是个寒冷﹑阴郁的地方。"}]},"choir":{"oxford":{"phon":"ˈkwaɪə(r)","pos":"noun","senses":[{"en":"a group of people who sing together, for example in church services or public performances","cn":"（教堂的）唱诗班；（公开演出的）合唱团，歌唱队","g":"[countable + singular or plural verb]","lab":"British English","ex":{"en":"She sings in the school choir.","cn":"她是校合唱队的成员。"}},{"en":"the part of a church where the choir sits during services","cn":"（教堂）唱经楼，唱诗席","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(教堂的)唱诗班;(学校的)合唱队，合唱团","en":"A choir is a group of people who sing together, for example in a church or school.","ex":{"en":"He has been singing in his church choir since he was six.","cn":"他打6岁起一直在教堂唱诗班里唱歌。"}},{"pos":"N-COUNT 可数名词","cn":"(教堂里的)唱诗班席","en":"In a church building, the choir is the area in front of the altar where the choir sits."}]},"media":{"uk":"media/uk/choir__gb_1.mp3","us":"media/us/choir__us_1.mp3"},"examples":[{"en":"She sings in the school choir.","cn":"她是校合唱队的成员。"},{"en":"He joined a church choir at the age of eight.","cn":"他八岁时加入了一个教堂唱诗班。"}]},"chair":{"media":{"img":["media/ldoce/img/chair.jpg","media/pic/chairs_livingroom_comp.jpg"],"uk":"media/uk/chair__gb_1.mp3","us":"media/us/chair__us_1.mp3"},"oxford":{"phon":"tʃeə(r)","pos":"noun","senses":[{"en":"a piece of furniture for one person to sit on, with a back, a seat and four legs","cn":"椅子","g":"[countable]","ex":{"en":"a table and chairs","cn":"一套桌椅"}},{"en":"the position of being in charge of a meeting or committee; the person who holds this position","cn":"（主持会议或委员会的）主席席位，委员长职位；（会议或委员会的）主席，委员长","g":"[countable, usually singular]","ex":{"en":"Who is in the chair today?","cn":"今天谁主持？"}},{"en":"the position of being in charge of a department in a university; a special position as a university professor","cn":"（大学的）系主任；讲席教授；讲座教授","g":"[countable]","ex":{"en":"He holds the chair of philosophy at Oxford.","cn":"他是牛津大学哲学系的讲席教授。"}},{"en":"(especially in the US) a chair in which criminals are killed by having a powerful electric current passed through their bodies; the method of execution that uses this chair","cn":"（处决犯人的）电椅，电刑","g":"[singular]","lab":"US English, informal，，"},{"en":"to act as the chairman or chairwoman of a meeting, discussion, etc.","cn":"担任（会议、讨论等的）主席；主持（会议、讨论等）","ex":{"en":"to chair a committee","cn":"担任委员会主席"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"椅子","en":"A chair is a piece of furniture for one person to sit on. Chairs have a back and four legs.","ex":{"en":"He rose from his chair and walked to the window.","cn":"他从椅子上站起来，朝窗口走去。"}},{"pos":"N-COUNT 可数名词","cn":"(大学的)教授职位","en":"At a university, a chair is the post of professor.","ex":{"en":"He has been appointed to the chair of sociology at Southampton University","cn":"他被任命担任南安普敦大学的社会学教授一职。"}},{"pos":"N-COUNT 可数名词","cn":"(委员会、会议的)主席","en":"The person who is the chair of a committee or meeting is the person in charge of it.","ex":{"en":"She is the chair of the Defense Advisory Committee on Women in the Military.","cn":"她担任军队女性权益保护顾问委员会主席。"}},{"pos":"VERB 动词","cn":"主持(会议);担任(委员会的)主席","en":"If you chair a meeting or a committee, you are the person in charge of it.","ex":{"en":"He was about to chair a meeting in Venice of EU foreign ministers","cn":"他将主持在威尼斯召开的欧盟外长会议。"}},{"pos":"N-SING 单数名词","cn":"同 electric chair","en":"The chair is the same as the electric chair ."},{"pos":"PHRASE 短语","cn":"主持(会议)","en":"If you are in the chair or take the chair at a meeting, you are the person in charge of it.","ex":{"en":"In the chair was Morien Morgan","cn":"会议由莫里恩·摩根主持。"}}]},"examples":[{"en":"He holds the chair of philosophy at Oxford.","cn":"他是牛津大学哲学系的系主任。"},{"en":"an old man asleep in a chair (= an armchair )","cn":"在扶手椅里睡着了的老人"}]},"challenging":{"media":{"uk":"media/uk/challenging__gb_1.mp3","us":"media/us/challenging__us_1.mp3"},"oxford":{"phon":"ˈtʃælɪndʒɪŋ","pos":"adjective","senses":[{"en":"difficult in an interesting way that tests your ability","cn":"挑战性的；考验能力的","ex":{"en":"challenging work/questions/problems","cn":"具有挑战性的工作／提问／问题"}},{"en":"done in a way that invites people to disagree or argue with you, or shows that you disagree with them","cn":"挑起争论的；不赞同的","ex":{"en":"She gave him a challenging look. ‘Are you really sure?’ she demanded.","cn":"她用挑衅的眼光看了他一眼。“你敢肯定吗？”她问道。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(任务或工作)艰巨的，具有挑战性的，要求高的","en":"A challenging task or job requires great effort and determination.","ex":{"en":"Mike found a challenging job as a computer programmer","cn":"迈克找到一份做计算机程序员的富有挑战性的工作。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"挑战性的;挑衅的","en":"If you do something in a challenging way, you seem to be inviting people to argue with you or compete against you in some way.","ex":{"en":"Mona gave him a challenging look.","cn":"莫娜挑衅地看了他一眼。"}}]},"examples":[{"en":"She gave him a challenging look. ‘Are you really sure?’ she demanded.","cn":"她用挑衅的眼光看了他一眼。 “你敢肯定吗？”她问道。"},{"en":"a challenging and rewarding career as a teacher","cn":"富有挑战性且有意义的教师职业"}]},"choose":{"media":{"uk":"media/uk/choose__gb_1.mp3","us":"media/us/choose__us_1.mp3"},"oxford":{"phon":"tʃuːz","pos":"verb","senses":[{"en":"to decide which thing or person you want out of the ones that are available","cn":"选择；挑选；选取","g":"[intransitive, transitive]","ex":{"en":"You choose—I can't decide.","cn":"你来选吧，我拿不定主意。"}},{"en":"to prefer or decide to do something","cn":"宁愿；情愿；决定","g":"[intransitive, transitive]","ex":{"en":"Employees can retire at 60 if they choose.","cn":"如果雇员愿意的话，可在 60 岁退休。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"挑选;选择;选取","en":"If you choose someone or something from several people or things that are available, you decide which person or thing you want to have.","ex":{"en":"They will be able to choose their own leaders in democratic elections","cn":"他们将能够通过民主选举选择自己的领导人。"}},{"pos":"VERB 动词","cn":"甘愿;决定","en":"If you choose to do something, you do it because you want to or because you feel that it is right.","ex":{"en":"They knew that discrimination was going on, but chose to ignore it","cn":"他们当时知道歧视现象仍然存在，但是宁愿装聋作哑。"}},{"pos":"PHRASE 短语","cn":"不分上下;好坏相当","en":"If there is little to choose between people or things or nothing to choose between them, it is difficult to decide which is better or more suitable.","ex":{"en":"There is very little to choose between the world's top tennis players.","cn":"世界顶级网球运动员之间往往难分伯仲。"}},{"pos":"PHRASE 短语","cn":"享受优厚待遇的少数人；精英","en":"The chosen few are a small group who are treated better than other people. You sometimes use this expression when you think this is unfair.","ex":{"en":"Learning should no longer be an elitist pastime for the chosen few.","cn":"学习不应再是少数人的高级消遣。"}},{"pos":"","cn":"","en":"to pick and choose→see: ;"}]},"examples":[{"en":"We have to choose a new manager from a shortlist of five candidates.","cn":"我们得从最终人选名单上的五位候选人中选出一个新经理。"},{"en":"She had to choose between staying in the UK or going home.","cn":"她不得不在留在英国和回国之间作出选择。"}]},"charge":{"media":{"uk":"media/uk/charge__gb_1.mp3","us":"media/us/charge__us_1.mp3"},"oxford":{"phon":"tʃɑːdʒ","pos":"noun","senses":[{"en":"the amount of money that somebody asks for goods and services","cn":"（商品和服务所需的）要价，收费","g":"[countable, uncountable]","lab":"British English","sc":"money","ex":{"en":"admission charges","cn":"入场费"}},{"en":"a charge account","cn":"赊销账；赊欠账；赊购","g":"[countable]","lab":"North American English, informal，，","sc":"money","ex":{"en":"Would you like to put that on your charge?","cn":"你愿意把这笔费用记在你的账上吗？"}},{"en":"a position of having control over somebody/something; responsibility for somebody/something","cn":"主管；掌管；职责；责任","g":"[uncountable]","sc":"responsibility","ex":{"en":"She has charge of the day-to-day running of the business.","cn":"她负责掌管日常业务。"}},{"en":"a person that you have responsibility for and care for","cn":"被照管的人；受照料者","g":"[countable]","lab":"formal or humorous","sc":"responsibility"},{"en":"an official claim made by the police that somebody has committed a crime","cn":"指控；控告","g":"[countable, uncountable]","lab":"especially North American English","sc":"of crime/something wrong","ex":{"en":"criminal charges","cn":"刑事指控"}},{"en":"a statement accusing somebody of doing something wrong or bad","cn":"指责；谴责","g":"[countable]","sc":"of crime/something wrong","ex":{"en":"She rejected the charge that the story was untrue.","cn":"她否认了说她编造事实的指责。"}},{"en":"the amount of electricity that is put into a battery or carried by a substance","cn":"（电池的）充电量；（带电物质的）电荷","g":"[countable, uncountable]","sc":"electricity","ex":{"en":"a positive/negative charge","cn":"正电荷；负电荷"}},{"en":"the act of putting electricity into a battery; the electricity in a battery","cn":"（电池）充电，电量","g":"[uncountable]","sc":"electricity","ex":{"en":"He put his phone on charge.","cn":"他给他的手机充电。"}},{"en":"a sudden rush or violent attack, for example by soldiers, wild animals or players in some sports","cn":"突然猛冲；猛攻；冲锋","g":"[countable]","lab":"figurative","sc":"rush/attack","ex":{"en":"He led the charge down the field.","cn":"他带头沿着球场冲杀过去。"}},{"en":"the amount of explosive needed to fire a gun or make an explosion","cn":"（射击或爆炸需要的）炸药量","g":"[countable]","sc":"explosive"},{"en":"the power to cause strong feelings","cn":"感染力；震撼力","g":"[singular]","sc":"strong feeling","ex":{"en":"the emotional charge of the piano piece","cn":"那首钢琴曲扣人心弦的感染力"}},{"en":"a task or duty","cn":"任务；责任","g":"[singular]","lab":"formal","sc":"task","ex":{"en":"His charge was to obtain specific information.","cn":"他的任务是收集具体的信息。"}},{"en":"to ask an amount of money for goods or a service","cn":"收费；要价","g":"[transitive, intransitive]","sc":"money","ex":{"en":"The fees charged by some companies are excessive.","cn":"有些公司收费过高。"},"pos":"verb"},{"en":"to record the cost of something as an amount that somebody has to pay","cn":"把…记在账上；在某人账上记入","g":"[transitive]","lab":"North American English","sc":"money","ex":{"en":"They charge the calls to their credit-card account.","cn":"他们用信用卡账户支付电话费。"},"pos":"verb"},{"en":"to pass electricity through something so that it is stored there; to take in electricity so that it is stored and ready for use","cn":"（给…）充电","g":"[transitive, intransitive]","sc":"with electricity","ex":{"en":"I need to charge my phone.","cn":"我需要给我的手机充电。"},"pos":"verb"},{"en":"to accuse somebody formally of a crime so that there can be a trial in court","cn":"控告；起诉","g":"[transitive]","sc":"with crime/something wrong","ex":{"en":"Several people were arrested but nobody was charged.","cn":"有数人被捕，但均未受到起诉。"},"pos":"verb"},{"en":"to accuse somebody publicly of doing something wrong or bad","cn":"指责；谴责","g":"[transitive]","lab":"formal","sc":"with crime/something wrong","ex":{"en":"Opposition MPs charged the minister with neglecting her duty.","cn":"反对党议员指责这名女部长玩忽职守。"},"pos":"verb"},{"en":"to make a claim or statement that something will happen or be the case","cn":"断言；宣称","sc":"with crime/something wrong","ex":{"en":"Opponents charged that cutting costs would reduce safety.","cn":"反对者宣称削减成本会降低安全性。"},"pos":"verb"},{"en":"to rush forward and attack somebody/something","cn":"猛冲；猛攻；冲锋","g":"[intransitive, transitive]","sc":"rush/attack","ex":{"en":"The bull put its head down and charged.","cn":"公牛低下头猛冲过来。"},"pos":"verb"},{"en":"to rush in a particular direction","cn":"向…方向冲去","g":"[intransitive]","sc":"rush/attack","ex":{"en":"The children charged down the stairs.","cn":"孩子们冲下了楼梯。"},"pos":"verb"},{"en":"to give somebody a responsibility or task","cn":"赋予…职责（或任务）；使…承担责任（或任务）","g":"[transitive]","lab":"formal","sc":"with responsibility/task","ex":{"en":"The committee has been charged with the development of sport in the region.","cn":"委员会已被赋予在该地区发展体育运动的职责。"},"pos":"verb"},{"en":"to fill somebody with an emotion","cn":"使充满（…情绪）","g":"[transitive]","lab":"literary","sc":"with strong feeling","ex":{"en":"The room was charged with hatred.","cn":"这个房间里充满了敌意。"},"pos":"verb"},{"en":"to fill a glass","cn":"注满（玻璃杯）","g":"[transitive]","lab":"British English, formal，，","sc":"glass","ex":{"en":"Please charge your glasses and drink a toast to the bride and groom!","cn":"请各位斟满酒杯向新娘、新郎敬酒！"},"pos":"verb"},{"en":"to load a gun","cn":"装（弹药）","g":"[transitive]","lab":"old use","sc":"gun","pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"向…收费;索要(钱);要价","en":"If you charge someone an amount of money, you ask them to pay that amount for something that you have sold to them or done for them.","ex":{"en":"Even local nurseries charge £100 a week","cn":"连本地托儿所每星期都要收费100英镑。"}},{"pos":"VERB 动词","cn":"将…的账单寄给…;把…记在…的账上","en":"To charge something to a person or organization means to tell the people providing it to send the bill to that person or organization. To charge something to someone's account means to add it to their account so they can pay for it later.","ex":{"en":"Go out and buy a pair of glasses, and charge it to us","cn":"去买副眼镜，账记在我们头上。"}},{"pos":"N-COUNT 可数名词","cn":"(提供服务的)要价，收费","en":"A charge is an amount of money that you have to pay for a service.","ex":{"en":"We can arrange this for a small charge","cn":"我们可以将此安排好，只收取很少的费用。"}},{"pos":"N-COUNT 可数名词","cn":"指控;控告","en":"A charge is a formal accusation that someone has committed a crime.","ex":{"en":"He may still face criminal charges","cn":"他可能仍然要面临刑事指控。"}},{"pos":"VERB 动词","cn":"(警方)指控，起诉","en":"When the police charge someone, they formally accuse them of having done something illegal.","ex":{"en":"They have the evidence to charge him","cn":"他们握有控告他的证据。"}},{"pos":"VERB 动词","cn":"(公开)指责，谴责","en":"If you charge someone with doing something wrong or unpleasant, you publicly say that they have done it.","ex":{"en":"He charged the minister with lying about the economy.","cn":"他指责部长在经济问题上撒谎。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"负责;管理","en":"If you take charge of someone or something, you make yourself responsible for them and take control over them. If someone or something is in your charge, you are responsible for them.","ex":{"en":"A few years ago Bacryl took charge of the company","cn":"几年前，巴克里尔接管了该公司。"}},{"pos":"PHRASE 短语","cn":"主管;全面负责；统领","en":"If you are in charge in a particular situation, you are the most senior person and have control over something or someone.","ex":{"en":"Who's in charge here?","cn":"这儿谁管事啊？"}},{"pos":"N-COUNT 可数名词","cn":"被照管的人;所负责的人","en":"If you describe someone as your charge, they have been given to you to be looked after and you are responsible for them.","ex":{"en":"The coach tried to get his charges motivated.","cn":"教练试图激发队员的积极性。"}},{"pos":"VERB 动词","cn":"猛冲;猛攻","en":"If you charge towards someone or something, you move quickly and aggressively towards them.","ex":{"en":"He charged through the door to my mother's office","cn":"他冲出门，往我母亲的办公室跑去。"}},{"pos":"VERB 动词","cn":"给(电池)充电","en":"To charge a battery means to pass an electrical current through it in order to make it more powerful or to make it last longer.","ex":{"en":"Alex had forgotten to charge the battery.","cn":"亚力克斯忘了给电池充电。"}},{"pos":"N-COUNT 可数名词","cn":"(带电物质的)电荷，充电量","en":"An electrical charge is an amount of electricity that is held in or carried by something."},{"pos":"N-COUNT 可数名词","cn":"(子弹、炮弹所装填的)火药，炸药;子弹;炮弹","en":"The charge in a cartridge or shell is the explosive inside it. You can also refer to the cartridge or shell itself as a charge ."},{"pos":"PHRASE 短语","cn":"免费的","en":"If something is free of charge, it does not cost anything.","ex":{"en":"The leaflet is available free of charge from post offices.","cn":"宣传单可以到邮局免费领取。"}},{"pos":"","cn":"","en":"相关词组：charge up"}]},"examples":[{"en":"Be careful you don't leave yourself open to charges of political bias.","cn":"你要小心别留下把柄，让人家指责你带有政治偏见。"},{"en":"The governing body is charged with managing the school within its budget.","cn":"学校管理部门负有在预算范围内管理好学校的职责。"}]},"chain":{"media":{"img":["media/ldoce/img/chain.jpg","media/pic/rope_comp.jpg"],"uk":"media/uk/chain__gb_1.mp3","us":"media/us/chain__us_1.mp3"},"oxford":{"phon":"tʃeɪn","pos":"noun","senses":[{"en":"a series of connected metal rings, used for pulling or fastening things; a length of chain used for a particular purpose","cn":"链子；链条；锁链","g":"[countable, uncountable]","sc":"metal rings","ex":{"en":"She wore a heavy gold chain around her neck.","cn":"她戴着一条粗实的金项链。"}},{"en":"a series of connected things or people","cn":"一系列，一连串（人或事）","g":"[countable]","sc":"connected things","ex":{"en":"mountain/island chains","cn":"山脉；岛群"}},{"en":"a group of shops or hotels owned by the same company","cn":"连锁商店（或旅馆）","g":"[countable]","sc":"of shops/hotels","ex":{"en":"a supermarket/hotel/retail chain","cn":"连锁超市／旅馆／零售店"}},{"en":"a thing that limits somebody’s freedom or ability to do something","cn":"约束；束缚","g":"[countable, usually plural]","lab":"formal or literary","sc":"restriction","ex":{"en":"the chains of fear/misery","cn":"恐惧的桎梏；苦难的枷锁"}},{"en":"a situation in which a number of people selling and buying houses must each complete the sale of their house before buying from the next person","cn":"连环式（指一群房主先售后购的置业方式）","g":"[countable, usually singular]","lab":"British English","sc":"in house buying"},{"en":"to fasten something with a chain; to fasten somebody/something to another person or thing with a chain, so that they do not escape or get stolen","cn":"用锁链拴住（或束缚、固定）","lab":"figurative","ex":{"en":"The doors were always locked and chained.","cn":"那些门总是上着锁链。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"链条;链子","en":"A chain consists of metal rings connected together in a line.","ex":{"en":"His open shirt revealed a fat gold chain","cn":"他的衬衫敞着，露出一条很粗的金链。"}},{"pos":"N-PLURAL 复数名词","cn":"手铐；镣铐","en":"If prisoners are in chains, they have thick rings of metal round their wrists or ankles to prevent them from escaping.","ex":{"en":"He'd spent four and a half years in windowless cells, much of the time in chains.","cn":"他已经在没有窗户的牢房里呆了4年半，多数时间都戴着镣铐。"}},{"pos":"N-PLURAL 复数名词","cn":"约束;羁绊;顾虑","en":"You can refer to feelings and duties which prevent you from doing what you want to do as chains .","ex":{"en":"He had to break right now the chains of habit that bound him to the present.","cn":"他必须现在就打破把他束缚在当前境况的习惯。"}},{"pos":"VERB 动词","cn":"用链子捆住;把…拴起来","en":"If a person or thing is chained to something, they are fastened to it with a chain.","ex":{"en":"The dog was chained to the leg of the one solid garden seat","cn":"狗被拴在公园一个固定座位的腿上。"}},{"pos":"N-COUNT 可数名词","cn":"一连串;一排","en":"A chain of things is a group of them existing or arranged in a line.","ex":{"en":"...a chain of islands known as the Windward Islands","cn":"名为“向风群岛”的岛群"}},{"pos":"N-COUNT 可数名词","cn":"连锁店;连锁集团","en":"A chain of shops, hotels, or other businesses is a number of them owned by the same person or company.","ex":{"en":"...a large supermarket chain.","cn":"大型连锁超市"}},{"pos":"N-SING 单数名词","cn":"一连串;一系列","en":"A chain of events is a series of them happening one after another.","ex":{"en":"...the bizarre chain of events that led to his departure in January 1938.","cn":"促使他于1938年1月离去的一连串离奇事件"}},{"pos":"","cn":"","en":"相关词组：chain up"}]},"examples":[{"en":"Volunteers formed a human chain to rescue precious items from the burning house.","cn":"志愿者排成一条长龙，从着火的房子里手传手把贵重物品抢救出来。"},{"en":"( figurative ) I've been chained to my desk all week (= because there was so much work).","cn":"我整个星期都在伏案工作，脱不开身。"}]},"change":{"media":{"uk":"media/uk/change__gb_1.mp3","us":"media/us/change__us_1.mp3"},"oxford":{"phon":"tʃeɪndʒ","pos":"verb","senses":[{"en":"to become different","cn":"改变；变化","g":"[intransitive]","sc":"become/make different","ex":{"en":"Rick hasn't changed. He looks exactly the same as he did at school.","cn":"里克一点儿没变，他和上学时一模一样。"}},{"en":"to make somebody/something different","cn":"使不同","g":"[transitive]","sc":"become/make different","ex":{"en":"Fame hasn't really changed him.","cn":"名声并没有使他有丝毫改变。"}},{"en":"to pass from one state or form into another; to make somebody/something pass from one state or form into another","cn":"（使）变换，改换，变成","g":"[intransitive, transitive]","sc":"become/make different","ex":{"en":"Wait for the traffic lights to change.","cn":"等待交通灯变换颜色。"}},{"en":"to stop having one state, position or direction and start having another","cn":"转换；变更","g":"[transitive]","sc":"become/make different","ex":{"en":"Leaves change colour in autumn.","cn":"树叶在秋天改变颜色。"}},{"en":"to replace one thing, person, service, etc. with something new or different","cn":"替代；替换；更换","g":"[transitive]","sc":"replace","ex":{"en":"I want to change my doctor.","cn":"我想另找一位医生看病。"}},{"en":"to exchange positions, places, etc. with somebody else, so that you have what they have, and they have what you have","cn":"互换；交换","g":"[transitive]","sc":"exchange","ex":{"en":"At half-time the teams change ends.","cn":"球队在半场时交换场地。"}},{"en":"to exchange money into the money of another country","cn":"把（货币）兑换（成另一种货币）","g":"[transitive]","sc":"money","ex":{"en":"I need to change some euros.","cn":"我需要兑换一些欧元。"}},{"en":"to exchange money for the same amount in different coins or notes","cn":"换零钱","g":"[transitive]","sc":"money","ex":{"en":"Can you change a £20 note?","cn":"你能把一张 20 英镑的钞票换成零钱吗？"}},{"en":"to exchange something that you have bought for something else, especially because there is something wrong with it; to give a customer a new item because there is something wrong with the one they have bought","cn":"退换；掉换","g":"[transitive]","lab":"British English","sc":"goods","ex":{"en":"This shirt I bought's too small—I'll have to change it for a bigger one.","cn":"我买的这件衬衫太小，得换件大一点的。"}},{"en":"to go from one bus, train, etc. to another in order to continue a journey","cn":"换乘；转乘","g":"[intransitive, transitive]","sc":"bus/train/plane","ex":{"en":"Where do I have to change?","cn":"我该在哪儿换车？"}},{"en":"to put on different or clean clothes","cn":"换衣服；更衣","g":"[intransitive, transitive]","lab":"especially North American English","sc":"clothes","ex":{"en":"I went into the bedroom to change.","cn":"我走进卧室更衣。"}},{"en":"to put clean clothes or a clean nappy on a baby","cn":"更换（衣服或尿布）","g":"[transitive]","sc":"baby","ex":{"en":"She can't even change a nappy.","cn":"她连换尿布都不会。"}},{"en":"to put clean sheets, etc. on a bed","cn":"换（床单等）","g":"[transitive]","sc":"bed","ex":{"en":"to change the sheets","cn":"换床单"}},{"en":"the act or result of something becoming different","cn":"改变；变化；变更；变革","g":"[countable, uncountable]","sc":"difference","ex":{"en":"We're hoping for a change in the weather.","cn":"我们希望天气有所变化。"},"pos":"noun"},{"en":"the process of replacing something with something new or different; a thing that is used to replace something","cn":"替代；更换；替代物","g":"[countable]","lab":"British English","sc":"replacing something","ex":{"en":"a change of address","cn":"地址的变更"},"pos":"noun"},{"en":"the fact of a situation, a place or an experience being different from what is usual and therefore likely to be interesting, fun, etc.","cn":"（会令人感兴趣、可喜等的）变化，变更","g":"[singular]","sc":"something new and interesting","ex":{"en":"Let's stay in for a change.","cn":"咱们改变一下，就待在家里吧。"},"pos":"noun"},{"en":"the money that you get back when you have paid for something giving more money than the amount it costs","cn":"找给的零钱；找头","g":"[uncountable]","sc":"money","ex":{"en":"Don't forget your change!","cn":"别忘了找给你的零钱！"},"pos":"noun"},{"en":"coins rather than paper money","cn":"辅币；硬币；分币","g":"[uncountable]","sc":"money","ex":{"en":"Do you have any change for the machine?","cn":"你有硬币投那台机器吗？"},"pos":"noun"},{"en":"an extra set of clothes, etc.","cn":"额外一套衣物（等）","g":"[countable]","sc":"of clothes","ex":{"en":"She packed a change of clothes for the weekend.","cn":"她已收拾好度周末的一套换洗衣物。"},"pos":"noun"},{"en":"an occasion when you go from one bus, train or plane to another during a journey","cn":"换车；转车；换机","g":"[countable]","sc":"of bus/train/plane","ex":{"en":"The journey involved three changes.","cn":"这趟旅行中转乘过三次。"},"pos":"noun"},{"en":"the menopause (= the time during which a woman gradually stops menstruating, usually at around the age of 50)","cn":"更年期","g":"[singular]","lab":"informal","sc":"in a woman's life","pos":"noun"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"变化;改变;变革","en":"If there is a change in something, it becomes different.","ex":{"en":"The ambassador appealed for a change in US policy","cn":"大使呼吁美国在政策上作出改变。"}},{"pos":"N-SING 单数名词","cn":"(令人愉快的)变化，改变","en":"If you say that something is a change or makes a change, you mean that it is enjoyable because it is different from what you are used to.","ex":{"en":"It is a complex system, but it certainly makes a change","cn":"这是个复杂的体系，不过确实有所改变。"}},{"pos":"VERB 动词","cn":"改用;改做","en":"If you change from one thing to another, you stop using or doing the first one and start using or doing the second.","ex":{"en":"His doctor increased the dosage but did not change to a different medication","cn":"他的医生加大了剂量，不过没有换药。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)变化;(使)改变","en":"When something changes or when you change it, it becomes different.","ex":{"en":"We are trying to detect and understand how the climates change","cn":"我们正努力探寻并理解气候是如何变化的。"}},{"pos":"VERB 动词","cn":"更换;替换","en":"To change something means to replace it with something new or different.","ex":{"en":"I paid £80 to have my car radio fixed and I bet all they did was change a fuse","cn":"我花80英镑让人把我车上的收音机修了修，可我敢肯定，他们只是换了根保险丝。"}},{"pos":"VERB 动词","cn":"换(衣服)；更衣","en":"When you change your clothes or change, you take some or all of your clothes off and put on different ones. →see usage note at:","ex":{"en":"Ben had merely changed his shirt","cn":"本仅仅换了件衬衫。"}},{"pos":"N-COUNT 可数名词","cn":"替换衣服；备用衣服","en":"A change of clothes is an extra set of clothes that you take with you when you go to stay somewhere or to take part in an activity.","ex":{"en":"He stuffed a bag with a few changes of clothing.","cn":"他往包里塞了几套换洗衣服。"}},{"pos":"VERB 动词","cn":"换(床单)","en":"When you change a bed or change the sheets, you take off the dirty sheets and put on clean ones.","ex":{"en":"After changing the bed, I would fall asleep quickly","cn":"换了床单，我很快就能睡着。"}},{"pos":"VERB 动词","cn":"给(婴儿)换尿布;换(尿布)","en":"When you change a baby or change its nappy or diaper, you take off the dirty one and put on a clean one.","ex":{"en":"She criticizes me for the way I feed or change him","cn":"她批评我不会给他喂奶、不会换尿布。"}},{"pos":"VERB 动词","cn":"转乘，换乘(交通工具);转车;转机","en":"When you change buses, trains, or planes or change, you get off one bus, train, or plane and get on to another in order to continue your journey.","ex":{"en":"At Glasgow I changed trains for Greenock","cn":"我在格拉斯哥改乘去格里诺克的火车。"}},{"pos":"VERB 动词","cn":"换(挡)","en":"When you change gear or change into another gear, you move the gear lever on a car, bicycle, or other vehicle in order to use a different gear.","ex":{"en":"The driver tried to change gear, then swerved","cn":"司机试图换挡，接着突然转向。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"找零;找头","en":"Your change is the money that you receive when you pay for something with more money than it costs because you do not have exactly the right amount of money.","ex":{"en":"'There's your change.' — 'Thanks very much.'","cn":"“您的找头。”——“多谢。”"}},{"pos":"N-UNCOUNT 不可数名词","cn":"硬币","en":"Change is coins, rather than paper money.","ex":{"en":"Thieves ransacked the office, taking a sack of loose change","cn":"窃贼洗劫了办公室，拿走了一口袋散币。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"零钱","en":"If you have change for larger notes, bills, or coins, you have the same value in smaller notes, bills, or coins, which you can give to someone in exchange.","ex":{"en":"The courier had change for a £10 note.","cn":"快递员能破开10英镑的纸币。"}},{"pos":"VERB 动词","cn":"兑换(货币);换(零钱)","en":"When you change money, you exchange it for the same amount of money in a different currency, or in smaller notes, bills, or coins.","ex":{"en":"You can expect to pay the bank a fee of around 1% to 2% every time you change money","cn":"每次到银行换币都会要求付1%到2%的手续费。"}},{"pos":"PHRASE 短语","cn":"换换口味;变个花样","en":"If you say that you are doing something or something is happening for a change, you mean that you do not usually do it or it does not usually happen, and you are happy to be doing it or that it is happening.","ex":{"en":"Now let me ask you a question, for a change","cn":"现在换我来问你一个问题吧。"}},{"pos":"","cn":"","en":"to change for the better→see: ; to change hands→see: ; a change of heart→see: ; to change your mind→see: ; to change places→see: ; to ring the changes→see: ; to change the subject→see: ; to change tack→see: ; to change your tune→see: ; to change for the worse→see: ;"},{"pos":"","cn":"","en":"相关词组：change down change over change up"}]},"examples":[{"en":"Wait until it happens to him — he'll soon change his tune.","cn":"等着瞧吧，到他遇上这事时，他很快就会改变看法了。"},{"en":"There are baby changing facilities in all our stores.","cn":"我们所有的商店都有供顾客给婴儿换尿布的地方。"}]},"chemistry":{"oxford":{"phon":"ˈkemɪstri","pos":"noun","senses":[{"en":"the scientific study of the structure of substances, how they react when combined or in contact with one another, and how they behave under different conditions","cn":"化学","ex":{"en":"a degree in chemistry","cn":"化学学位"}},{"en":"the chemical structure and behaviour of a particular substance","cn":"物质的化学组成（或性质）","lab":"specialist","ex":{"en":"the chemistry of copper","cn":"铜的化学性质"}},{"en":"the relationship between two people, usually a strong sexual attraction","cn":"（常指有强烈性吸引力的）两人间的关系","ex":{"en":"sexual chemistry","cn":"相互吸引的两性关系"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"化学","en":"Chemistry is the scientific study of the structure of substances and of the way that they react with other substances."},{"pos":"N-UNCOUNT 不可数名词","cn":"(物质的)化学组成，化学成分，化学反应","en":"The chemistry of an organism or a material is the chemical substances that make it up and the chemical reactions that go on inside it.","ex":{"en":"We have literally altered the chemistry of our planet's atmosphere","cn":"我们确实改变了地球大气层的化学构成。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(互相之间的)吸引，亲密","en":"If you say that there is chemistry between two people, you mean that is obvious they are attracted to each other or like each other very much.","ex":{"en":"...the extraordinary chemistry between Ingrid and Bogart","cn":"英格丽和鲍嘉之间的情意绵绵"}}]},"media":{"uk":"media/uk/chemistry__gb_1.mp3","us":"media/us/chemistry__us_1.mp3"},"examples":[{"en":"The patient's blood chemistry was monitored regularly.","cn":"那名患者的血液化学成分受到了定时的监测。"},{"en":"The chemistry just wasn't right.","cn":"他俩就是擦不出火花。"}]},"champagne":{"media":{"uk":"media/uk/champagne__gb_1.mp3","us":"media/us/champagne__us_1.mp3"},"oxford":{"phon":"ʃæmˈpeɪn","pos":"noun","senses":[{"en":"a sparkling white wine (= one with bubbles) produced in the Champagne region of France, typically drunk on special occasions","cn":"香槟酒","ex":{"en":"a glass of champagne","cn":"一杯香槟酒"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"香槟(酒)","en":"Champagne is an expensive French white wine with bubbles in. It is often drunk to celebrate something."},{"pos":"PHRASE 短语","cn":"庆贺;庆祝","en":"If you say that champagne corks are popping, you mean that people are celebrating something."}]},"examples":[{"en":"a glass of champagne","cn":"一杯香槟酒"}]},"chandelier":{"media":{"uk":"media/uk/chandelier__gb_1.mp3","us":"media/us/chandelier__us_1.mp3","img":["media/ldoce/img/chandelier.jpg"]},"oxford":{"phon":"ˌʃændəˈlɪə(r)","pos":"noun","senses":[{"en":"a large round frame hanging from the ceiling, with branches that hold lights or candles. Some chandeliers are decorated with many small pieces of glass.","cn":"枝形吊灯","ex":{"en":"a crystal chandelier","cn":"水晶玻璃枝形吊灯。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"枝形吊灯","en":"A chandelier is a large, decorative frame which holds light bulbs or candles and hangs from the ceiling."}]}},"chuckle":{"media":{"uk":"media/uk/chuckle__gb_1.mp3","us":"media/us/chuckle__us_1.mp3"},"oxford":{"phon":"ˈtʃʌkl","pos":"noun","senses":[{"en":"an act of laughing quietly","cn":"低声轻笑；轻声地笑","ex":{"en":"She gave a chuckle of delight.","cn":"她愉快地轻声笑起来。"}},{"en":"to laugh quietly","cn":"低声轻笑；轻声地笑","ex":{"en":"She chuckled at the memory.","cn":"想起这件事她就暗自发笑。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"低声轻笑;偷笑","en":"When you chuckle, you laugh quietly.","ex":{"en":"The banker chuckled and said, 'Of course not.'","cn":"银行家暗自发笑并说道：“当然不。”"}}]},"examples":[{"en":"She chuckled at the memory.","cn":"想起这件事她就暗自发笑。"},{"en":"She gave a chuckle of delight.","cn":"她高兴得轻声笑了出来。"}]},"china":{"media":{"uk":"media/uk/china__gb_1.mp3","us":"media/us/china__us_1.mp3"},"oxford":{"phon":"ˈtʃaɪnə","pos":"noun","senses":[{"en":"white clay that is baked and used for making cups, plates, etc.","cn":"瓷；瓷料","ex":{"en":"a china vase","cn":"瓷花瓶"}},{"en":"cups, plates, etc. that are made of china","cn":"瓷制品；瓷器","ex":{"en":"She got out the best china.","cn":"她制作最好的瓷器。"}},{"en":"a country in East Asia","cn":"中国（东亚国家）"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"瓷;瓷料","en":"China is a hard white substance made from clay. It is used to make things such as cups, bowls, plates, and ornaments.","ex":{"en":"...a small boat made of china.","cn":"瓷制小船"}},{"pos":"N-UNCOUNT 不可数名词","cn":"瓷器;瓷制品","en":"Cups, bowls, plates, and ornaments made of china are referred to as china .","ex":{"en":"Judy collects blue and white china.","cn":"朱迪收集青花瓷。"}},{"pos":"","cn":"","en":"a bull in a china shop→see: ;"}]},"examples":[{"en":"She got out the best china.","cn":"她造出最好的瓷器。"},{"en":"a china vase","cn":"瓷花瓶"}]},"chests":{"oxford":{"phon":"tʃest","pos":"noun","senses":[{"en":"the top part of the front of the body, between the neck and the stomach","cn":"胸部；胸膛"},{"en":"( in adjectives","cn":"构成形容词 ) having the type of chest mentioned 有 … 胸的；胸部 … 的"}]},"media":{"uk":"media/uk/chest__gb_1.mp3","us":"media/us/chest__us_1.mp3"}},"checking":{"oxford":{"phon":"tʃek","pos":"verb","senses":[{"en":"to examine sth to see if it is correct, safe or acceptable","cn":"检查；审查；核查；检验"},{"en":"to find out if sth/sb is present, correct or true or if sth is how you think it is","cn":"查明；查看；核实；弄确实"}]},"media":{"uk":"media/uk/check__gb_1.mp3","us":"media/us/check__us_1.mp3"}},"challenged":{"oxford":{"phon":"ˈtʃælɪndʒd","pos":"adjective","senses":[{"en":"a way of referring to somebody who is disabled in some way","cn":"伤残的；有残疾的","lab":"humorous","ex":{"en":"a competition for physically challenged athletes","cn":"残疾运动员的比赛"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有…障碍的，有…缺陷的(常与不恰当的词语连用表示诙谐)","en":"If you say that someone is challenged in a particular way, you mean that they have a disability in that area. Challenged is often combined with inappropriate words for humorous effect.","ex":{"en":"...terms like 'vertically-challenged' — meaning short","cn":"像“垂直缺陷”这种表示身材矮小的词语"}}]},"media":{"uk":"media/uk/challenged__gb_1.mp3","us":"media/us/challenged__us_1.mp3"},"examples":[{"en":"a competition for physically challenged athletes","cn":"残疾运动员的比赛"},{"en":"( humorous ) I'm financially challenged at the moment (= I have no money).","cn":"我眼下身无分文。"}]},"chandeliers":{"oxford":{"phon":"ˌʃændəˈlɪə(r)","pos":"noun","senses":[{"en":"a large round frame with branches that hold lights or candles. Chandeliers are decorated with many small pieces of glass and hang from the ceiling.","cn":"枝形吊灯"}]},"media":{"uk":"media/uk/chandelier__gb_1.mp3","us":"media/us/chandelier__us_1.mp3"}},"cheap":{"media":{"uk":"media/uk/cheap__gb_1.mp3","us":"media/us/cheap__us_1.mp3"},"oxford":{"phon":"tʃiːp","pos":"adjective","senses":[{"en":"costing little money or less money than you expected","cn":"花钱少的；便宜的；廉价的","sc":"low price","ex":{"en":"cheap imports/flights","cn":"廉价进口商品／航班"}},{"en":"charging low prices","cn":"收费低廉的","lab":"British English","sc":"low price","ex":{"en":"a cheap restaurant/hotel","cn":"收费低廉的餐馆／旅馆"}},{"en":"low in price and quality","cn":"价低质劣的","lab":"disapproving","sc":"poor quality","ex":{"en":"cheap perfume/jewellery/shoes","cn":"低价劣质香水／珠宝／鞋"}},{"en":"unpleasant or unkind and rather obvious","cn":"令人讨厌的；明显不友好的；不和善的","sc":"unkind","ex":{"en":"I was tired of his cheap jokes at my expense.","cn":"我讨厌他拿我开低级庸俗的玩笑。"}},{"en":"having a low status and therefore not deserving respect","cn":"卑微的；卑贱的；可鄙的","lab":"disapproving","sc":"low status","ex":{"en":"He's just a cheap crook.","cn":"他简直是个卑鄙的骗子。"}},{"en":"not liking to spend money","cn":"小气的；抠门儿的","lab":"North American English","sc":"not generous","ex":{"en":"Don't be so cheap!","cn":"别这么小气！"}},{"en":"for a low price","cn":"低价地；廉价地；便宜地","ex":{"en":"I got this dress cheap in a sale.","cn":"这件衣服是我在大减价时便宜买的。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"便宜的;不贵的","en":"Goods or services that are cheap cost less money than usual or than you expected.","ex":{"en":"I'm going to live off campus if I can find somewhere cheap enough","cn":"要是能找到足够便宜的地方，我就不在校园里住了。"}},{"pos":"ADJ 形容词","cn":"不值钱的;质次价低的","en":"If you describe goods as cheap, you mean they cost less money than similar products but their quality is poor.","ex":{"en":"Don't resort to cheap copies; save up for the real thing.","cn":"别买廉价的仿冒品，攒点钱买正品吧。"}},{"pos":"ADJ 形容词","cn":"（劳动力）廉价的","en":"If you describe the cost of someone's work as cheap, you disapprove of the way people are taking advantage of a situation to pay someone less than they should for the work that they do.","ex":{"en":"...unscrupulous employers who treat children as a cheap source of labour.","cn":"把儿童当廉价劳动力使用的黑心雇主"}},{"pos":"ADJ 形容词","cn":"(言行)讨便宜的，刻薄的，不怀好意的","en":"If you describe someone's remarks or actions as cheap, you mean that they are unkindly or insincerely using a situation to benefit themselves or to harm someone else.","ex":{"en":"These tests will inevitably be used by politicians to make cheap political points.","cn":"这些测试必然会被政客们不失时机地拿去大做政治文章。"}},{"pos":"ADJ 形容词","cn":"吝啬的;小气的","en":"If you describe someone as cheap, you are criticizing them for being unwilling to spend money.","ex":{"en":"Oh, please, Dad, just this once don't be cheap.","cn":"哦，求求你，爸爸，就这一回，别抠门儿了。"}},{"pos":"PHRASE 短语","cn":"人命不值钱;人命如草芥","en":"You use life is cheap or life has become cheap to refer to a situation in which nobody cares that large numbers of people are dying.","ex":{"en":"We will end up living in a society where life is cheap.","cn":"我们最终将生活在一个视人命为儿戏的社会。"}},{"pos":"PHRASE 短语","cn":"便宜第一;节省地","en":"If someone does or buys something on the cheap, they spend less money than they should because they are more concerned with what it costs than with its quality.","ex":{"en":"Most modern housing estates are terrible and inevitably done on the cheap.","cn":"现在的房子大多质量差劲透顶，肯定都是偷工减料盖起来的。"}}]},"examples":[{"en":"Personal computers are cheap and getting cheaper.","cn":"个人电脑现在价格便宜，以后还会越来越便宜。"},{"en":"The printer isn't exactly cheap at £200.","cn":"价格为 200 英镑的打印机并不是很便宜。"}]},"cheating":{"oxford":{"phon":"tʃiːt","pos":"verb","senses":[{"en":"to trick sb or make them believe sth which is not true","cn":"欺骗；蒙骗"},{"en":"to act in a dishonest way in order to gain an advantage, especially in a game, a competition, an exam, etc. （","cn":"尤指在游戏、比赛、考试等中）作弊，舞弊"}]}},"champion":{"media":{"uk":"media/uk/champion__gb_1.mp3","us":"media/us/champion__us_1.mp3"},"oxford":{"phon":"ˈtʃæmpiən","pos":"noun","senses":[{"en":"a person, team, etc. that has won a competition, especially in a sport","cn":"冠军；第一名；优胜者","ex":{"en":"the world/European/national/Olympic champion","cn":"世界／欧洲／全国／奥运会冠军"}},{"en":"a person who fights for, or speaks in support of, a group of people or a belief","cn":"斗争者；捍卫者；声援者；拥护者","ex":{"en":"She was a long-term champion of animal rights and environmental protection.","cn":"她是动物权利和环境保护的长期倡导者。"}},{"en":"to fight for or speak in support of a group of people or a belief","cn":"为…而斗争；捍卫；声援","ex":{"en":"He has always championed the cause of gay rights.","cn":"他一直在为争取同性恋者的权利而斗争。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"冠军","en":"A champion is someone who has won the first prize in a competition, contest, or fight.","ex":{"en":"...a former Olympic champion","cn":"前奥运会冠军"}},{"pos":"N-COUNT 可数名词","cn":"支持者；拥护者；捍卫者","en":"If you are a champion of a person, a cause, or a principle, you support or defend them.","ex":{"en":"He received acclaim as a champion of the oppressed","cn":"他因维护被压迫者的利益而备受称赞。"}},{"pos":"VERB 动词","cn":"支持；拥护；捍卫","en":"If you champion a person, a cause, or a principle, you support or defend them.","ex":{"en":"He passionately championed the poor","cn":"他满腔热情地捍卫穷人的利益。"}}]},"examples":[{"en":"He has always championed the cause of gay rights.","cn":"他一直在为争取同性恋者的权利而斗争。"},{"en":"She was a champion of the poor all her life.","cn":"她终身都是穷苦人的卫士。"}]},"chimpanzee":{"media":{"img":["media/pic/primates_comp.jpg","media/thumb/chimpanzee.jpg"],"uk":"media/uk/chimpanzee__gb_1.mp3","us":"media/us/chimpanzee__us_1.mp3"},"oxford":{"phon":"ˌtʃɪmpænˈziː","pos":"noun","senses":[{"en":"a small intelligent African ape (= an animal like a large monkey without a tail)","cn":"黑猩猩"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"黑猩猩","en":"A chimpanzee is a kind of small African ape."}]}},"chrysanthemum":{"media":{"img":["media/pic/flowerlabels_flowers_comp.jpg","media/thumb/chrysanthemum.jpg"],"uk":"media/uk/chrysanthemum__gb_1.mp3","us":"media/us/chrysanthemum__us_1.mp3"},"oxford":{"phon":"krɪˈzænθəməm","pos":"noun","senses":[{"en":"a large, brightly coloured garden flower that is like a ball in shape and is made up of many long narrow petals","cn":"菊花"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"菊(花)","en":"A chrysanthemum is a large garden flower with many long, thin petals."}]}},"chat":{"oxford":{"phon":"tʃæt","pos":"verb","senses":[{"en":"to talk in a friendly, informal way to somebody","cn":"闲聊；闲谈；聊天","g":"[intransitive]","ex":{"en":"I'm sorry I can't stop to chat.","cn":"对不起，我不能停下来聊天。"}},{"en":"to exchange messages with somebody on the internet, when you can see and reply to messages immediately and have a written conversation","cn":"（在网上）聊天","g":"[intransitive]","ex":{"en":"I've been chatting online with my best friend.","cn":"我一直在网上和我最好的朋友聊天。"}},{"en":"a friendly informal conversation","cn":"闲聊；闲谈；聊天","g":"[countable]","ex":{"en":"I just called in for a chat.","cn":"我只是来聊聊天。"},"pos":"noun"},{"en":"talking, especially informal conversation","cn":"（尤指非正式的）谈话，讲话","g":"[uncountable]","ex":{"en":"After a few more minutes of chat, she left.","cn":"又聊了几分钟，她就走了。"},"pos":"noun"},{"en":"communication between people on the internet in which they see and reply to messages immediately and have a written conversation","cn":"网上聊天","g":"[uncountable, countable]","ex":{"en":"Fans are invited to an online chat.","cn":"粉丝获邀参与网上聊天。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"聊天;闲聊","en":"When people chat, they talk to each other in an informal and friendly way.","ex":{"en":"The women were chatting","cn":"女人们在聊天。"}},{"pos":"","cn":"","en":"相关词组：chat up"}]},"media":{"uk":"media/uk/chat__gb_1.mp3","us":"media/us/chat__us_1.mp3"},"examples":[{"en":"My kids spend hours chatting on the phone to their friends.","cn":"我的几个孩子在电话上和朋友聊天一聊就是几个小时。"},{"en":"Within minutes of being introduced they were chatting away like old friends.","cn":"他们经人介绍认识才几分钟，便一见如故地聊个没完。"}]},"chef":{"media":{"uk":"media/uk/chef__gb_1.mp3","us":"media/us/chef__us_1.mp3","img":["media/ldoce/img/chef.jpg"]},"oxford":{"phon":"ʃef","pos":"noun","senses":[{"en":"a person whose job is to cook, especially the most senior person in a restaurant, hotel, etc.","cn":"厨师；大厨；（尤指餐馆、酒店等的）主厨，厨师长","ex":{"en":"a new book by celebrity chef Jamie Oliver","cn":"明星大厨杰米·奥利弗写的新书"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(饭店、宾馆的)厨师","en":"A chef is a cook in a restaurant or hotel."}]},"examples":[{"en":"a master chef","cn":"手艺高超的厨师长"},{"en":"a pastry chef","cn":"糕饼师傅"}]},"cheated":{"oxford":{"phon":"tʃiːt","pos":"verb","senses":[{"en":"to trick sb or make them believe sth which is not true","cn":"欺骗；蒙骗"},{"en":"to act in a dishonest way in order to gain an advantage, especially in a game, a competition, an exam, etc. （","cn":"尤指在游戏、比赛、考试等中）作弊，舞弊"}]}},"child":{"media":{"uk":"media/uk/child__gb_1.mp3","us":"media/us/child__us_1.mp3","img":["media/ldoce/img/toddler.jpg"]},"oxford":{"phon":"tʃaɪld","pos":"noun","senses":[{"en":"a young human who is not yet an adult","cn":"儿童；小孩","lab":"especially US English","ex":{"en":"a child of 3/a 3-year-old child","cn":"三岁小孩"}},{"en":"a son or daughter of any age","cn":"儿子；女儿","ex":{"en":"They have three grown-up children.","cn":"他们有三个成年的孩子。"}},{"en":"a person who is strongly influenced by the ideas and attitudes of a particular time or person","cn":"深受…影响的人","ex":{"en":"a child of the 90s","cn":"属于 20 世纪 90 年代的人"}},{"en":"an adult who behaves like a child and is not mature or responsible","cn":"孩子气的人；幼稚的人；不负责任的人","lab":"disapproving"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小孩;孩子;儿童","en":"A child is a human being who is not yet an adult.","ex":{"en":"When I was a child I lived in a country village","cn":"我小时候生活在一个小乡村里。"}},{"pos":"N-COUNT 可数名词","cn":"儿女;子女","en":"Someone's children are their sons and daughters of any age.","ex":{"en":"How are the children?","cn":"孩子们都好吧？"}}]},"examples":[{"en":"a support group for adult children of alcoholics","cn":"帮助酗酒者成年子女的小组"},{"en":"They have three grown-up children.","cn":"他们有三个成年的孩子。"}]},"chart":{"media":{"uk":"media/uk/chart__gb_1.mp3","us":"media/us/chart__us_1.mp3"},"oxford":{"phon":"tʃɑːt","pos":"noun","senses":[{"en":"a diagram, lists of figures, etc. that shows information","cn":"图表","g":"[countable]","ex":{"en":"Some shares have lost two-thirds of their value since being issued (see chart).","cn":"有些股票自发行以来已贬值三分之二（见图表）。"}},{"en":"a detailed map of the sea","cn":"海图","g":"[countable]","ex":{"en":"a naval chart","cn":"海军航图"}},{"en":"a list, produced each week, of the songs or albums that have sold the most copies or been downloaded or listened to via streaming the most frequently","cn":"（歌曲或唱片每周销售、下载或流播数量）排行榜","g":"[plural]","lab":"especially British English","ex":{"en":"The album went straight into the charts at number 1.","cn":"这张专辑一进入流行唱片排行榜便占首位。"}},{"en":"to record or follow the progress or development of somebody/something","cn":"记录，跟踪（进展或发展）","ex":{"en":"The exhibition charts the history of the palace.","cn":"展览记载了这座王宫的历史。"},"pos":"verb"},{"en":"to plan a course of action","cn":"计划行动步骤；制订计划","ex":{"en":"She had carefully charted her route to the top of her profession.","cn":"她周密地制订了达到她职业巅峰的行动计划。"},"pos":"verb"},{"en":"to make a map of an area","cn":"绘制…的地图","ex":{"en":"Cook charted the coast of New Zealand in 1768.","cn":"库克于 1768 年绘制了新西兰的海岸图。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"图表;图片;曲线图","en":"A chart is a diagram, picture, or graph which is intended to make information easier to understand.","ex":{"en":"Male unemployment was 14.2%, compared with 5.8% for women (see chart on next page)","cn":"相比女性的5.8%，男性失业率为14.2%(见下页图表)。"}},{"pos":"N-COUNT 可数名词","cn":"海图;星位图","en":"A chart is a map of the sea or stars.","ex":{"en":"...charts of Greek waters.","cn":"希腊海域图"}},{"pos":"VERB 动词","cn":"绘制…的地图(或海图、星位图)","en":"If you chart an area of land, sea, or sky, or a feature in that area, you make a map of the area or show the feature in it.","ex":{"en":"Portuguese explorers had charted the west coast of Africa as far as Sierra Leone","cn":"葡萄牙探险家已经绘制出了远至塞拉里昂的非洲西海岸地图。"}},{"pos":"N-COUNT 可数名词","cn":"(唱片销售量的)排行榜","en":"The charts are the official lists that show which CDs have sold the most copies each week.","ex":{"en":"This album confirmed The Orb's status as national stars, going straight to Number One in the charts","cn":"这张专辑确立了The Orb作为全国明星的地位，销量直升至排行榜首位。"}},{"pos":"VERB 动词","cn":"记录，跟踪(进展)","en":"If you chart the development or progress of something, you observe it and record or show it. You can also say that a report or graph charts the development or progress of something.","ex":{"en":"One GP has charted a dramatic rise in local childhood asthma since the M25 was built nearby","cn":"一位全科医生跟踪记录发现，自从附近修建了25号高速公路以来，当地哮喘病患儿数量急剧增加。"}},{"pos":"VERB 动词","cn":"规定，制订(行动计划)","en":"If a person or plan charts a course of action, they describe what should be done in order to achieve something or to make progress in the future.","ex":{"en":"We've charted a possible way forward","cn":"我们已经制订了下一步可能的计划。"}}]},"examples":[{"en":"Cook charted the coast of New Zealand in 1768.","cn":"库克于 1768 年绘制了新西兰的海岸图。"},{"en":"She had carefully charted her route to the top of her profession.","cn":"她周密地制订了达到她职业巅峰的行动计划。"}]},"christianity":{"oxford":{"phon":"ˌkrɪstiˈænəti","pos":"noun","senses":[{"en":"the religion that is based on the teachings of Jesus Christ and the belief that he was the son of God","cn":"基督教","ex":{"en":"Christianity spread rapidly in the first century.","cn":"基督教在一世纪迅速传播。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"基督教","en":"Christianity is a religion that is based on the teachings of Jesus Christ and the belief that he was the son of God.","ex":{"en":"He converted to Christianity that day.","cn":"那天，他皈依了基督教。"}}]},"media":{"uk":"media/uk/christianity__gb_1.mp3","us":"media/us/christianity__us_1.mp3"}},"character":{"media":{"img":["media/pic/ideogram_comp.jpg","media/thumb/character.jpg"],"uk":"media/uk/character__gb_1.mp3","us":"media/us/character__us_1.mp3"},"oxford":{"phon":"ˈkærəktə(r)","pos":"noun","senses":[{"en":"a person or an animal in a book, play or film","cn":"（书、戏剧或电影中的）人物，角色","g":"[countable]","lab":"US English","sc":"in book/play/movie","ex":{"en":"the main character in the film","cn":"电影的主角"}},{"en":"a particular type of person in a play, film or TV show","cn":"（戏剧、电影或电视节目中形象鲜明的）性格演员，个性角色","sc":"in book/play/movie","ex":{"en":"He has developed a skill set from his character work in film, TV and stage.","cn":"他从电影、电视和舞台上的角色工作中发展出了一套技能。"}},{"en":"all the qualities and features that make a person different from others","cn":"（人的）品质，性格","g":"[countable, usually singular]","sc":"qualities/features","ex":{"en":"to have a strong/weak character","cn":"个性强／软弱"}},{"en":"strong personal qualities such as the ability to deal with difficult or dangerous situations","cn":"勇气；毅力","g":"[uncountable]","lab":"approving","sc":"qualities/features","ex":{"en":"Everyone admires her strength of character and determination.","cn":"每一个人都钦佩她坚强的性格和决心。"}},{"en":"the way that something is; a particular quality or feature that a thing, an event or a place has","cn":"（事物、事件或地方的）特点，特征，特色","g":"[countable, usually singular, uncountable]","sc":"qualities/features","ex":{"en":"The character of the neighbourhood hasn't changed at all.","cn":"这片街区的风貌依旧。"}},{"en":"the interesting or unusual quality that a place or a person has","cn":"（地方或人的）与众不同之处，特色","g":"[uncountable]","lab":"usually approving","sc":"qualities/features","ex":{"en":"The modern hotels here have no real character.","cn":"此处的现代化旅馆毫无特色可言。"}},{"en":"a person, particularly an unpleasant or strange one","cn":"（令人讨厌的或古怪的）人","g":"[countable]","lab":"informal","sc":"strange/interesting person","ex":{"en":"There were some really strange characters hanging around the bar.","cn":"有些不三不四的人在酒吧周围游荡。"}},{"en":"an interesting or unusual person","cn":"（有趣的或不同寻常的）人","g":"[countable]","lab":"informal","sc":"strange/interesting person","ex":{"en":"She's a character!","cn":"她真是个有趣的人！"}},{"en":"the opinion that people have of you, particularly of whether you can be trusted or relied on","cn":"名誉；声望；名气","g":"[countable, uncountable]","lab":"formal","sc":"reputation","ex":{"en":"a slur/attack on his character","cn":"对他名誉的诋毁／攻击"}},{"en":"a letter, sign, mark or symbol used in writing, in printing or on computers","cn":"（书写、印刷或计算机上的）文字，字母，符号","g":"[countable]","sc":"symbol/letter","ex":{"en":"These are the Chinese characters meaning ‘wind’ and ‘water’.","cn":"这些汉字的意思是wind（风）和water（水）。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（人的）性格，个性;(地方的)特点","en":"The character of a person or place consists of all the qualities they have that make them distinct from other people or places.","ex":{"en":"Perhaps there is a negative side to his character that you haven't seen yet","cn":"或许，他性格中不好的一面你还没有看见。"}},{"pos":"N-SING 单数名词","cn":"特点;特征;特色","en":"If something has a particular character, it has a particular quality.","ex":{"en":"The financial concessions granted to British Aerospace were, he said, of a precarious character","cn":"他说，向英国宇航公司给予财政优惠未获证实。"}},{"pos":"N-SING 单数名词","cn":"(某地人具有的)特点，特色，特征","en":"You can use character to refer to the qualities that people from a particular place are believed to have.","ex":{"en":"Individuality is a valued and inherent part of the British character.","cn":"个性鲜明是英国人固有的、也是他们看重的特点。"}},{"pos":"N-COUNT 可数名词","cn":"人物;人","en":"You use character to say what kind of person someone is. For example, if you say that someone is a strange character, you mean they are strange.","ex":{"en":"It's that kind of courage and determination that makes him such a remarkable character","cn":"就是那种勇气和决心使他成为如此了不起的人。"}},{"pos":"N-VAR 可变名词","cn":"人品;品行","en":"Your character is your personality, especially how reliable and honest you are. If someone is of good character, they are reliable and honest. If they are of bad character, they are unreliable and dishonest.","ex":{"en":"He's begun a series of personal attacks on my character","cn":"他开始对我进行一连串的人身攻击。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(坚强的)个性，性格;人格力量","en":"If you say that someone has character, you mean that they have the ability to deal effectively with difficult, unpleasant, or dangerous situations.","ex":{"en":"She showed real character in her attempts to win over the crowd","cn":"她在努力获得民众的支持时，表现出真正的人格力量。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(地方的)与众不同之处，特色","en":"If you say that a place has character, you mean that it has an interesting or unusual quality which makes you notice it and like it.","ex":{"en":"An ugly shopping centre stands across from one of the few buildings with character.","cn":"一座难看的购物中心对面，耸立着为数不多的几幢别具特色的大楼之一。"}},{"pos":"N-COUNT 可数名词","cn":"(电影、书、戏剧里的)人物，角色","en":"The characters in a film, book, or play are the people that it is about.","ex":{"en":"The film is autobiographical and the central character is played by Collard himself","cn":"这部电影是自传体，其中的主角由科勒德亲自扮演。"}},{"pos":"N-COUNT 可数名词","cn":"有趣的人;怪人;滑稽的人","en":"If you say that someone is a character, you mean that they are interesting, unusual, or amusing.","ex":{"en":"He'll be sadly missed. He was a real character.","cn":"人们会非常怀念他的，他可真是个有趣的人啊。"}},{"pos":"N-COUNT 可数名词","cn":"字母;数字;文字；字符","en":"A character is a letter, number, or other symbol that is written or printed."},{"pos":"PHRASE 短语","cn":"符合/不符合…的性格(或特点)","en":"If someone's actions are in character, they are doing what you would expect them to do, knowing what kind of person they are. If their actions are out of character, they are not doing what you would expect them to do.","ex":{"en":"It was entirely in character for Rachel to put her baby first","cn":"把自己的婴孩放在第一位，这完全符合雷切尔的性格。"}}]},"examples":[{"en":"The new wing of the museum was not really in character with the rest of the building.","cn":"博物馆新建的侧翼楼与大楼其他部分的风格有些不一样。"},{"en":"He showed great character returning to the sport after his accident.","cn":"他在出了事故后仍能重返体坛表现出他顽强的毅力。"}]},"challenge":{"media":{"uk":"media/uk/challenge__gb_1.mp3","us":"media/us/challenge__us_1.mp3"},"oxford":{"phon":"ˈtʃælɪndʒ","pos":"noun","senses":[{"en":"a new or difficult task that tests somebody’s ability and skill","cn":"挑战；艰巨任务","ex":{"en":"a tough/major/significant challenge","cn":"严峻／重大／巨大的挑战"}},{"en":"an invitation or a suggestion to somebody that they should enter a competition, fight, etc.","cn":"挑战书；（比赛、打斗等的）邀请，提议","ex":{"en":"She accepted his challenge to a debate on the issue.","cn":"她接受了他对这个问题进行辩论的挑战。"}},{"en":"a statement or an action that shows that somebody refuses to accept something and questions whether it is right, legal, etc.","cn":"质询；质疑；提出异议","ex":{"en":"Their legal challenge was unsuccessful.","cn":"他们提出的法律质疑未能成功。"}},{"en":"to question whether a statement or an action is right, legal, etc.; to refuse to accept something","cn":"对…怀疑（或质疑）；拒绝接受","ex":{"en":"His legal team immediately sought to challenge the decision.","cn":"他的法律团队立即试图对这一裁定提出质疑。"},"pos":"verb"},{"en":"to invite somebody to enter a competition, fight, etc.; to suggest strongly that somebody should do something (especially when you think that they might be unwilling to do it)","cn":"向（某人）挑战；（尤指在对方不情愿时）强烈建议（某人做某事）","ex":{"en":"Mike challenged me to a game of chess.","cn":"迈克硬逼着要和我下一盘棋。"},"pos":"verb"},{"en":"to enter into to a competition against somebody to achieve something or take something from them","cn":"挑战书；（比赛、打斗等的）邀请，提议","g":"[intransitive, transitive]","ex":{"en":"She was poised to challenge for the party leadership.","cn":"她已准备好竞争党内领导地位。"},"pos":"verb"},{"en":"to test somebody’s/your ability and skills, especially in an interesting way","cn":"考查，考验（能力和技巧）","ex":{"en":"The job doesn't really challenge her.","cn":"这项工作不能真正考验出她的能力。"},"pos":"verb"},{"en":"to order somebody to stop and say who they are or what they are doing","cn":"盘问；查问","ex":{"en":"We were challenged by police at the border.","cn":"我们在边境受到警察盘问。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"挑战;难题","en":"A challenge is something new and difficult which requires great effort and determination.","ex":{"en":"I like a big challenge and they don't come much bigger than this","cn":"我喜欢大的挑战，而所有挑战中再没有比这更大的了。"}},{"pos":"PHRASE 短语","cn":"(成功地)应对挑战，迎接挑战","en":"If someone rises to the challenge, they act in response to a difficult situation which is new to them and are successful.","ex":{"en":"The new Germany must rise to the challenge of its enhanced responsibilities","cn":"一个崭新的德国必须迎接挑战，承担更多的责任。"}},{"pos":"N-VAR 可变名词","cn":"(对真实性、价值、权威等提出的)怀疑，质疑","en":"A challenge to something is a questioning of its truth or value. A challenge to someone is a questioning of their authority.","ex":{"en":"The demonstrators have now made a direct challenge to the authority of the government.","cn":"示威者现在直接对政府的权威发出了质疑。"}},{"pos":"VERB 动词","cn":"怀疑，质疑(真实性、价值、权威等)","en":"If you challenge ideas or people, you question their truth, value, or authority.","ex":{"en":"Democratic leaders have challenged the president to sign the bill","cn":"民主党领袖对总统签署这项法案提出了质疑。"}},{"pos":"VERB 动词","cn":"挑战；向…下战书","en":"If you challenge someone, you invite them to fight or compete with you in some way.","ex":{"en":"A mum slashed a neighbour's car tyre and challenged her to a fight after their daughters fell out","cn":"两家的女儿吵起来后，一个妈妈划破了邻居的车胎，说要和她较量较量。"}},{"pos":"VERB 动词","cn":"(警卫)盘问，查问","en":"If someone is challenged by a guard, they are ordered to stop and say who they are or why they are there.","ex":{"en":"The men apparently opened fire after they were challenged by a patrol.","cn":"显然，那些人是在受到一支巡逻队的盘问后开的火。"}}]},"examples":[{"en":"Destruction of the environment is one of the most serious challenges we face.","cn":"环境的破坏是我们所面临的最严峻的挑战之一。"},{"en":"The role will be the biggest challenge of his acting career.","cn":"扮演这个角色将是他演艺生涯中最大的挑战。"}]},"check-in":{"oxford":{"phon":"ˈtʃek ɪn","pos":"noun","senses":[{"en":"the place where you go to at an airport to leave your bags, cases, etc. and show your ticket","cn":"（机场的）登机手续办理处","g":"[countable, uncountable]","ex":{"en":"The airline apologizes for long delays at check-ins today.","cn":"航空公司为今天办理登机手续耽误了很多时间而道歉。"}},{"en":"the act of confirming your intention to take a particular flight and your personal details either at an airport or using a computer","cn":"（在机场或电脑上）办理登机手续，值机","g":"[uncountable]","lab":"British English","ex":{"en":"Do you know your check-in time?","cn":"你知道办理登机手续的时间吗？"}},{"en":"the time when you arrive at a hotel at the start of your stay","cn":"登记入住宾馆；办理入住手续","g":"[countable, uncountable]","ex":{"en":"We can arrange an early check-in.","cn":"我们可以安排提前办理入住手续。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(机场的)检票口，办理登机手续处","en":"At an airport, a check-in is the counter or desk where you check in."}]},"media":{"uk":"media/uk/check_in_1_gb_1.mp3","us":"media/us/check_in_1_us_1.mp3"},"examples":[{"en":"Do you know your check-in time?","cn":"你知道办理登机手续的时间吗？"},{"en":"( BrE ) the check-in desk","cn":"办理登机手续的服务台"}]},"chequebook":{"oxford":{"phon":"ˈtʃekbʊk","pos":"noun","senses":[{"en":"a book of printed cheques","cn":"支票簿"}]},"media":{"img":["media/pic/money_comp.jpg","media/thumb/chequebook.jpg"],"uk":"media/uk/chequebook__gb_1.mp3","us":"media/us/chequebook__us_1.mp3"}},"charities":{"oxford":{"phon":"ˈtʃærəti","pos":"noun","senses":[{"en":"an organization for helping people in need","cn":"慈善机构（或组织）"},{"en":"the aim of giving money, food, help, etc. to people who are in need","cn":"慈善；赈济；施舍"}]}},"chamois":{"media":{"uk":"media/uk/chamois__gb_1.mp3","us":"media/us/chamois__us_1.mp3"},"oxford":{"phon":"","pos":"noun","senses":[{"en":"an animal like a small deer, that lives in the mountains of Europe and Asia","cn":"（欧亚山区的）岩羚羊","g":"[countable]"},{"en":"a type of soft leather, made from the skin of goats, sheep, etc.; a piece of this, used especially for cleaning windows","cn":"（由山羊、绵羊等的皮制成的）麂皮；（尤指）擦窗用的软皮革；擦拭用的软皮","g":"[uncountable, countable]","lab":"British English also"},{"en":"a type of soft thick cotton cloth, used especially for making shirts","cn":"（尤指制衬衣用的）厚软棉织物","g":"[uncountable]","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(欧洲、西南亚山区的)岩羚羊","en":"Chamois are small animals rather like goats that live in the mountains of Europe and South West Asia."},{"pos":"N-COUNT 可数名词","cn":"(用于清洁、擦拭的)软皮革","en":"A chamois or a chamois leather is a soft leather cloth used for cleaning and polishing."}]}},"chic":{"media":{"uk":"media/uk/chic__gb_1.mp3","us":"media/us/chic__us_1.mp3"},"oxford":{"phon":"ʃiːk","pos":"noun","senses":[{"en":"the quality of being fashionable and attractive","cn":"时髦的；优雅的；雅致的","ex":{"en":"a perfectly dressed woman with an air of chic that was unmistakably French","cn":"一个衣着讲究的女人，明显地流露出法国式的优雅风度"}},{"en":"very fashionable and attractive","cn":"时髦的；迷人的","ex":{"en":"She is always so chic, so elegant.","cn":"她总是那么时髦，那么优雅。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"时髦的;别致的","en":"Something or someone that is chic is fashionable and sophisticated.","ex":{"en":"Her gown was very French and very chic.","cn":"她的礼服颇具法国风情，非常别致。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"时尚;雅致;别致","en":"Chic is used to refer to a particular style or to the quality of being chic.","ex":{"en":"...French designer chic","cn":"法国设计时尚"}}]},"examples":[{"en":"a perfectly dressed woman with an air of chic that was unmistakably French","cn":"一位衣着讲究、明显地流露出法国式优雅姿态的女士"},{"en":"She is always so chic, so elegant.","cn":"她总是那么时髦，那么优雅。"}]},"charitable":{"media":{"uk":"media/uk/charitable__gb_1.mp3","us":"media/us/charitable__us_1.mp3"},"oxford":{"phon":"ˈtʃærətəbl","pos":"adjective","senses":[{"en":"connected with a charity or charities","cn":"慈善团体的；慈善事业的","lab":"British English","ex":{"en":"a charitable institution/foundation/trust","cn":"慈善机构／基金会／基金机构"}},{"en":"helping people who are poor or in need","cn":"慈善的；行善的；布施的","ex":{"en":"His later years were devoted largely to charitable work.","cn":"他晚年主要致力于慈善工作。"}},{"en":"kind in your attitude to other people, especially when you are judging them","cn":"仁爱的；宽厚的；宽容的","ex":{"en":"Let's be charitable and assume she just made a mistake.","cn":"咱们宽容些吧，就当她只是犯了个错误。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(组织或活动)慈善的","en":"A charitable organization or activity helps and supports people who are ill, disabled, or very poor.","ex":{"en":"...charitable work for the handicapped.","cn":"为残疾人做的慈善工作"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"仁慈的;体谅的","en":"Someone who is charitable to people is kind or understanding towards them.","ex":{"en":"They were rather less than charitable towards the referee.","cn":"他们对裁判根本不体谅。"}}]},"examples":[{"en":"Let's be charitable and assume she just made a mistake.","cn":"咱们宽容些吧，就当她只是犯了个错误。"},{"en":"Try to think about him a little more charitably.","cn":"看待他这个人尽量大度一点吧。"}]},"chauffeur":{"media":{"uk":"media/uk/chauffeur__gb_1.mp3","us":"media/us/chauffeur__us_1.mp3"},"oxford":{"phon":"ˈʃəʊfə(r)","pos":"noun","senses":[{"en":"a person whose job is to drive a car, especially for somebody rich or important","cn":"（尤指富人或要人的）司机","ex":{"en":"His chauffeur was waiting in the street outside.","cn":"他的司机正在外面的街道上等着。"}},{"en":"to drive somebody in a car, usually as your job","cn":"为某人开车；当司机","ex":{"en":"He was chauffeured to all his meetings.","cn":"他由司机开车送去参加所有的会议。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(富人或要人的)私人司机","en":"The chauffeur of a rich or important person is the man or woman who is employed to look after their car and drive them around in it."},{"pos":"VERB 动词","cn":"为…当私人司机;给…开车","en":"If you chauffeur someone somewhere, you drive them there in a car, usually as part of your job.","ex":{"en":"It was certainly useful to have her there to chauffeur him around","cn":"有她在那儿还是挺有用的，能开车带他到处跑。"}}]},"examples":[{"en":"He was chauffeured to all his meetings.","cn":"他由司机开车送去参加所有的会议。"},{"en":"a chauffeured limousine","cn":"有专职司机驾驶的豪华轿车"}]},"cheat":{"oxford":{"phon":"tʃiːt","pos":"verb","senses":[{"en":"to trick somebody or make them believe something that is not true","cn":"欺骗；蒙骗","g":"[transitive]","ex":{"en":"She is accused of attempting to cheat the taxman.","cn":"她被指控企图蒙骗税务员。"}},{"en":"to act in a dishonest way in order to gain an advantage, especially in a game, a competition, an exam, etc.","cn":"（尤指在游戏、比赛、考试等中）作弊，舞弊","g":"[intransitive]","lab":"British English","ex":{"en":"He cheats at cards.","cn":"他玩牌爱作弊。"}},{"en":"to have a secret sexual relationship with somebody else","cn":"与他人有秘密性关系；对伴侣不忠","g":"[intransitive]","ex":{"en":"He’s cheating on his wife.","cn":"他欺骗了他的妻子。"}},{"en":"a person who cheats, especially in a game","cn":"（尤指游戏中的）作弊者，骗子","g":"[countable]","lab":"especially in North American English","ex":{"en":"You little cheat!","cn":"你这小滑头！"},"pos":"noun"},{"en":"something that seems unfair or dishonest, for example a way of doing something with less effort than it usually needs","cn":"欺骗手段；欺诈行为","g":"[singular]","ex":{"en":"It's really a cheat, but you can use ready-made pastry if you want.","cn":"虽然这么做是作弊，但如果你愿意的话，可以用现成的油酥面团。"},"pos":"noun"},{"en":"a program you can use to move immediately to the next stage of a computer game without needing to play the game","cn":"（电脑游戏的）秘技，欺骗程序，作弊软件","g":"[countable]","lab":"computing","ex":{"en":"There's a cheat you can use to get to the next level.","cn":"有种秘技，你可以用来到达下一关。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"作弊;舞弊;弄虚作假","en":"When someone cheats, they do not obey a set of rules which they should be obeying, for example in a game or exam.","ex":{"en":"Students may be tempted to cheat in order to get into top schools.","cn":"为了能进入一流学校，学生们会忍不住想作弊。"}},{"pos":"N-COUNT 可数名词","cn":"作弊者;弄虚作假的人","en":"Someone who is a cheat does not obey a set of rules which they should be obeying.","ex":{"en":"Cheats will be disqualified.","cn":"弄虚作假者将被取消资格。"}},{"pos":"VERB 动词","cn":"骗取；骗得","en":"If someone cheats you out of something, they get it from you by behaving dishonestly.","ex":{"en":"The company engaged in a deliberate effort to cheat them out of their pensions","cn":"公司涉嫌蓄意骗取他们的养老金。"}},{"pos":"PHRASE 短语","cn":"九死一生;幸免于难","en":"If you say that someone cheats death, you mean they only just avoid being killed.","ex":{"en":"He cheated death when he was rescued from the roof of his blazing cottage.","cn":"他被人从他那熊熊燃烧的棚屋顶上救了下来，捡了条命。"}},{"pos":"PHRASE 短语","cn":"感觉失望;觉得受委屈","en":"If you feel cheated, you feel that you have been let down or treated unfairly.","ex":{"en":"The storyline is fatally compromised by an ending that leaves you feeling horribly cheated.","cn":"故事结尾让人很失望，这样的结尾严重削弱了故事情节。"}},{"pos":"","cn":"","en":"相关词组：cheat on"}]},"media":{"uk":"media/uk/cheat__gb_1.mp3","us":"media/us/cheat__us_1.mp3"},"examples":[{"en":"It's really a cheat, but you can use ready-made pastry if you want.","cn":"这样做其实是骗人，但如果你愿意的话，可以用现成的油酥面团。"},{"en":"Many people feel cheated by the government's refusal to hold a referendum.","cn":"由于政府拒绝举行公民投票表决，许多人都觉得上当受骗。"}]},"chip":{"oxford":{"phon":"tʃɪp","pos":"noun","senses":[{"en":"a long thin piece of potato fried in oil or fat","cn":"油炸土豆条；炸薯条","g":"[usually plural]","lab":"British English","ex":{"en":"He was eating a burger and chips.","cn":"他当时正在吃汉堡和薯条。"}},{"en":"a thin round slice of potato that is fried until hard then dried and eaten cold. Chips are sold in bags and are made to taste of many different foods.","cn":"油炸土豆片；炸薯片","lab":"both North American English","ex":{"en":"a bag of chips","cn":"一袋薯片"}},{"en":"a small flat hard piece of food, often like a triangle in shape, made from maize","cn":"脆玉米片（通常为三角形）"},{"en":"the place from which a small piece of wood, glass, etc. has broken from an object","cn":"（木头、玻璃等的）缺口，缺损处","ex":{"en":"This mug has a chip in it.","cn":"这缸子有个豁口。"}},{"en":"a small piece of wood, glass, etc. that has broken or been broken off an object","cn":"（木头、玻璃等破损后留下的）碎屑，碎片，碎渣","ex":{"en":"chips of wood","cn":"碎木屑"}},{"en":"a small flat piece of plastic used to represent a particular amount of money in some types of gambling","cn":"（作赌注用的）筹码","ex":{"en":"a poker chip","cn":"扑克牌戏筹码"}},{"en":"an act of hitting or kicking a ball high in the air so that it lands within a short distance","cn":"（高尔夫球）近穴击球，切削击球；（足球）撮球","ex":{"en":"She left herself with a short chip to the green.","cn":"她在果岭上留下了短切杆。"}},{"en":"to damage something by breaking a small piece off it; to become damaged in this way","cn":"打破；弄缺；被损坏","g":"[transitive, intransitive]","ex":{"en":"a badly chipped saucer","cn":"破损厉害的碟子"},"pos":"verb"},{"en":"to cut or break small pieces off something with a tool","cn":"切下，削下，凿下（碎片、屑片）","g":"[transitive]","ex":{"en":"Chip away the damaged area.","cn":"把损坏的部分凿掉。"},"pos":"verb"},{"en":"to hit or kick the ball so that it goes high in the air and then lands within a short distance","cn":"撮高（球）；近穴击（球）","g":"[transitive, intransitive]","pos":"verb"},{"en":"to cut potatoes into long thin pieces in order to fry them in deep oil","cn":"将（土豆）切条油炸","g":"[transitive]","lab":"British English","pos":"verb"},{"en":"to put a microchip under the skin of a dog or other animal so that it can be identified if it is lost or stolen","cn":"（为辨认而在狗或其他动物的皮下）植入微芯片","g":"[transitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"炸薯条","en":"Chips are long, thin pieces of potato fried in oil or fat and eaten hot, usually with a meal.","ex":{"en":"I had fish and chips in a cafe","cn":"我在一家小餐馆吃了炸鱼薯条。"}},{"pos":"N-COUNT 可数名词","cn":"（作为零食的）炸薯片","en":"Chips or potato chips are very thin slices of fried potato that are eaten cold as a snack.","ex":{"en":"...a package of onion-flavored potato chips.","cn":"一包洋葱味薯片"}},{"pos":"N-COUNT 可数名词","cn":"芯片;集成电路片","en":"A silicon chip is a very small piece of silicon with electronic circuits on it which is part of a computer or other piece of machinery."},{"pos":"N-COUNT 可数名词","cn":"碎片;碎屑;碎块","en":"A chip is a small piece of something or a small piece which has been broken off something.","ex":{"en":"It contains real chocolate chips","cn":"里面有货真价实的巧克力碎屑。"}},{"pos":"N-COUNT 可数名词","cn":"(瓷器上的)缺口，豁口;(家具上的)凹坑，瘪儿","en":"A chip in something such as a piece of china or furniture is where a small piece has been broken off it.","ex":{"en":"The washbasin had a small chip.","cn":"脸盆边上有个小豁口。"}},{"pos":"V-ERG 及物/不及物动词","cn":"削掉，凿落(碎片);剥落","en":"If you chip something or if it chips, a small piece is broken off it.","ex":{"en":"The blow chipped the woman's tooth","cn":"那一击把那个女人的一颗牙打掉了一块。"}},{"pos":"N-COUNT 可数名词","cn":"(用于赌钱的)筹码","en":"Chips are plastic counters used in gambling to represent money.","ex":{"en":"He put the pile of chips in the center of the table and drew a card.","cn":"他将一堆筹码堆在桌子中间，抽了一张牌。"}},{"pos":"N-COUNT 可数名词","cn":"(谈判中的)筹码，讨价还价的资本","en":"In discussions between people or governments, a chip or a bargaining chip is something of value which one side holds, which can be exchanged for something they want from the other side.","ex":{"en":"The information could be used as a bargaining chip to extract some parallel information from Britain","cn":"这个情报可以当作筹码，从英国人那里换取等价的消息。"}},{"pos":"PHRASE 短语","cn":"(性格或行为)酷似父亲(或母亲)的人","en":"If you describe someone as a chip off the old block, you mean that they are just like one of their parents in character or behaviour.","ex":{"en":"Her fifth child was born, a son who Sally at first thought was another chip off the old block.","cn":"她的第5个孩子降生了，是个儿子;刚开始，萨莉以为这孩子又是跟他父亲一个模子。"}},{"pos":"PHRASE 短语","cn":"紧急关头;关键时刻","en":"If you say that something happens when the chips are down, you mean it happens when a situation gets very difficult.","ex":{"en":"When the chips are down, she's very tough.","cn":"关键时刻，她总是很坚强。"}},{"pos":"PHRASE 短语","cn":"(自我感觉)低人一等，不忿","en":"If you say that someone has a chip on their shoulder, you think that they feel inferior or that they believe they have been treated unfairly.","ex":{"en":"He had this chip on his shoulder about my mum and dad thinking that they're better than him.","cn":"他在我父母面前一脸晦气，觉得他们看不起他。"}},{"pos":"","cn":"","en":"相关词组：chip away at chip in"}]},"media":{"img":["media/pic/chips_crisps.jpg","media/thumb/chips.jpg","media/pic/broken_comp.jpg"],"uk":"media/uk/chip__gb_1.mp3","us":"media/us/chip__us_1.mp3"},"examples":[{"en":"If everyone chips in we'll be able to buy her a really nice present.","cn":"如果大家都凑钱，我们就能给她买件很好的礼物。"},{"en":"I'm not sure what I'll do when the chips are down.","cn":"我拿不准到了关键时刻我会干出些什么事来。"}]},"changed":{"media":{"uk":"media/uk/changed__gb_1.mp3","us":"media/us/changed__us_1.mp3"},"oxford":{"phon":"tʃeɪndʒd","pos":"adjective","senses":[{"en":"very different from what they were before","cn":"与以前截然不同的；变化大的；已变的","ex":{"en":"She's a changed woman since she got that job.","cn":"她自从得到了那份工作，变得判若两人。"}}]},"examples":[{"en":"This will not be possible in the changed economic climate.","cn":"这在经济气候已经改变的条件下是不可能的。"},{"en":"She's a changed woman since she got that job.","cn":"她自从得到了那份工作，变得判若两人。"}]},"cheerful":{"media":{"uk":"media/uk/cheerful__gb_1.mp3","us":"media/us/cheerful__us_1.mp3"},"oxford":{"phon":"ˈtʃɪəfl","pos":"adjective","senses":[{"en":"happy, and showing it by the way that you behave","cn":"快乐的；高兴的；兴高采烈的","ex":{"en":"You're not your usual cheerful self today.","cn":"你今天不像往常那么快快乐乐的。"}},{"en":"giving you a feeling of happiness","cn":"令人愉快的","ex":{"en":"a bright, cheerful restaurant","cn":"明亮宜人的餐馆"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"欢快的;高兴的;兴高采烈的","en":"Someone who is cheerful is happy and shows this in their behaviour.","ex":{"en":"They are both very cheerful in spite of their colds","cn":"他们俩虽然感冒了，可都兴高采烈的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人愉快的;令人开心的","en":"Something that is cheerful is pleasant and makes you feel happy.","ex":{"en":"The nursery is bright and cheerful, with plenty of toys.","cn":"托儿所明亮宜人，还有许多玩具。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乐观的;开朗的;满不在乎的","en":"If you describe someone's attitude as cheerful, you mean they are not worried about something, and you think that they should be.","ex":{"en":"There is little evidence to support many of Mr Will's cheerful assumptions.","cn":"没有多少证据能支持威尔先生的那些乐观设想。"}}]},"examples":[{"en":"You're not your usual cheerful self today.","cn":"你今天不像往常那么快快乐乐的。"},{"en":"I could cheerfully have killed him when he said that (= I would have liked to).","cn":"他说那话时我真想把他宰了。"}]},"charging":{"oxford":{"phon":"tʃɑːdʒ","pos":"noun","senses":[{"en":"the amount of money that sb asks for goods and services （","cn":"商品和服务所需的）要价，收费"},{"en":"an official claim made by the police that sb has committed a crime","cn":"指控；控告"}]}},"chickens":{"oxford":{"phon":"ˈtʃɪkɪn","pos":"noun","senses":[{"en":"a large bird that is often kept for its eggs or meat","cn":"鸡"},{"en":"meat from a chicken","cn":"鸡肉"}]}},"cheapened":{"oxford":{"phon":"ˈtʃiːpən","pos":"verb","senses":[{"en":"to make sb lose respect for himself or herself","cn":"使丧失威信；使贬低"},{"en":"to make sth lower in price","cn":"降低 … 的价格"}]}},"cheaper":{"oxford":{"phon":"tʃiːp","pos":"adjective","senses":[{"en":"costing little money or less money than you expected","cn":"花钱少的；便宜的；廉价的"},{"en":"charging low prices","cn":"收费低廉的"}]}},"characterizes":{"oxford":{"phon":"ˈkærəktəraɪz","pos":"verb","senses":[{"en":"to be typical of a person, place or thing","cn":"是 … 的特征；以 … 为典型"},{"en":"to give sb/sth its typical or most noticeable qualities or features","cn":"使 … 具有特点（或最引人注目的特征）"}]}},"cheerleaders":{"oxford":{"phon":"ˈtʃɪəliːdə(r)","pos":"noun","senses":[{"en":"(in the US) one of the members of a group of young people (usually women) wearing special uniforms, who encourage the crowd to cheer for their team at a sports event","cn":"拉拉队队员（美国体育比赛时鼓动观众为本队加油，通常为女性）"},{"en":"a person who supports a particular politician, idea, or way of doing sth （","cn":"某一政治家、某种观点或做法等的）支持者，摇旗呐喊者"}]}},"chid":{"oxford":{"phon":"tʃaɪd","pos":"verb","senses":[{"en":"to criticize or blame sb because they have done sth wrong","cn":"批评；指责；责备"}]}},"changing":{"oxford":{"phon":"tʃeɪndʒ","pos":"verb","senses":[{"en":"to become different","cn":"改变；变化"},{"en":"to make sb/sth different","cn":"使不同"}]}},"chairs":{"oxford":{"phon":"tʃeə(r)","pos":"noun","senses":[{"en":"a piece of furniture for one person to sit on, with a back, a seat and four legs","cn":"椅子"},{"en":"the position of being in charge of a meeting or committee; the person who holds this position （","cn":"主持会议或委员会的）主席席位；委员长职位；（会议或委员会的）主席；委员长"}]}},"checks":{"oxford":{"phon":"tʃek","pos":"verb","senses":[{"en":"to examine sth to see if it is correct, safe or acceptable","cn":"检查；审查；核查；检验"},{"en":"to find out if sth/sb is present, correct or true or if sth is how you think it is","cn":"查明；查看；核实；弄确实"}]}},"characterized":{"oxford":{"phon":"ˈkærəktəraɪz","pos":"verb","senses":[{"en":"to be typical of a person, place or thing","cn":"是 … 的特征；以 … 为典型"},{"en":"to give sb/sth its typical or most noticeable qualities or features","cn":"使 … 具有特点（或最引人注目的特征）"}]}},"chocolates":{"oxford":{"phon":"ˈtʃɒklət","pos":"noun","senses":[{"en":"a hard brown sweet food made from cocoa beans , used in cooking to add flavour to cakes, etc. or eaten as a sweet/candy","cn":"巧克力；朱古力"},{"en":"a sweet/candy that is made of or covered with chocolate","cn":"巧克力糖；夹心巧克力糖"}]}},"choosing":{"oxford":{"phon":"tʃuːz","pos":"verb","senses":[{"en":"to decide which thing or person you want out of the ones that are available","cn":"选择；挑选；选取"},{"en":"to prefer or decide to do sth","cn":"宁愿；情愿；决定"}]}},"chanted":{"oxford":{"phon":"tʃɑːnt","pos":"noun","senses":[{"en":"words or phrases that a group of people shout or sing again and again","cn":"反复呼喊的话语；重复唱的歌词"},{"en":"a religious song or prayer or a way of singing, using only a few notes that are repeated many times","cn":"圣歌；反复吟咏的祷文；单调的吟唱"}]}},"chopping":{"oxford":{"phon":"tʃɒp","pos":"verb","senses":[{"en":"to cut sth into pieces with a sharp tool such as a knife","cn":"切碎；剁碎；砍；劈"},{"en":"( informal ) to reduce sth by a large amount; to stop sth （","cn":"大幅度地）削减，降低；取消；终止"}]}},"characteristics":{"oxford":{"phon":"ˌkærəktəˈrɪstɪk","pos":"adjective","senses":[{"en":"very typical of sth or of sb's character","cn":"典型的；独特的；特有的"},{"en":"a typical feature or quality that sth/sb has","cn":"特征；特点；品质"}]}},"cheeks":{"oxford":{"phon":"tʃiːk","pos":"noun","senses":[{"en":"either side of the face below the eyes","cn":"面颊；脸颊"},{"en":"( in adjectives","cn":"构成形容词 ) having the type of cheeks mentioned 有 … 面颊的；面颊 … 的"}]}},"churches":{"oxford":{"phon":"tʃɜːtʃ","pos":"noun","senses":[{"en":"a building where Christians go to worship （","cn":"基督教的）教堂，礼拜堂"},{"en":"a service or services in a church","cn":"礼拜；礼拜仪式"}]}},"chilled":{"oxford":{"phon":"tʃɪl","pos":"noun","senses":[{"en":"a feeling of being cold","cn":"寒冷；寒意；凉意"},{"en":"an illness caused by being cold and wet, causing fever and shivering (= shaking of the body)","cn":"着凉；受寒"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ldoce6chilled.mp3","us":"media/ldoce/hwd/ame/f/ldoce6chilled.mp3"},"examples":[{"en":"a bottle of chilled white wine","cn":"一瓶冰镇白葡萄酒"},{"en":"He’s usually quite chilled.","cn":"他一般都很淡定。"}]},"children":{"oxford":{"phon":"tʃaɪld","pos":"noun","senses":[{"en":"a young human who is not yet an adult","cn":"儿童；小孩"},{"en":"a son or daughter of any age","cn":"儿子；女儿"}]},"collins":{"senses":[{"pos":"","cn":"(child 的复数)","en":"Children is the plural of child ."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld44children.mp3","us":"media/ldoce/hwd/ame/9/ld44children.mp3"}},"choices":{"oxford":{"phon":"tʃɔɪs","pos":"noun","senses":[{"en":"an act of choosing between two or more possibilities; something that you can choose","cn":"选择；挑选；抉择"},{"en":"the right to choose or the possibility of choosing","cn":"选择权；选择的可能性"}]}},"challenges":{"oxford":{"phon":"ˈtʃælɪndʒ","pos":"noun","senses":[{"en":"a new or difficult task that tests sb's ability and skill","cn":"挑战；艰巨任务"},{"en":"an invitation or a suggestion to sb that they should enter a competition, fight, etc.","cn":"挑战书；（比赛、打斗等的）邀请，提议"}]}},"changes":{"oxford":{"phon":"tʃeɪndʒ","pos":"verb","senses":[{"en":"to become different","cn":"改变；变化"},{"en":"to make sb/sth different","cn":"使不同"}]}},"charges":{"oxford":{"phon":"tʃɑːdʒ","pos":"noun","senses":[{"en":"the amount of money that sb asks for goods and services （","cn":"商品和服务所需的）要价，收费"},{"en":"an official claim made by the police that sb has committed a crime","cn":"指控；控告"}]}},"charms":{"oxford":{"phon":"tʃɑːm","pos":"noun","senses":[{"en":"the power of pleasing or attracting people","cn":"魅力；魔力；吸引力"},{"en":"a feature or quality that is pleasing or attractive","cn":"迷人的特征；吸引人的特性；妩媚"}]}},"chimpanzees":{"oxford":{"phon":"ˌtʃɪmpænˈziː","pos":"noun","senses":[{"en":"a small intelligent African ape (= an animal like a large monkey without a tail)","cn":"黑猩猩"}]}},"chains":{"oxford":{"phon":"tʃeɪn","pos":"noun","senses":[{"en":"a series of connected metal rings, used for pulling or fastening things; a length of chain used for a particular purpose","cn":"链子；链条；锁链"},{"en":"a series of connected things or people","cn":"一系列，一连串（人或事）"}]}},"cheeses":{"oxford":{"phon":"tʃiːz","pos":"noun","senses":[{"en":"a type of food made from milk that can be either soft or hard and is usually white or yellow in colour; a particular type of this food","cn":"干酪；奶酪"},{"en":"what you ask sb to say before you take their photograph “","cn":"茄子”（要求照相的人说的口形词）"}]}},"chillier":{"oxford":{"phon":"ˈtʃɪli","pos":"adj.","senses":[{"en":"too cold to be comfortable","cn":"寒冷的；阴冷的"},{"en":"not friendly","cn":"不友好的；冷淡的；冷漠的"}]}},"characters":{"oxford":{"phon":"ˈkærəktə(r)","pos":"noun","senses":[{"en":"all the qualities and features that make a person, groups of people, and places different from others （","cn":"人、集体的）品质，性格；（地方的）特点，特性"},{"en":"the way that sth is, or a particular quality or feature that a thing, an event or a place has （","cn":"事物、事件或地方的）特点，特征，特色"}]}},"chasing":{"oxford":{"phon":"tʃeɪs","pos":"verb","senses":[{"en":"to run, drive, etc. after sb/sth in order to catch them","cn":"追赶；追逐；追捕"},{"en":"to try to obtain or achieve sth, for example money, work or success","cn":"努力获得；争取得到"}]}},"cheek":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脸颊;脸蛋儿","en":"Your cheeks are the sides of your face below your eyes.","ex":{"en":"Tears were running down her cheeks","cn":"眼泪顺着她的脸颊流了下来。"}},{"pos":"N-SING 单数名词","cn":"厚颜无耻；厚脸皮","en":"You say that someone has a cheek when you are annoyed or shocked at something unreasonable that they have done.","ex":{"en":"I'm amazed they had the cheek to ask in the first place","cn":"我真惊讶他们当初竟然有脸问。"}},{"pos":"PHRASE 短语","cn":"忍气吞声;逆来顺受","en":"If you turn the other cheek when someone harms or insults you, you do not harm or insult them in return."},{"pos":"","cn":"","en":"cheek by jowl→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the soft round part of your face below each of your eyes","cn":"面颊﹐脸颊"},{"en":"disrespectful or rude behaviour, especially towards someone in a position of authority 〔","cn":"尤指对权威〕无礼[放肆]的行为﹔厚颜无耻"},{"en":"very close to someone or something else","cn":"紧挨着（某人/某物）"}]},"collocations":{"phrases":["ADJ. flushed, hot | cool | smooth, soft | ashen, pale, pallid, pasty | blushing, pink, rosy, scarlet | sunken His red-rimmed eyes and sunken","VERB + CHEEK brush, dab (at), stroke, touch She dabbed at her cheeks with a handkerchief. | kiss, peck | give (sb), proffer She proffered he","CHEEK + VERB blaze, burn, flame, grow hot, redden He felt his cheeks burning with shame.","PREP. across sb's/the ~ She gave him a sharp slap across his cheek. | against sb's ~ She laid her cheek against his. | down sb's ~ A tear sl","PHRASES bring the colour (back) to your cheeks, the colour floods/rises/rushes to your cheeks The colour flooded to his cheeks when he reali","ADJ. awful, bare-faced, colossal It's an awful cheek, the way he keeps asking you to lend him money. | bleeding (taboo) , bloody (taboo) , d","VERB + CHEEK have He's got a cheek, making you wait outside his office.","PHRASES Of all the cheek!/What (a) cheek! He asked you for money? Of all the cheek!"]},"media":{"uk":"media/ldoce/hwd/bre/0/cheek_n0205.mp3","us":"media/ldoce/hwd/ame/f/cheek.mp3"},"examples":[{"en":"He had the cheek to ask his ex-girlfriend to babysit for them.","cn":"他竟厚着脸皮要他以前的女朋友为他们临时照看小孩。"},{"en":"I think they've got a cheek making you pay to park the car.","cn":"我想不到他们居然有脸要你付停车费。"}],"oxford":{"phon":"tʃiːk","pos":"noun","senses":[{"en":"either side of the face below the eyes","cn":"面颊；脸颊","g":"[countable]","lab":"informal","ex":{"en":"chubby/rosy/pink cheeks","cn":"丰满的／红润的／粉红的脸颊"}},{"en":"having the type of cheeks mentioned","cn":"有…面颊的；面颊…的","ex":{"en":"chubby-cheeked/rosy-cheeked/hollow-cheeked","cn":"双颊丰满／红润／瘦削"}},{"en":"either of the buttocks","cn":"半边屁股","g":"[countable]","lab":"informal"},{"en":"talk or behaviour that people think is annoying, rude or not showing enough respect","cn":"令人讨厌（或粗鲁、无礼）的话（或行为）","g":"[uncountable, singular]","lab":"British English","ex":{"en":"What a cheek!","cn":"真不要脸！"}},{"en":"to speak to somebody in a rude way that shows a lack of respect","cn":"对…粗鲁无礼地说","ex":{"en":"‘Don't cheek your mother, Sam!’","cn":"“萨姆，别对你妈妈无礼!”"},"pos":"verb"}]}},"chute":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滑道;斜道;溜槽","en":"A chute is a steep, narrow slope down which people or things can slide.","ex":{"en":"Passengers escaped from the plane's front four exits by sliding down emergency chutes.","cn":"乘客们从飞机前部4个出口处的紧急滑道滑下逃生了。"}},{"pos":"N-COUNT 可数名词","cn":"降落伞","en":"A chute is a parachute.","ex":{"en":"You can release the chute with either hand, but it is easier to do it with the left.","cn":"你随便哪只手都能打开降落伞，不过用左手容易些。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long narrow structure that slopes down, so that things or people can slide down it from one place to another","cn":"滑道﹔斜槽﹔溜槽"},{"en":"a parachute","cn":"降落伞"}]},"collocations":{"phrases":["ADJ. garbage, laundry, rubbish, water a swimming pool with a long water chute","PREP. down a/the ~ The rubbish goes down the chute into a large bin."]},"media":{"uk":"media/ldoce/hwd/bre/5/chute0205.mp3","us":"media/ldoce/hwd/ame/5/chute.mp3"},"examples":[{"en":"a laundry/rubbish/garbage chute (= from the upper floors of a high building)","cn":"洗衣槽；垃圾道（高层建筑上面各层用的）"},{"en":"a water chute (= at a swimming pool)","cn":"滑水槽"}],"oxford":{"phon":"ʃuːt","pos":"noun","senses":[{"en":"a tube or passage down which people or things can slide","cn":"（人或物可顺势滑下的）斜槽，溜道","ex":{"en":"a water chute (= at a swimming pool)","cn":"滑水槽"}},{"en":"a parachute (= a device that is attached to people or objects to make them fall slowly and safely when they are dropped from an aircraft. It consists of a large piece of thin cloth that opens out in the air.)","cn":"降落伞：降落伞（一种附着在人或物体上的装置，当人或物体从飞机上坠落时，使它们缓慢而安全地掉落。它由一块大的薄布组成，该薄布向空中敞开。）","lab":"informal"}]}},"chapter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(书的)章，回，篇","en":"A chapter is one of the parts that a book is divided into. Each chapter has a number, and sometimes a title.","ex":{"en":"Chromium supplements were used successfully in the treatment of diabetes (see Chapter 4)","cn":"铬补充剂被成功运用于治疗糖尿病(见第4章)。"}},{"pos":"N-COUNT 可数名词","cn":"(人生或历史上的)阶段，时期，篇章","en":"A chapter in someone's life or in history is a period of time during which a major event or series of related events takes place.","ex":{"en":"This had been a particularly difficult chapter in Lebanon's recent history.","cn":"这在黎巴嫩的近代史上是个特别困难的时期。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"大教堂全体教士(或全体相关神职人员)","en":"A chapter is a group of Christian clergy who work in or who are connected with a cathedral.","ex":{"en":"The Archbishop began his address, thanking the Dean and Chapter of Westminster for inviting him to the Abbey.","cn":"大主教在开始演讲之前，首先感谢威斯敏斯特大教堂的主教和全体教士邀请他来到这里。"}},{"pos":"N-COUNT 可数名词","cn":"(社团或俱乐部的)分会，分部","en":"A chapter is a branch of a society or club.","ex":{"en":"To find out more about cancer warning signs call your local chapter of the American Cancer Society.","cn":"想要了解更多有关癌症的征兆，请给美国癌症协会本地分会打电话。"}},{"pos":"PHRASE 短语","cn":"详细内容;具体细节","en":"If you say that someone gives you chapter and verse on a particular subject, you are emphasizing that they tell you every detail about it.","ex":{"en":"In the course of the evening he gave me chapter and verse on the mosses of the Islay peat bogs.","cn":"整个晚上，他向我详细讲述艾莱岛泥炭沼泽地上的各种青苔。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that together with other things forms a whole","cn":""},{"en":"a small part of something","cn":""},{"en":"one of several different parts that you join together to make something","cn":""}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"A chapter is a section of a book. Some long novels might be divided into twenty or thirty chapters ."}]},"collocations":{"phrases":["ADJ. introductory, opening","VERB + CHAPTER read I read the first few chapters and then got bored.","PREP. in a/the ~ His influence on other writers will be discussed in the next chapter. | ~ about/on a chapter on the city's architecture 2 p","ADJ. difficult, sad, unhappy Her return to France ended a particularly unhappy chapter in her life."]},"media":{"uk":"media/ldoce/hwd/bre/e/chapter0205.mp3","us":"media/ldoce/hwd/ame/d/chapter.mp3"},"examples":[{"en":"I can't give chapter and verse, but that's the rough outline of our legal position.","cn":"我无法提供准确细节，但那是我们所处法律地位的大致情况。"},{"en":"Have you read the chapter on the legal system?","cn":"你读过论述法律制度的那一章吗？"}],"oxford":{"phon":"ˈtʃæptə(r)","pos":"noun","senses":[{"en":"a separate section of a book, usually with a number or title","cn":"（书的）章，篇，回","g":"[countable]","ex":{"en":"to read/write a chapter","cn":"读／写一章"}},{"en":"a period of time in a person’s life or in history","cn":"（人生或历史的）时期，时代，篇章","g":"[countable]","ex":{"en":"a difficult chapter in our country’s history","cn":"我们国家历史上的一段困难时期"}},{"en":"all the priests of a cathedral or members of a religious community","cn":"主教座堂全体教士；宗教团体的全体成员","g":"[countable + singular or plural verb]","ex":{"en":"a meeting of the dean and chapter","cn":"座堂主任牧师和全体教士的会议"}},{"en":"a local branch of a society, club, etc.","cn":"（社团、俱乐部等的）地方分会","g":"[countable]","lab":"especially North American English","ex":{"en":"the local chapter of the Rotary club","cn":"扶轮社的地方分会"}}]}},"cholesterol":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"胆固醇","en":"Cholesterol is a substance that exists in the fat, tissues, and blood of all animals. Too much cholesterol in a person's blood can cause heart disease.","ex":{"en":"...a dangerously high cholesterol level.","cn":"高得危险的胆固醇水平"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical substance found in your blood. Too much cholesterol in your body may cause heart disease.","cn":"胆固醇"}]},"vocab":{"pos":"n","senses":[{"en":"Cholesterol is a naturally-occurring steroid found in animal tissues. It's important for healthy cell membranes and other functions, but its waxy makeup makes it a danger as a high concentration could build up and block arteries."}]},"collocations":{"phrases":["ADJ. high, raised | low | blood raised blood cholesterol levels","QUANT. level a high/low level of cholesterol","VERB + CHOLESTEROL have (only used with high or low ) He has high cholesterol. | contain chips containing no cholesterol | reduce Eating gar","CHOLESTEROL + NOUN level","PHRASES be high/low in cholesterol foods that are low in cholesterol"]},"media":{"uk":"media/ldoce/hwd/bre/2/cholesterol0205.mp3","us":"media/ldoce/hwd/ame/4/cholesterol.mp3"},"oxford":{"phon":"kəˈlestərɒl","pos":"noun","senses":[{"en":"a fatty substance found in most tissues of the body. Too much cholesterol in the blood is linked to a higher risk of heart disease.","cn":"胆固醇","lab":"British English","ex":{"en":"a high cholesterol level","cn":"高胆固醇水平"}}]}},"chilly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"阴冷的;寒冷的","en":"Something that is chilly is unpleasantly cold. →see usage note at:","ex":{"en":"It was a chilly afternoon","cn":"那是个阴冷的下午。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷的;有寒意的","en":"If you feel chilly, you feel rather cold.","ex":{"en":"I'm a bit chilly.","cn":"我有点冷。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人际关系、反应)冷淡的，冷冰冰的，不热情的","en":"You say that relations between people are chilly or that a person's response is chilly when they are not friendly, welcoming, or enthusiastic.","ex":{"en":"I was slightly afraid of their chilly distant politeness.","cn":"他们那种冷冰冰的、敬而远之的客套让我有点憷头。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used especially when you feel uncomfortable","cn":""},{"en":"a little cold, often in a way that feels comfortable","cn":""},{"en":"a little cold, but not very cold, in a way that feels rather uncomfortable","cn":""}]},"vocab":{"pos":"1 adj 2 n","senses":[{"en":"Did someone leave a window open? It's chilly in here! That word means \"cold,\" and it can also mean that someone's acting in a frosty way."}]},"collocations":{"phrases":["VERBS be, feel She was beginning to feel chilly. | get We were starting to get a bit chilly. | turn (only used about the weather) It turned ","ADV. decidedly, distinctly, very | a bit, pretty, quite, rather, somewhat"]},"media":{"uk":"media/ldoce/hwd/bre/9/chilly0205.mp3","us":"media/ldoce/hwd/ame/4/chile.mp3"},"examples":[{"en":"I was feeling chilly.","cn":"我感到冷得难受。"},{"en":"The visitors got a chilly reception.","cn":"客人遭到了冷遇。"}],"oxford":{"phon":"ˈtʃɪli","pos":"adjective","senses":[{"en":"too cold to be comfortable","cn":"寒冷的；阴冷的","ex":{"en":"It's chilly today.","cn":"今天很寒冷。"}},{"en":"not friendly","cn":"不友好的；冷淡的；冷漠的","ex":{"en":"The visitors got a chilly reception.","cn":"客人遭到了冷遇。"}}]}},"charade":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"明显的做作;一眼看穿的伪装","en":"If you describe someone's actions as a charade, you mean that their actions are so obviously false that they do not convince anyone.","ex":{"en":"I wondered why he had gone through the elaborate charade","cn":"我不明白，他为什么要大费周章，装腔作势。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"看手势猜字谜游戏","en":"Charades is a game for teams of players in which one team acts a word or phrase, syllable by syllable, until other players guess the whole word or phrase.","ex":{"en":"She and her three brothers played charades.","cn":"她和3个兄弟玩看手势猜字谜。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt to pretend that something is true, especially in order to deceive people","cn":""},{"en":"a situation in which people pretend that something is true and behave as if it were true, especially when everyone really knows that it is not true","cn":""},{"en":"an attempt to deceive people by pretending that something is true, especially if it is easy for people to see that it is not true","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A charade is something done just for show. Your devotion to vegetarianism would be a charade if you actually ate cheeseburgers when no one was looking."}]},"collocations":{"phrases":["ADJ. clever, elaborate | pathetic, ridiculous","VERB + CHARADE continue, go along with, keep up, maintain, take part in I refused to go along with their pathetic charade.","PREP. ~ of She struggled to maintain the charade of not being afraid."]},"media":{"uk":"media/ldoce/hwd/bre/c/charade0205.mp3","us":"media/ldoce/hwd/ame/3/charade.mp3"},"examples":[{"en":"Their whole marriage had been a charade — they had never loved each other.","cn":"他们的整个婚姻都是在做戏，他们从未相爱过。"},{"en":"Let's play charades.","cn":"咱们来玩打哑谜猜字游戏吧。"}],"oxford":{"phon":"ʃəˈrɑːd","pos":"noun","senses":[{"en":"a situation in which people pretend that something is true when it clearly is not","cn":"明显的伪装；做戏；装模作样","g":"[countable]","ex":{"en":"Their whole marriage had been a charade—they had never loved each other.","cn":"他们的整个婚姻都是在做戏，他们从未相爱过。"}},{"en":"a game in which one player acts out the syllables of a word or title and the other players try to guess what it is","cn":"打哑谜猜字游戏","g":"[uncountable]","ex":{"en":"Let's play charades.","cn":"咱们来玩打哑谜猜字游戏吧。"}}]}},"chimney":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"烟囱","en":"A chimney is a pipe through which smoke goes up into the air, usually through the roof of a building.","ex":{"en":"This gas fire doesn't need a chimney.","cn":"这种煤气取暖器不需要烟囱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to smoke a lot, especially too much","cn":""},{"en":"to smoke one cigarette after another, without a break","cn":""},{"en":"a vertical pipe that allows smoke from a fire to pass out of a building up into the air, or the part of this pipe that is above the roof","cn":"烟囱（管）﹐烟道"}]},"vocab":{"pos":"n","senses":[{"en":"A chimney is the long, vertical, tunnel-like opening above a fireplace that provides a safe pathway for smoke — and the occasional Santa. It is also the name of the curvy glass flue in a hurricane lamp."}]},"collocations":{"phrases":["ADJ. high, tall | short | narrow, wide | tapering | smoking The air was black from smoking chimneys. | sooty | factory, industrial","VERB + CHIMNEY clean, sweep","CHIMNEY + VERB belch sth factory chimneys belching smoke over the town | draw This chimney doesn't draw very well.","CHIMNEY + NOUN breast, flue, piece, pot, stack | sweep"]},"media":{"img":["media/ldoce/img/roof.jpg"],"uk":"media/ldoce/hwd/bre/4/chimney0205.mp3","us":"media/ldoce/hwd/ame/a/chimney.mp3"},"examples":[{"en":"He threw a bit of paper onto the fire and it flew up the chimney.","cn":"他把一些纸屑扔进火里，纸飘进了烟道。"},{"en":"the factory chimneys of an industrial landscape","cn":"工厂烟囱林立的工业区景观"}],"oxford":{"phon":"ˈtʃɪmni","pos":"noun","senses":[{"en":"a structure through which smoke or steam is carried up away from a fire, etc. and through the roof of a building; the part of this that is above the roof","cn":"烟囱；烟道；（屋顶上的）烟囱管","ex":{"en":"He threw a bit of paper onto the fire and it flew up the chimney.","cn":"他把一小片纸扔进火里，纸飘进了烟道。"}},{"en":"a narrow opening in an area of rock that a person can climb up","cn":"（岩石间可供攀登的）狭孔，狭缝","lab":"specialist"}]}},"chug":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(车辆)突突地缓慢行驶","en":"When a vehicle chugs somewhere, it goes there slowly, noisily and with difficulty.","ex":{"en":"The train chugs down the track.","cn":"火车沿铁轨缓慢前行。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a car, train etc chugs somewhere, it moves there slowly, with the engine making a repeated low sound 〔","cn":"汽车﹑火车等〕突突地缓慢前进"},{"en":"to drink all of something in a glass or bottle without stopping","cn":"一饮而尽﹐一口喝下"},{"en":"to make slow but steady progress","cn":"缓慢而稳步地进展"}]},"collocations":{"phrases":["ADV. slowly, steadily The train chugged steadily along the West Highland Line.","PREP. along, down, in, out, past, etc. The boat chugged slowly down the river."]},"media":{"uk":"media/ldoce/hwd/bre/6/chug0205.mp3","us":"media/ldoce/hwd/ame/9/chug.mp3"},"examples":[{"en":"The boat chugged down the river.","cn":"小船突突地沿江而下。"},{"en":"The boat chugged out of the harbour.","cn":"小船突突地驶出港口。"}],"oxford":{"phon":"tʃʌɡ","pos":"verb","senses":[{"en":"to move making the sound of an engine running slowly","cn":"（发动机缓慢运转时）发出突突声","g":"[intransitive]","ex":{"en":"The boat chugged down the river.","cn":"小船突突地沿江而下。"}},{"en":"to drink all of something quickly without stopping","cn":"一饮而尽；一口气喝完","g":"[transitive]","lab":"North American English, informal，，"},{"en":"the sound made by a chugging engine","cn":"（发动机的）突突声","pos":"noun"}]}},"checkpoint":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（车辆）检查站，关卡","en":"A checkpoint is a place where traffic is stopped so that it can be checked."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place, especially on a border, where an official person examines vehicles or people 〔","cn":"尤指边境的〕关卡﹐检查站"}]},"collocations":{"phrases":["ADJ. border | army, military | vehicle","VERB + CHECKPOINT set up The army has set up checkpoints on all the major roads in the area.","PREP. at a/the ~ We were stopped at the checkpoint. | through a/the ~ The police waved our car through the border checkpoint."]},"media":{"uk":"media/ldoce/hwd/bre/8/checkpoint0205.mp3","us":"media/ldoce/hwd/ame/3/checkpoint.mp3"},"examples":[{"en":"They had to cross five military checkpoints.","cn":"他们得通过五个军事检查站。"}],"oxford":{"phon":"ˈtʃekpɔɪnt","pos":"noun","senses":[{"en":"a place, especially on a border between two countries, where people have to stop so their vehicles and documents can be checked","cn":"（边防）检查站；边防关卡","ex":{"en":"There are border guards at the checkpoint crossing.","cn":"检查站有边防警卫。"}}]}},"chickenpox":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"水痘","en":"Chickenpox is a disease which gives you a high temperature and red spots that itch."}]},"examples":[{"en":"to catch/get/have chickenpox","cn":"染上/患上/得了水痘"}],"oxford":{"phon":"ˈtʃɪkɪnpɒks","pos":"noun","senses":[{"en":"a disease, especially of children, that causes a high temperature and many spots on the skin","cn":"水痘","ex":{"en":"to catch/get/have chickenpox","cn":"染上／患上／得了水痘"}}]}},"cheekbone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"颧骨;颊骨","en":"Your cheekbones are the two bones in your face just below your eyes.","ex":{"en":"She was very beautiful, with high cheekbones.","cn":"她颧骨高高的，非常漂亮。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two bones above your cheeks, just below your eyes","cn":"颧骨﹐颊骨"}]},"collocations":{"phrases":["ADJ. high, prominent | perfect, sculptured | broken, cracked, fractured","PREP. beneath sb's ~s The hollows beneath his cheekbones showed his stress. | on sb's ~s A flush of anger appeared on her cheekbones. | over"]},"media":{"uk":"media/ldoce/hwd/bre/2/cheekbone0205.mp3","us":"media/ldoce/hwd/ame/2/cheekbone.mp3"},"examples":[{"en":"She had high cheekbones and green eyes.","cn":"她有着高颧骨和一双绿眼睛。"}],"oxford":{"phon":"ˈtʃiːkbəʊn","pos":"noun","senses":[{"en":"the bone below the eye","cn":"颧骨","ex":{"en":"A flush of anger appeared on her cheekbones.","cn":"一股怒气上冲，她顿时双颊飞红。"}}]}},"charter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"章程;宪章","en":"A charter is a formal document describing the rights, aims, or principles of an organization or group of people.","ex":{"en":"...Article 50 of the United Nations Charter.","cn":"《联合国宪章》第50款"}},{"pos":"ADJ 形容词","cn":"(飞机或船只)包租的，包用的","en":"A charter plane or boat is one which is hired for use by a particular person or group and which is not part of a regular service.","ex":{"en":"...the last charter plane carrying out foreign nationals.","cn":"运送外国侨民出境的最后一架包机"}},{"pos":"VERB 动词","cn":"(个人、团体)包租，租用(飞机、船只等)","en":"If a person or organization charters a plane, boat, or other vehicle, they hire it for their own use.","ex":{"en":"He chartered a jet to fly her home from California to Switzerland","cn":"他包了架喷气式飞机把她从加利福尼亚送回瑞士家里。"}},{"pos":"PHRASE 短语","cn":"对…的纵容(或怂恿)","en":"If you describe a decision or policy as a charter for someone or something you disapprove of, you mean that it is likely to help or encourage them.","ex":{"en":"They described the Home Office scheme as a 'charter for cheats'","cn":"他们称内政部的方案是“对诈骗的纵容”。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to let someone do something, or let something happen, especially something bad that you should try to stop. Allow is more formal than let","cn":""},{"en":"to let someone do something that they have chosen to do, although you could stop them, especially because they want to do it very much","cn":""},{"en":"if something bad or unpleasant happens unchecked , it is allowed to continue to happen because no one is controlling it when they should be","cn":""}]},"vocab":{"pos":"1 n v 2 v n","senses":[{"en":"What do rock gods do when they travel? They charter their own plane, of course. Charter means you rent or lease a particular service or object. Anyone can charter something, though lesser mortals tend to limit themselves to buses."}]},"collocations":{"phrases":["ADJ. draft | founding | environmental, social | national, UN/United Nations | citizens', patients', etc.","VERB + CHARTER draw up | sign","CHARTER + VERB set sth out The charter clearly sets out children's rights.","PREP. ~ for a national charter for the protection of animals | ~ of a charter of workers' rights 2 document giving rights to a town/an organ","ADJ. royal","VERB + CHARTER give sb/sth, grant sb/sth, issue | sign | apply for | receive | revoke","PREP. by ~ They were given this right by royal charter."]},"media":{"uk":"media/ldoce/hwd/bre/2/charter_n0205.mp3","us":"media/ldoce/hwd/ame/b/charter1.mp3"},"examples":[{"en":"The Royal College received its charter as a university in 1967.","cn":"皇家学院于 1967 年获得升格为大学的特许状。"},{"en":"The new law will be a charter for unscrupulous financial advisers.","cn":"新的法律会使不诚实的金融顾问有机可乘。"}],"oxford":{"phon":"ˈtʃɑːtə(r)","pos":"noun","senses":[{"en":"a written statement describing the rights that a particular group of people should have","cn":"（说明某部分民众应有权利的）宪章","g":"[countable]","ex":{"en":"the European Social Charter of workers’ rights","cn":"欧洲工人权利社会宪章"}},{"en":"a written statement of the principles and aims of an organization","cn":"（表明某一组织之宗旨和原则的）宪章，章程","g":"[countable]","ex":{"en":"the United Nations Charter","cn":"联合国宪章"}},{"en":"an official document stating that a government or political leader allows a new organization, town or university to be established and gives it particular rights","cn":"（政府或政治领袖批准组织、城镇、大学等成立并享有某些权利的）特许状，许可证，凭照","g":"[countable]","ex":{"en":"The Royal College received its charter as a university in 1967.","cn":"皇家学院于 1967 年获得升格为大学的特许状。"}},{"en":"a law or policy that seems likely to help people do something bad","cn":"（法律或政策的）不完善，漏洞，缺陷","g":"[singular]","lab":"British English","ex":{"en":"The new law will be a charter for unscrupulous financial advisers.","cn":"新的法律会使不诚实的金融顾问有机可乘。"}},{"en":"the hiring of a plane, boat, etc.","cn":"（飞机、船等的）租赁","g":"[uncountable]","ex":{"en":"a yacht available for charter","cn":"可供租赁的游艇"}},{"en":"to hire a plane, boat, etc. for your own use","cn":"包租（飞机、船等）","ex":{"en":"They flew to Athens and then chartered a boat to the island.","cn":"他们飞到雅典，然后包船去岛上。"},"pos":"verb"},{"en":"to state officially that a new organization, town or university has been established and has special rights","cn":"特许设立；给予…特权；发给许可证（或凭照）","g":"[usually passive]","pos":"verb"}]}},"childbirth":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"分娩;生孩子","en":"Childbirth is the act of giving birth to a child.","ex":{"en":"She died in childbirth.","cn":"她生孩子的时候死了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to have a baby - use this especially to talk about the actual process of doing this","cn":""},{"en":"to have a baby for the first time","cn":""},{"en":"the process of giving birth","cn":""}]},"collocations":{"phrases":["ADJ. natural","VERB + CHILDBIRTH die in His wife died in childbirth in 1928.","PHRASES the pain of childbirth She dreaded the pain of childbirth."]},"media":{"uk":"media/ldoce/hwd/bre/e/childbirth0205.mp3","us":"media/ldoce/hwd/ame/7/childbirth.mp3"},"examples":[{"en":"His wife died in childbirth.","cn":"他妻子生孩子的时候死了。"},{"en":"pregnancy and childbirth","cn":"怀孕及分娩"}],"oxford":{"phon":"ˈtʃaɪldbɜːθ","pos":"noun","senses":[{"en":"the process of giving birth to a baby","cn":"分娩；生孩子","ex":{"en":"pregnancy and childbirth","cn":"怀孕及分娩"}}]}},"checkout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(超市的)收款处，收银台","en":"In a supermarket, a checkout is a counter where you pay for things you are buying.","ex":{"en":"...queuing at the checkout in Sainsbury's.","cn":"在塞恩斯伯里超市的收款处前排队"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the place in a supermarket where you pay for the goods you have collected 〔","cn":"超级市场的〕付款处﹐收银台"},{"en":"the time by which you must leave a hotel room 〔","cn":"宾馆的〕退房时间"}]},"collocations":{"phrases":["ADJ. supermarket","VERB + CHECKOUT go through, walk through You can't just go through the checkout without paying!","CHECKOUT + NOUN assistant, girl, operator","PREP. at the ~ He hates waiting at the checkout."]},"media":{"uk":"media/ldoce/hwd/bre/d/c32new3.mp3","us":"media/ldoce/hwd/ame/7/checkout.mp3"},"examples":[{"en":"At checkout, your bill will be printed for you.","cn":"结账时，旅馆会把你的账单打印给你。"},{"en":"a checkout assistant/operator","cn":"付款台助手/收银员"}],"oxford":{"phon":"ˈtʃekaʊt","pos":"noun","senses":[{"en":"the place where you pay for the things that you are buying in a supermarket","cn":"（超市的）付款台，付款处","g":"[countable]","ex":{"en":"a checkout assistant/operator","cn":"收银员"}},{"en":"the time when you leave a hotel at the end of your stay","cn":"结账离开宾馆；办理退房手续","g":"[uncountable]","ex":{"en":"At checkout, your bill will be printed for you.","cn":"退房时，旅馆会把你的账单打印给你。"}},{"en":"part of the process of online shopping in which the customer enters delivery information and pays for the item","cn":"（网购）结算（输入送货信息并付款）","g":"[uncountable]","ex":{"en":"You may choose to pay for your order online using our secure checkout.","cn":"您可以选择使用我们的安全结账在线支付订单。"}}]}},"chilli":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"辣椒","en":"Chillies are small red or green peppers. They have a very hot taste and are used in cooking."},{"pos":"N-UNCOUNT 不可数名词","cn":"同 chilli con carne","en":"Chilli is the same as chilli con carne ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small thin red or green pepper with a very strong hot taste","cn":"辣椒"},{"en":"a spicy dish made with beans, meat, and chillies","cn":"辣味牛肉豆〔一种用豆子﹑肉和辣椒做成的菜肴〕"}]},"collocations":{"phrases":["ADJ. fresh | dried | hot | green, red","CHILLI + NOUN pepper | oil, powder, sauce | beans •"]},"media":{"img":["media/ldoce/img/chili_pepper.jpg","media/thumb/chilli.jpg"],"uk":"media/ldoce/hwd/bre/f/chili0205.mp3","us":"media/ldoce/hwd/ame/5/laadchili.mp3"},"oxford":{"phon":"ˈtʃɪli","pos":"noun","senses":[{"en":"the small green or red fruit of a type of pepper plant that is used in cooking to give a hot taste to food, often dried or made into powder, also called chilli or chilli powder","cn":"辣椒（辣椒粉亦称 chilli 或 chilli powder）","g":"[countable, uncountable]"},{"en":"a hot spicy Mexican dish made with beans, chillies and often meat","cn":"辣豆酱（墨西哥菜肴）","g":"[uncountable]"}]}},"chicago":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the third largest city in the US. It is in the state of Illinois, on the southwest shore of Lake Michigan, and is an important industrial and business centre. During the 1920s and 1930s, Chicago was famous for its gangster s (= professional violent criminals w","cn":""},{"en":"a musical that was first performed in a theatre in 1975 and which is based on the play Chicago by Maurine Dallas Watkins. The story is about two women who have both committed murder and who both want to be famous in Chicago in the 1920s.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/p028-000003243.mp3","us":"media/ldoce/hwd/ame/3/p028-000003243.mp3"},"oxford":{"phon":"ʃɪˈkɑːɡəʊ","pos":"","senses":[{"en":"the third largest US city. It is in the state of Illinois on Lake Michigan and is sometimes called the 'Windy City'. It had the world's first skyscrapers. Chicago is the centre of the American Middle West and its O'Hare airport is one of the busiest airports in the world. The El train runs around the business district, called the Loop. During Prohibition, Chicago was known for its gangsters (= criminals), especially Al Capone.","cn":"芝加哥（美国第三大城市，位于伊利诺伊州密歇根湖畔，别号“风城”）"}]}},"chemist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(兼卖化妆品和某些日用品的)药店","en":"A chemist or a chemist's is a shop where drugs and medicines are sold or given out, and where you can buy cosmetics and some household goods.","ex":{"en":"There are many creams available from the chemist which should clear the infection","cn":"很多能够消除这种感染的药膏在药店就能买到。"}},{"pos":"N-COUNT 可数名词","cn":"药剂师","en":"A chemist is someone who works in a chemist's shop and is qualified to prepare and sell medicines."},{"pos":"N-COUNT 可数名词","cn":"化学家","en":"A chemist is a person who does research connected with chemistry or who studies chemistry.","ex":{"en":"She worked as a research chemist.","cn":"她曾经是化学研究员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large shop that sells a wide range of things, especially food, cleaning materials, and other things that people buy regularly","cn":""},{"en":"a shop in your local area that sells food, alcohol, magazines etc and is often open 24 hours a day","cn":""},{"en":"a small local shop, usually on the corner of a street, that sells food, newspapers, cigarettes etc","cn":""}]},"collocations":{"phrases":["ADJ. local | dispensing","PHRASES chemist's (shop), the chemist's I've just got to go to the chemist's. 2 specialist in chemistry","ADJ. distinguished, leading | government, industrial | analytical, research | inorganic, organic • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/7/chemist0205.mp3","us":"media/ldoce/hwd/ame/5/chemist.mp3"},"examples":[{"en":"You can obtain the product from all good chemists.","cn":"你可从各大药房买到这种产品。"},{"en":"Take this prescription to the chemist's.","cn":"带着这张药方到药房去。"}],"oxford":{"phon":"ˈkemɪst","pos":"noun","senses":[{"en":"a person whose job is to prepare and sell medicines, and who works in a shop","cn":"药剂师；药商","lab":"both British English"},{"en":"a shop that sells medicines and usually also soap, make-up, etc.","cn":"药房，药店（通常也出售肥皂、化妆品等）","lab":"British English","ex":{"en":"You can obtain the product from all good chemists.","cn":"你可从各大药房买到这种产品。"}},{"en":"a scientist who studies chemistry","cn":"化学家","ex":{"en":"a research chemist","cn":"从事研究工作的化学家"}}]}},"chaos":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"混乱;乱糟糟","en":"Chaos is a state of complete disorder and confusion.","ex":{"en":"The world's first transatlantic balloon race ended in chaos last night","cn":"昨晚世界第一届跨大西洋热气球比赛在一片混乱中收场。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which everything or everyone seems to be extremely disorganized or completely out of control","cn":""},{"en":"a situation in which things are disorganized or untidy, or people are disorganized and out of control","cn":""},{"en":"a situation in which no one is sure what is happening and there is a lot of noise and activity","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Chaos is a state of extreme confusion and disorder. Putting a dozen dogs and a dozen cats in the same room would probably lead to utter chaos ."}]},"collocations":{"phrases":["ADJ. absolute, complete, total, utter | general | administrative, domestic, economic, financial, political, social, traffic","VERB + CHAOS bring, cause, create, lead to A serious road accident caused traffic chaos yesterday. | end in, result in The game ended in cha","CHAOS + VERB break out, ensue Chaos broke out when the fire started. I lost my bag in the ensuing chaos. | reign, rule The government collap","PREP. in ~ The airport was in chaos during the strike.","PHRASES on/to the brink of chaos The country was brought to the brink of chaos. | order out of chaos His brave leadership has created order "]},"media":{"uk":"media/ldoce/hwd/bre/2/chaos0205.mp3","us":"media/ldoce/hwd/ame/7/chaos.mp3"},"examples":[{"en":"Heavy snow has caused total chaos on the roads.","cn":"大雪导致道路上交通一片混乱。"},{"en":"The house was in chaos after the party.","cn":"聚会后，房子里一片狼藉。"}],"oxford":{"phon":"ˈkeɪɒs","pos":"noun","senses":[{"en":"a complete lack of order","cn":"混乱；杂乱；紊乱","ex":{"en":"economic/political/domestic chaos","cn":"经济／政治／国内的混乱"}}]}},"choke":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)噎住;(使)哽住;(使)卡住","en":"When you choke or when something chokes you, you cannot breathe properly or get enough air into your lungs.","ex":{"en":"The coffee was almost too hot to swallow and made him choke for a moment","cn":"咖啡烫得几乎咽不下去，呛得他好一会儿喘不过气来。"}},{"pos":"VERB 动词","cn":"掐死;扼死;勒死","en":"To choke someone means to squeeze their neck until they are dead.","ex":{"en":"The men pushed him into the entrance of a nearby building where they choked him with his tie.","cn":"那些人把他推进附近大楼的入口处，用他的领带勒死了他。"}},{"pos":"VERB 动词","cn":"挤满;塞满","en":"If a place is choked with things or people, it is full of them and they prevent movement in it.","ex":{"en":"The village's roads are choked with traffic","cn":"村里的路上挤满了车辆行人。"}},{"pos":"N-COUNT 可数名词","cn":"(汽车、卡车等的)阻气门","en":"The choke in a car, truck, or other vehicle is a device that reduces the amount of air going into the engine and makes it easier to start."},{"pos":"","cn":"","en":"相关词组：choke back choke off"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be unable to breathe because your throat is blocked or because there is not enough air","cn":""},{"en":"to die because you are unable to breathe because you cannot get any air","cn":""},{"en":"if a person or smoke, gas etc chokes someone, they make it very difficult or impossible for them to breathe","cn":""}]},"collocations":{"phrases":["ADV. almost, nearly","VERB + CHOKE threaten to The panic rising in his throat threatened to choke him. | make sb The fumes from the burning tyres made her choke.","PREP. on My son nearly choked on one of those sweets.","PHRASES choke (sb) to death He choked to death when a fish bone got stuck in his throat."]},"media":{"uk":"media/ldoce/hwd/bre/c/choke_v0205.mp3","us":"media/ldoce/hwd/ame/7/choke1.mp3"},"examples":[{"en":"‘I can't bear it,’ he said in a choked voice. “","cn":"我实在忍不下去了。”他声音哽咽地说道。"},{"en":"She choked up when she began to talk about her mother.","cn":"她开始谈起母亲时，便哽咽着说不出话来。"}],"oxford":{"phon":"tʃəʊk","pos":"verb","senses":[{"en":"to be unable to breathe because the passage to your lungs is blocked or you cannot get enough air; to make somebody unable to breathe","cn":"（使）窒息，哽噎","g":"[intransitive, transitive]","ex":{"en":"She almost choked to death in the thick fumes.","cn":"她几乎被浓烟呛死。"}},{"en":"to make somebody stop breathing by pressing their throat, especially with your fingers","cn":"（掐住喉咙）使停止呼吸，使窒息","g":"[transitive]","ex":{"en":"He may have been choked or poisoned.","cn":"他可能是被掐死或毒死的。"}},{"en":"to be unable to speak normally especially because of strong emotion; to make somebody feel too emotional to speak normally","cn":"（尤指感情激动而）说不出话来；使哽咽","g":"[intransitive, transitive]","ex":{"en":"His voice was choking with rage.","cn":"他气得声音哽咽。"}},{"en":"to block or fill a passage, space, etc. so that movement is difficult","cn":"阻塞，塞满，堵塞（通道、空间等）","g":"[transitive, usually passive]","ex":{"en":"The pond was choked with rotten leaves.","cn":"池塘被腐烂的叶子塞满了。"}},{"en":"to fail at something, for example because you are nervous","cn":"（因紧张等而）失败，失灵，失去作用","g":"[intransitive]","lab":"informal","ex":{"en":"We were the only team not to choke at the big moment.","cn":"只有我们队没有在关键时刻发挥失常。"}},{"en":"a device that controls the amount of air flowing into the engine of a vehicle","cn":"（车辆发动机的）进气门","ex":{"en":"an automatic choke","cn":"自动阻风门"},"pos":"noun"},{"en":"an act or the sound of choking","cn":"窒息；哽噎；哽噎声；呛住的声音","ex":{"en":"She gave a little choke of laughter.","cn":"她轻声地扑哧一笑。"},"pos":"noun"}]}},"chasm":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"石罅;地缝;冰缝","en":"A chasm is a very deep crack in rock, earth, or ice."},{"pos":"N-COUNT 可数名词","cn":"(事物或团体间的)显著差距，巨大分歧","en":"If you say that there is a chasm between two things or between two groups of people, you mean that there is a very large difference between them.","ex":{"en":"...the chasm that divides the worlds of university and industry.","cn":"将大学和企业两个世界分隔开的鸿沟"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a big hole in the surface of something, especially the ground, that is caused by an explosion or a large falling object","cn":""},{"en":"a hole in the surface of a road that makes driving difficult or dangerous","cn":""},{"en":"a large wide hole in the ground, especially one that is used for a particular purpose such as burying things","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A chasm is a deep divide, either literal or figurative, such as a giant chasm in an ice cap or the growing chasm between two friends who haven't spoken in a long time."}]},"collocations":{"phrases":["ADJ. deep, gaping, great, huge, yawning","CHASM + VERB open (up) Suddenly a huge chasm opened in the earth. 2 great difference of feelings/interests","ADJ. great, huge, unbridgeable, wide, yawning","VERB + CHASM bridge","CHASM + VERB separate sth A chasm separates my generation from my parents'.","PREP. ~ between an attempt to bridge the unbridgeable chasm between the two cultures | ~ of a huge chasm of hate and prejudice"]},"media":{"uk":"media/ldoce/hwd/bre/c/chasm0205.mp3","us":"media/ldoce/hwd/ame/9/chasm.mp3"},"examples":[{"en":"a rope bridge across the chasm","cn":"峡谷上的索桥"},{"en":"the chasm between rich and poor","cn":"贫富悬殊"}],"oxford":{"phon":"ˈkæzəm","pos":"noun","senses":[{"en":"a deep opening or break in the ground","cn":"（地上的）深裂口，裂隙，深坑","g":"[countable]","lab":"literary","ex":{"en":"Suddenly a huge chasm opened in the earth.","cn":"大地突然裂开，露出一个大窟窿。"}},{"en":"a very big difference between two people or groups, for example because they have different attitudes","cn":"（两个人或团体之间的）巨大分歧，显著差别","g":"[singular]","lab":"formal","ex":{"en":"the yawning chasm of the generation gap","cn":"代沟的巨大鸿沟"}}]}},"checklist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"清单;检查单","en":"A checklist is a list of all the things that you need to do, information that you want to find out, or things that you need to take somewhere, which you make in order to ensure that you do not forget anything.","ex":{"en":"Make a checklist of the tools and materials you will need.","cn":"把你需要的工具和材料开一张单子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of names, places, jobs you need to do etc, which are written one below the other","cn":""},{"en":"a list of things you need or things you have to do which you keep in order to help you remember them","cn":""},{"en":"a list of the most suitable people for a job or prize, chosen from a larger group of people","cn":""}]},"collocations":{"phrases":["ADJ. useful | mental","VERB + CHECKLIST have | use | draw up, produce My boss is drawing up a checklist of my duties. | go through, run through We ran through the ","PREP. ~ for a useful checklist for assessing different schools | ~ of a checklist of questions"]},"media":{"uk":"media/ldoce/hwd/bre/e/checklist0205.mp3","us":"media/ldoce/hwd/ame/7/checklist.mp3"},"examples":[{"en":"The guide contains a useful checklist of points to look for when buying a car.","cn":"手册里有一张很有用的清单﹐列出买车时要注意的一些事项。"}],"oxford":{"phon":"ˈtʃeklɪst","pos":"noun","senses":[{"en":"a list of the things that you must remember to do, to take with you or to find out","cn":"（记事）清单，一览表","ex":{"en":"The following is a checklist of points to look for when choosing a coursebook.","cn":"以下是选择教材时需要注意的要点清单。"}}]}},"chauvinism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"沙文主义;本国至上主义","en":"Chauvinism is a strong, unreasonable belief that your own country is more important and morally better than other people's.","ex":{"en":"It may also appeal to the latent chauvinism of many ordinary people.","cn":"它可能也迎合了许多普通人心中的沙文主义情结。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a belief that your own sex is better or more important than the other sex, especially if you are a man","cn":"本性别至上主义﹔〔尤指〕大男子主义"},{"en":"a strong belief that your country or race is better or more important than any other","cn":"沙文主义﹐本国[本民族]至上主义"}]},"vocab":{"pos":"n","senses":[{"en":"Chauvinism means the belief that your country is superior to all others. If you traveled to China and complained about everything that was unfamiliar and talked about how much better things are back home, you'd be guilty of chauvinism ."}]},"collocations":{"phrases":["ADJ. male | national | British, Russian, etc."]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41chauvinism.mp3","us":"media/ldoce/hwd/ame/1/chauvinism.mp3"},"examples":[{"en":"male chauvinism","cn":"大男子主义"},{"en":"national chauvinism","cn":"民族沙文主义"}],"oxford":{"phon":"ˈʃəʊvɪnɪzəm","pos":"noun","senses":[{"en":"an aggressive and unreasonable belief that your own country is better than all others","cn":"沙文主义","ex":{"en":"It was a typical case of British chauvinism and insularity.","cn":"这是英国沙文主义和狭隘主义的典型案例。"}},{"en":"the belief held by some men that men are more important, more intelligent or better than women","cn":"大男子主义"}]}},"championship":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"锦标赛;冠军赛","en":"A championship is a competition to find the best player or team in a particular sport.","ex":{"en":"...the world chess championship.","cn":"国际象棋世界冠军赛"}},{"pos":"N-SING 单数名词","cn":"冠军头衔;冠军称号;第一名","en":"The championship refers to the title or status of being a sports champion.","ex":{"en":"He went on to take the championship","cn":"他继而夺取冠军宝座。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an organized event in which people try to do an activity or sport better than other people, especially in order to win a prize","cn":""},{"en":"an important sports event in which players or teams play against each other to decide who is the best in an area, the country, or the world","cn":""},{"en":"a competition in a sport or game in which each player or team plays a series of games until one person or team wins","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A championship is a contest where a champion — an ultimate winner — is decided."}]},"collocations":{"phrases":["ADJ. major | international, national, world | British, European, etc. | swimming, tennis, etc.","VERB + CHAMPIONSHIP hold The championships are to be held in Rome. | compete in, take part in Over thirty children will compete in the swimm","CHAMPIONSHIP + VERB take place","CHAMPIONSHIP + NOUN final, game, match, race | title, winner","PREP. at a/the ~ I saw him play at last year's tennis championship. | in a/the ~ the teams in the championship 2 position/title of champion","VERB + CHAMPIONSHIP hold Who holds the championship at the moment? | take, win He's won the championship for the third time in a row. | lose"]},"media":{"uk":"media/ldoce/hwd/bre/1/championship0205.mp3","us":"media/ldoce/hwd/ame/8/championship.mp3"},"examples":[{"en":"They've held the championship for the past two years.","cn":"他们在过去的两年里一直保持着冠军地位。"},{"en":"He won a silver medal at the European Championships.","cn":"他获得了欧洲锦标赛的银牌。"}],"oxford":{"phon":"ˈtʃæmpiənʃɪp","pos":"noun","senses":[{"en":"a competition to find the best player or team in a particular sport","cn":"锦标赛","g":"[plural]","ex":{"en":"the National Basketball Association Championship","cn":"NBA 总决赛"}},{"en":"the position of being a champion","cn":"冠军地位","ex":{"en":"They've held the championship for the past two years.","cn":"他们在过去的两年里一直保持着冠军地位。"}},{"en":"the football (soccer) league in England and Wales that has the second best teams in it, after the Premier League","cn":"（英格兰和威尔士的）足球冠军联赛（仅次于足球超级联赛）"}]}},"chronological":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"按时间顺序的;按先后次序的","en":"If things are described or shown in chronological order, they are described or shown in the order in which they happened.","ex":{"en":"I have arranged these stories in chronological order.","cn":"我把这些报道按时间顺序整理好了。"}},{"pos":"ADJ 形容词","cn":"(年龄)自然的，实龄的(与心理年龄或身心发展程度相对)","en":"If you refer to someone's chronological age, you are referring to the number of years they have lived, in contrast to their mental age or the stage they have reached in their physical or emotional development."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"arranged according to when things happened or were made","cn":"按时间先后顺序排列的"},{"en":"a person’s chronological age is how old they actually are, rather than how old their mind or body seems","cn":"时序年龄，实际年龄"}]},"vocab":{"pos":"adj","senses":[{"en":"If you’re making a list of all your teachers in the order you had them, from kindergarten right up to the present, you’re listing them in chronological order. Chronological is the order in which things actually happened."}]},"collocations":{"phrases":["VERBS be","ADV. strictly a strictly chronological account of the events | broadly The anthology is broadly chronological."]},"media":{"uk":"media/ldoce/hwd/bre/b/chronological0205.mp3","us":"media/ldoce/hwd/ame/2/l3chronological.mp3"},"examples":[{"en":"The facts should be presented in chronological order.","cn":"这些事实应按时间先后顺序陈述。"},{"en":"We arranged the documents in chronological order .","cn":"我们把这些文件按时序排列。"}],"oxford":{"phon":"ˌkrɒnəˈlɒdʒɪkl","pos":"adjective","senses":[{"en":"arranged in the order in which they happened","cn":"按发生时间顺序排列的","ex":{"en":"The facts should be presented in chronological order.","cn":"这些事实应按时间先后顺序陈述。"}}]}},"chop":{"collins":{"senses":[{"pos":"VERB 动词","cn":"砍;剁;劈;切","en":"If you chop something, you cut it into pieces with strong downward movements of a knife or an axe.","ex":{"en":"Chop the butter into small pieces","cn":"把黄油切成小片。"}},{"pos":"N-COUNT 可数名词","cn":"(羊或猪的)排骨","en":"A chop is a small piece of meat cut from the ribs of a sheep or pig.","ex":{"en":"...grilled lamb chops.","cn":"烤羊排"}},{"pos":"PHRASE 短语","cn":"反复无常;不断变卦","en":"When people chop and change, they keep changing their minds about what to do or how to act.","ex":{"en":"Don't ask me why they have chopped and changed so much.","cn":"别问我为什么他们一会儿一个主意。"}},{"pos":"PHRASE 短语","cn":"将被取消(或关闭);(人)将被解雇","en":"If something is for the chop or is going to get the chop, it is going to be stopped or closed. If someone is for the chop, they are going to lose their job or position.","ex":{"en":"He won't say which programmes are for the chop","cn":"他不愿说哪些项目将被毙掉。"}},{"pos":"","cn":"","en":"相关词组：chop down chop off chop up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to divide something into two or more pieces, especially using a knife or scissors","cn":""},{"en":"to quickly cut something, especially using scissors","cn":""},{"en":"to make a long narrow cut through something, especially using a knife","cn":""}]},"collocations":{"phrases":["ADV. finely Add finely chopped parsley. | roughly Roughly chop the cabbage. | up I spent the day chopping up wood. | down There are concerns","PREP. into Chop the meat into small cubes.","PHRASES chop sth to pieces The furniture had been chopped to pieces."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdechop.mp3","us":"media/ldoce/hwd/ame/a/chop1.mp3","img":["media/thumb/chop.jpg"]},"examples":[{"en":"The share price was chopped from 50 pence to 20 pence.","cn":"股价由每股 50 便士猛降至 20 便士。"},{"en":"( figurative ) The country was chopped up into small administrative areas.","cn":"这个国家被划分为若干小的行政区。"}],"oxford":{"phon":"tʃɒp","pos":"verb","senses":[{"en":"to cut something into pieces with a sharp tool such as a knife","cn":"切碎；剁碎；砍；劈","lab":"figurative","ex":{"en":"He was chopping logs for firewood.","cn":"他在把原木劈成柴火。"}},{"en":"to suddenly stop providing or allowing something; to suddenly reduce something by a large amount","cn":"（忽然）取消，终止；（突然大幅度地）削减，降低","g":"[usually passive]","lab":"informal","ex":{"en":"Their training courses are to be chopped.","cn":"他们的培训课程将被取消。"}},{"en":"to hit somebody/something downwards with a quick, short movement","cn":"向下猛烈击打","ex":{"en":"Guzman tried to chop the ball on the ground and use his speed.","cn":"古兹曼试图利用自己的速度将球劈在地上。"}},{"en":"a thick slice of meat with a bone attached to it, especially from a pig or sheep","cn":"猪（或羊等）排","g":"[countable]","ex":{"en":"a pork/lamb chop","cn":"猪排；羊排"},"pos":"noun"},{"en":"an act of cutting something in a quick movement downwards using an axe or a knife","cn":"砍；劈；剁","g":"[countable, usually singular]","ex":{"en":"Give the mushrooms a quick chop before adding them to the pan.","cn":"将蘑菇放入锅中之前先将其快速切碎。"},"pos":"noun"},{"en":"an act of hitting somebody/something with the side of your hand in a quick movement downwards","cn":"掌劈","g":"[countable]","ex":{"en":"a karate chop","cn":"空手道中的掌劈"},"pos":"noun"},{"en":"the part of a person’s or an animal’s face around the mouth","cn":"（人或动物的）嘴周围的地方","g":"[plural]","lab":"informal","ex":{"en":"The dog sat licking its chops.","cn":"那只狗坐着在舔嘴。"},"pos":"noun"},{"en":"the technical skill of an actor or a jazz or rock musician","cn":"（演员、爵士乐手或摇滚乐手的）技艺","g":"[plural]","ex":{"en":"He has the acting chops to carry a major film.","cn":"他的演技足以撑起一部大片。"},"pos":"noun"}]}},"chap":{"collins":{"senses":[{"pos":"","cn":"男人;男孩","en":"A chap is a man or boy.","ex":{"en":"She thought he was a very nice chap.","cn":"她觉得他是个大好人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man, especially a man you know and like 〔","cn":"尤指你认识和喜欢的〕小伙子﹐家伙"},{"en":"protective leather covers worn over your trousers when riding a horse 〔","cn":"骑马时穿的〕皮套裤"},{"en":"chapped lips or hands are sore, dry, and cracked, especially as a result of cold weather or wind","cn":""}]},"collocations":{"phrases":["ADJ. clever, decent, good, jolly, lucky, nice, pleasant He was a pleasant chap but didn't talk much. | good-looking, handsome | young | old ","PHRASES not (such) a bad chap He's not such a bad chap really. | sort of chap He's a decent sort of chap."]},"media":{"uk":"media/ldoce/hwd/bre/9/chap0205.mp3","us":"media/ldoce/hwd/ame/f/chap.mp3"},"examples":[{"en":"He isn't such a bad chap really.","cn":"他这个家伙并不真的这么坏。"},{"en":"a decent sort of chap","cn":"一个正派的小伙子"}],"oxford":{"phon":"tʃæp","pos":"noun","senses":[{"en":"used to talk about a man in a friendly way","cn":"（对男子的友好称呼）家伙，伙计","ex":{"en":"He isn't such a bad chap really.","cn":"他这个家伙并不真的这么坏。"}},{"en":"to become rough, dry and painful, especially because of wind or cold weather","cn":"皲裂","ex":{"en":"His skin is very dry and chaps easily.","cn":"他的皮肤很干，很容易皲裂。"},"pos":"verb"},{"en":"(in writing) chapter","cn":"（书写形式）章，篇，回","pos":"abbreviation"}]}},"chore":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"杂务;琐事","en":"A chore is a task that you must do but that you find unpleasant or boring.","ex":{"en":"She sees exercise primarily as an unavoidable chore","cn":"她基本上把锻炼看做是不得不做的琐事。"}},{"pos":"N-COUNT 可数名词","cn":"家务活;家庭琐事","en":"Chores are tasks such as cleaning, washing, and ironing that have to be done regularly at home.","ex":{"en":"My husband and I both go out to work so we share the household chores.","cn":"我和丈夫都出去工作，所以我们家务活分摊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a specific piece of work that you have to do, often one that you are not paid for","cn":""},{"en":"a piece of work that you have to do - use this especially about a difficult or unpleasant job, or about a specific part of your work","cn":""},{"en":"a job that you have to do, either for your work or for yourself, especially things that you have to leave your office or house to do","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A chore is a duty or task you’re obligated to perform, often one that is unpleasant but necessary. Washing the dishes is a chore , and so is completing a homework assignment you aren’t excited about."}]},"collocations":{"phrases":["ADJ. little, small | daily, day-to-day, routine | administrative, domestic, household","VERB + CHORE carry out, do It'll take me an hour to do the household chores."]},"media":{"uk":"media/ldoce/hwd/bre/c/chore0205.mp3","us":"media/ldoce/hwd/ame/a/chore.mp3"},"examples":[{"en":"Shopping's a real chore for me.","cn":"对我来说，购物真是件苦差事。"},{"en":"doing the household/domestic chores","cn":"干家务杂活"}],"oxford":{"phon":"tʃɔː(r)","pos":"noun","senses":[{"en":"a task that you do regularly","cn":"日常事务；例行工作","ex":{"en":"doing the household/domestic chores","cn":"干家务杂活"}},{"en":"an unpleasant or boring task","cn":"令人厌烦的任务；乏味无聊的工作","g":"[usually singular]","ex":{"en":"Shopping's a real chore for me.","cn":"对我来说，购物真是件苦差事。"}}]}},"chant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"不断重复的话","en":"A chant is a word or group of words that is repeated over and over again.","ex":{"en":"He was greeted by the chant of 'Judas! Judas!'.","cn":"人们看见他就反复不停地喊：“犹大！犹大！”"}},{"pos":"N-COUNT 可数名词","cn":"(反复吟诵的)圣歌，祷文","en":"A chant is a religious song or prayer that is sung on only a few notes.","ex":{"en":"...a Gregorian chant.","cn":"格列高利圣歌"}},{"pos":"VERB 动词","cn":"反复呼喊;不停地重复","en":"If you chant something or if you chant, you repeat the same words over and over again.","ex":{"en":"Demonstrators chanted slogans","cn":"示威者们反复喊着口号。"}},{"pos":"VERB 动词","cn":"吟诵(经文);念(经)","en":"If you chant or if you chant something, you sing a religious song or prayer.","ex":{"en":"Muslims chanted and prayed","cn":"穆斯林们诵经、祈祷。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to repeat a word or phrase again and again 〔","cn":"有节奏地反复〕唱﹐喊叫"},{"en":"to sing or say a religious song or prayer in a way that involves using only one note or tone","cn":"吟唱〔圣歌〕﹔吟诵〔赞美诗〕"},{"en":"words or phrases that are repeated again and again by a group of people","cn":"反复呼喊的话语"}]},"vocab":{"pos":"n v","senses":[{"en":"A chant is a type of song with a repetitive, monotonous structure. It’s also something sports fans love to do. At the Olympics, some Americans chant , “USA! USA! USA!”"}]},"collocations":{"phrases":["ADJ. incessant | melodious | ritual, traditional | Gregorian a group of monks singing Gregorian chant | football You could hear the football","VERB + CHANT sing | keep up The crowd kept up an incessant chant of &lsquo;Out! Out! Out!&rsquo; | hear","PREP. amid ~s, to ~s The band left the stage to chants of &lsquo;We want more! We want more!&rsquo; | ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/6/chant_v0205.mp3","us":"media/ldoce/hwd/ame/f/chant1.mp3"},"examples":[{"en":"A group of protesters, chanting and carrying placards, waited outside.","cn":"一群抗议者等候在外面，举着标语牌不停地喊着口号。"},{"en":"The crowd broke into chants of ‘Out! Out!’","cn":"人群爆发出一阵阵“下台！下台！”的呼喊声。"}],"oxford":{"phon":"tʃɑːnt","pos":"noun","senses":[{"en":"words or phrases that a group of people shout or sing again and again","cn":"反复呼喊的话语；重复唱的歌词","g":"[countable]","ex":{"en":"The crowd broke into chants of ‘Out! Out!’","cn":"人群爆发出一阵阵“下台！下台！”的呼喊声。"}},{"en":"a religious song or prayer or a way of singing, using only a few notes that are repeated many times","cn":"（音调简单重复的）圣歌，祷文，吟唱","g":"[countable, uncountable]","ex":{"en":"a Buddhist chant","cn":"佛教唱诵"}},{"en":"to sing or shout the same words or phrases many times","cn":"反复唱；反复呼喊","g":"[intransitive, transitive]","ex":{"en":"A group of protesters, chanting and carrying placards, waited outside.","cn":"一群抗议者等候在外面，举着标语牌不停地喊着口号。"},"pos":"verb"},{"en":"to sing or say a religious song or prayer using only a few notes that are repeated many times","cn":"唱圣歌；吟咏祷文","g":"[intransitive, transitive]","ex":{"en":"In a nearby temple, our guide chanted a prayer and lit a stick of incense.","cn":"在附近一座寺庙里，我们的指导者吟咏了祷文，并点燃一炷香。"},"pos":"verb"}]}},"chapel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(教堂里的)私人祈祷室","en":"A chapel is a part of a church which has its own altar and which is used for private prayer.","ex":{"en":"...the chapel of the Virgin Mary.","cn":"圣母堂的私人祈祷室"}},{"pos":"N-COUNT 可数名词","cn":"(附属于医院、学校、监狱的)小教堂","en":"A chapel is a small church attached to a hospital, school, or prison.","ex":{"en":"We married in the chapel of Charing Cross Hospital in London.","cn":"我们是在伦敦查令十字医院的小教堂里结的婚。"}},{"pos":"N-VAR 可变名词","cn":"(基督教某些派别的)教堂，宗教仪式","en":"A chapel is a building used for worship by members of some Christian churches. Chapel refers to the religious services that take place there.","ex":{"en":"...a Methodist chapel","cn":"卫理公会教堂"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small church, or a room in a hospital, prison, big church etc in which Christians pray and have religious services","cn":"小教堂﹔〔医院﹑监狱﹑大教堂等中的〕小礼拜堂"},{"en":"a building where Christians who are Nonconformists have religious services 〔","cn":"英国非国教徒做礼拜的〕教堂"},{"en":"the religious services held in a chapel 〔","cn":"小教堂里的〕礼拜仪式"}]},"vocab":{"pos":"n","senses":[{"en":"A chapel is a place of worship. It's usually smaller than a church, and it has its own altar."}]},"collocations":{"phrases":["ADJ. little, small | side The funeral was conducted in one of the smaller side chapels. | family, hospital, memorial, prison, private, royal","CHAPEL + VERB be dedicated to sb The chapel is dedicated to St Michael.","PREP. in a/the ~ 2 church for some Protestant groups","ADJ. Baptist, Methodist, Nonconformist, etc.","VERB + CHAPEL attend, go to He goes to chapel every Sunday.","PREP. at ~ They are still at chapel (= at a service) . | at a/the ~ They agreed to meet at the chapel after the service."]},"media":{"uk":"media/ldoce/hwd/bre/3/chapel0205.mp3","us":"media/ldoce/hwd/ame/7/chapel.mp3"},"examples":[{"en":"She always went to chapel on Sundays.","cn":"她总是在星期天去教堂做礼拜。"},{"en":"a college chapel","cn":"学院的小教堂"}],"oxford":{"phon":"ˈtʃæpl","pos":"noun","senses":[{"en":"a small building or room where Christians go to pray, attend religious services, etc. in a school, prison, large private house, etc.","cn":"（学校、监狱、私人宅院等基督教徒礼拜用的）小教堂","g":"[countable]","ex":{"en":"a college chapel","cn":"学院的小教堂"}},{"en":"a separate part of a church or cathedral, with its own altar, used for some services and private prayer","cn":"（教堂内的）分堂，小教堂","g":"[countable]","ex":{"en":"a Lady chapel (= a chapel dedicated to Mary, the mother of Jesus)","cn":"圣母堂（供奉耶稣之母马利亚的礼拜堂）。"}},{"en":"the word for a church used in some Christian denominations, for example by Nonconformists in the UK","cn":"（基督教某些教派如英国的非圣公会新教教徒做礼拜的）教堂","g":"[countable, uncountable]","ex":{"en":"a Methodist chapel","cn":"循道宗教堂"}},{"en":"a small building or room used for funeral services, especially at a cemetery or crematorium","cn":"（尤指墓地或火葬场的）殡仪馆，殡仪室","g":"[countable]","ex":{"en":"a chapel of rest","cn":"安息小堂"}},{"en":"a branch of a trade union in a newspaper office or printing house; the members of the branch","cn":"（报馆或印刷所的）工会分会，工会分会会员","g":"[countable + singular or plural verb]","lab":"British English"}]}},"christening":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"洗礼(基督教仪式，表示正式接纳新教徒，并为之命名)","en":"A christening is a Christian ceremony in which a baby is made a member of the Christian church and is officially given his or her name.","ex":{"en":"...my grand-daughter's christening.","cn":"我孙女的洗礼"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a Christian religious ceremony at which a child is officially given a name and becomes a member of a Christian church","cn":"洗礼〔给某人施洗礼命名的仪式〕"}]},"collocations":{"phrases":["VERB + CHRISTENING attend, go to","CHRISTENING + VERB take place","CHRISTENING + NOUN gift, present | mug, spoon | robe/robes | party","PREP. at a/the ~ We all got together at the christening."]},"media":{"uk":"media/ldoce/hwd/bre/d/christening0205.mp3","us":"media/ldoce/hwd/ame/e/laadchristening.mp3"},"oxford":{"phon":"ˈkrɪsnɪŋ","pos":"noun","senses":[{"en":"a Christian ceremony in which a baby is officially named and welcomed into the Christian Church","cn":"（基督教的）洗礼","ex":{"en":"We all got together at the christening.","cn":"我们在洗礼仪式上聚在一起。"}}]}},"chord":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"和弦;和音","en":"A chord is a number of musical notes played or sung at the same time with a pleasing effect.","ex":{"en":"...the opening chords of 'Stairway to Heaven'.","cn":"《通往天堂的阶梯》的开篇和弦"}},{"pos":"PHRASE 短语","cn":"激起共鸣;触动心弦","en":"If something strikes a chord with you, it makes you feel sympathy or enthusiasm.","ex":{"en":"Mr Jenkins' arguments for stability struck a chord with Europe's two most powerful politicians","cn":"詹金斯先生关于稳定的论点引起了欧洲两位最有影响的政治家的共鸣。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a combination of several musical notes that are played at the same time and sound pleasant together 〔","cn":"音乐的〕和弦﹐和音"},{"en":"to do or say something that people feel is familiar or true","cn":"引起（某人）内心共鸣﹐触动（某人的）心弦"},{"en":"a straight line joining two points on a curve 〔","cn":"弧线的〕弦"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"In music, a chord is three or more notes that combine harmoniously. You can play chords on a piano or guitar, but not on an instrument that plays one note at a time, like a trumpet."}]},"collocations":{"phrases":["ADJ. major, minor | C, D, etc. | augmented, diminished a diminished 7th chord | dominant, tonic, etc. | 7th, 9th, etc. | full | broken | jaz","VERB + CHORD play, strum","CHORD + NOUN change, progression, sequence"]},"media":{"uk":"media/ldoce/hwd/bre/6/chord0205.mp3","us":"media/ldoce/hwd/ame/8/chord1.mp3"},"examples":[{"en":"The speaker had obviously struck a chord with his audience.","cn":"讲演者显然已引起了听众的共鸣。"},{"en":"Many of the things she says will strike a chord with other young women.","cn":"她说的许多话都能引起其他年轻女子的共鸣。"}],"oxford":{"phon":"kɔːd","pos":"noun","senses":[{"en":"three or more notes played together","cn":"和弦；和音","lab":"music"},{"en":"a straight line that joins two points on a curve","cn":"弦","lab":"mathematics"}]}},"chunk":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"厚块;大块","en":"Chunks of something are thick solid pieces of it.","ex":{"en":"They had to be careful of floating chunks of ice.","cn":"他们必须当心大块浮冰。"}},{"pos":"N-COUNT 可数名词","cn":"大量;大部分","en":"A chunk of something is a large amount or large part of it.","ex":{"en":"The company owns a chunk of farmland near Gatwick Airport.","cn":"该公司拥有盖特威克机场周边的大片农田。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of something that has been cut or separated from the main part","cn":""},{"en":"a piece. Bit is more informal than piece and is often used about smaller pieces","cn":""},{"en":"a small piece of something solid or firm that does not have a regular shape","cn":""}]},"collocations":{"phrases":["ADJ. big, great, huge, large, sizeable, substantial He bit a great chunk out of the apple. This one project has taken a substantial chunk of","VERB + CHUNK cut sth (up) into","PREP. in a/the ~ I bought th e cheese in one big chunk. | ~ of a huge chunk of meat/rock/tex t"]},"media":{"uk":"media/ldoce/hwd/bre/4/chunk0205.mp3","us":"media/ldoce/hwd/ame/b/chunk.mp3"},"examples":[{"en":"I've already written a fair chunk of the article.","cn":"我已写出文章的大部分。"},{"en":"a chunk of cheese/masonry","cn":"一块厚厚的奶酪/砖石"}],"oxford":{"phon":"tʃʌŋk","pos":"noun","senses":[{"en":"a thick, solid piece that has been cut or broken off something","cn":"厚块；厚片；大块","ex":{"en":"a chunk of cheese/masonry","cn":"一块厚厚的奶酪／砖石"}},{"en":"a fairly large amount of something","cn":"相当大的量","lab":"informal","ex":{"en":"I've already written a fair chunk of the article.","cn":"我已写出文章相当大的部分。"}},{"en":"a phrase or group of words that can be learnt as a unit by somebody who is learning a language. Examples of chunks are ‘Can I have the bill, please?’ and ‘Pleased to meet you’.","cn":"语块（话语组成部分）","lab":"linguistics","ex":{"en":"The listening texts consist of short, bite-sized chunks which are accessible to beginners.","cn":"听力文本由简短的块组成，适合初学者。"}}]}},"chestnut":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"栗子树","en":"A chestnut or chestnut tree is a tall tree with broad leaves."},{"pos":"N-COUNT 可数名词","cn":"栗子","en":"Chestnuts are the reddish-brown nuts that grow on chestnut trees. You can eat chestnuts."},{"pos":"COLOUR 颜色词","cn":"栗色;红棕色","en":"Something that is chestnut is dark reddish-brown in colour.","ex":{"en":"...a woman with chestnut hair.","cn":"栗色头发的女子"}},{"pos":"PHRASE 短语","cn":"老掉牙的话(或故事、笑话);老一套","en":"If you refer to a statement, a story, or a joke as an old chestnut or a hoary chestnut, you mean that it has been repeated so often that it is no longer interesting.","ex":{"en":"...that old chestnut, the war between man and machines.","cn":"又是老掉牙的故事：人机大战"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a smooth red-brown nut that you can eat","cn":"栗子"},{"en":"the tree on which this nut grows","cn":"栗子树"},{"en":"a red-brown colour","cn":"栗色﹐红棕色"}]},"collocations":{"phrases":["ADJ. bright, glossy, rich | dark, deep •"]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdechestnut.mp3","us":"media/ldoce/hwd/ame/0/chestnut1.mp3","img":["media/thumb/chestnut.jpg"]},"examples":[{"en":"roast chestnuts","cn":"炒板栗"},{"en":"her chestnut hair","cn":"她的红棕色头发"}],"oxford":{"phon":"ˈtʃesnʌt","pos":"noun","senses":[{"en":"a large tree with spreading branches that produces smooth brown nuts inside cases that are covered with spikes. There are several types of chestnut tree.","cn":"栗树","g":"[countable]"},{"en":"a smooth brown nut of a chestnut tree, some types of which can be eaten","cn":"栗子；板栗","g":"[countable]","ex":{"en":"roast chestnuts","cn":"炒板栗"}},{"en":"a deep red-brown colour","cn":"栗色；深红棕色","g":"[uncountable]"},{"en":"a horse of a red-brown colour","cn":"栗色马；红棕马","g":"[countable]"},{"en":"an old joke or story that has been told so many times that it is no longer funny or interesting","cn":"陈腐的笑话；老掉牙的故事","g":"[countable]","lab":"informal"},{"en":"red-brown in colour","cn":"栗色的；红棕色的","pos":"adjective"}]}},"challenger":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(职位或头衔的)挑战者","en":"A challenger is someone who competes with you for a position or title that you already have, for example being a sports champion or a political leader.","ex":{"en":"Draskovic has emerged as the strongest challenger to the leader of the Serbian government","cn":"德拉什科维奇一跃成为塞尔维亚政府领导人最大的挑战者。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to refuse to accept that something is right, fair, or legal","cn":""},{"en":"to invite someone to compete or fight against you, or to try to win something","cn":""},{"en":"to test the skills or abilities of someone or something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Challengers don’t let things stay the way they are, they go against something already in place, like a rule or the score on the scoreboard. Or they go after the same thing you may want, like victory in a competition or even the parking spot you were waiting for."}]},"collocations":{"phrases":["ADJ. closest, main, nearest, serious, strong Her nearest challenger is the vice-president.","VERB + CHALLENGER take on He took on various challengers, but refused to fight Jackson.","PREP. ~ for the main challengers for the European title | ~ to a challenger to the prime minister"]},"media":{"uk":"media/ldoce/hwd/bre/2/challenge_n0205.mp3","us":"media/ldoce/hwd/ame/0/challenge1.mp3"},"examples":[{"en":"the official challenger for the world championship title","cn":"世界冠军头衔的正式挑战者"},{"en":"a boy with a reputation for challenging the authority of his teachers","cn":""}],"oxford":{"phon":"ˈtʃælɪndʒə(r)","pos":"noun","senses":[{"en":"a person who competes with somebody else in sport or in politics for an important position that the other person already holds","cn":"（体育运动或政治的）挑战者","ex":{"en":"the official challenger for the world championship title","cn":"世界冠军头衔的正式挑战者"}},{"en":"the name of the US space shuttle (= spacecraft that can be used again) which exploded in the air on 28 January 1986 and killed all seven astronauts in it. This disaster was seen on television by millions of people and resulted in flights with astronauts being stopped for two years. There were other Challenger spacecraft.","cn":"“挑战者”号航天飞机美国航天飞机，1986年1月28日在空中爆炸，机上七名航天员全部遇难。数百万人在电视上目睹了这场灾难，此事件导致载人航天飞行停止两年。另有其他以“挑战者”命名的航天器。","pos":""}]}},"cherry":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"樱桃","en":"Cherries are small, round fruit with red skins."},{"pos":"N-COUNT 可数名词","cn":"樱桃树","en":"A cherry or a cherry tree is a tree that cherries grow on."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small round red or black fruit with a long thin stem and a stone in the middle","cn":"樱桃"},{"en":"the tree on which this fruit grows","cn":"樱桃树"},{"en":"the wood of this tree, used for making furniture","cn":"樱桃木"}]},"collocations":{"phrases":["ADJ. black, red | glace, morello | juicy, sour, sweet","QUANT. bunch","CHERRY + NOUN stone •"]},"media":{"img":["media/ldoce/img/cherries.jpg","media/thumb/cherry.jpg"],"uk":"media/ldoce/hwd/bre/6/cherry0205.mp3","us":"media/ldoce/hwd/ame/6/cherry.mp3"},"examples":[{"en":"a winter-flowering cherry","cn":"冬季开花的樱桃树"},{"en":"cherry blossom","cn":"樱花"}],"oxford":{"phon":"ˈtʃeri","pos":"noun","senses":[{"en":"a small soft round fruit with shiny red or black skin and a large seed inside","cn":"樱桃","g":"[countable]"},{"en":"a tree on which cherries grow, or a similar tree, grown for its flowers","cn":"樱桃树；樱花树","g":"[countable]","ex":{"en":"cherry blossom","cn":"樱花"}},{"en":"the wood of the cherry tree","cn":"樱桃木","g":"[uncountable]"},{"en":"a bright red colour","cn":"樱桃色；鲜红色；朱红色","g":"[uncountable]"},{"en":"bright red in colour","cn":"樱桃色的；鲜红的；朱红的","ex":{"en":"cherry lips","cn":"樱唇"},"pos":"adjective"}]}}});
